window.__D("text/torat-shmuel/c034",{"p":[[2000460384,"שאוכל דבר היתר ובכח האכילה לומד ומתפלל ומעלה את המאכל למקורה ושרשה שזהו ג\"כ ענין יחוד מ\"ה וב\"ן, והוא ע\"ד מה שאנו אומרים קודם עשיות המצות לשם יחוד קוב\"ה ושכינתי', ששכינתי' הו\"ע ב\"ן וקוב\"ה הו\"ע מ\"ה, שזהו ג\"כ ענין יחוד מ\"ה וב\"ן, ולמה הסיפור של עבדי בתי אבות הם באריכות וגופי תורה הם ברמיזא הלא גופי תורה הם ג\"כ ענין יחוד מ\"ה וב\"ן. והענין הוא שהסיפור של אבות הם ענין כלל, ומצות הם ענין פרט, ואין ערך פרט לגבי כלל, והוא ע\"ד ר\"ה שנק' ראש לכל השנה שהוא יום הדין ומלאכים יחפזון שבו נקצבו חיות לכל השנה, אף כי המחדש בטובו בכל יום תמיד מעשה בראשית, ולאו בכל יום דוקא אלא בכל עת ורגע כמ\"ש לרגעים תבחננו, מ\"מ הוא ראש לכל השנה, וכמו ר\"ח שהוא ראש לשלשים יום ואינו נק' בכתוב יום המעשה, אף כי מותר בעשיות מלאכה אך זהו מפני שהוא ראש וכלל לל' יום שדיבור מקבל אז מחכמה<sup data-n=\"1211\">12</sup>, אבל ר\"ה שהוא כלל יותר גדול שהוא כלל לכל השנה הוא אסור בעשיות מלאכה מן התורה ונק' יו\"ט. וכן עד\"ז באדם יש אברים פרטיים ויש אברים כללים, דהיינו מוח ולב וכבד שנקובתן במשהו שהם ענין כלל, אף שבכל האברים הוא החיות, מ\"מ אינו דומה, כי כשחותכין היד או הרגל ח\"ו יכול לחיות, אבל בג' אברים הללו תלוי עיקר החיות שהלב פליג לכל שייפין שהו\"ע כלל.\n<b>ובזה</b> יובן מעלת הכלל על הפרט שיפה שיחתן של עבדי בתי אבות מפני שזהו ענין כלל, אבל תורתן של בנים הו\"ע פרט ואין ערך פרט לגבי כלל. ושרש הענין הוא שאורייתא מחכ' נפקת, וחכ' הוא ענין צמצום דיו\"ד שהוא נקודה חדא כמ\"ש אנת הוא חכים, דכדי שיהי' מאנת בחי' חכים צ\"ל צמצום, ואין הפי' צמצום, צמצום גמור אלא פי' צמצום כמארז\"ל לעולם ישנה אדם לתלמידו בדרך קצרה, והוא עד\"מ שיש לרב שכל עמוק ואין התלמיד יכול לקבלו כמו שהוא בשכל הרב, מצמצם הרב את עצמו בדרך קצרה, ובאמת עצם השכל הרי יש בהצמצום כי אחר כך מבין התלמיד את השכל כמו שהוא בשכל הרב. ולכן המצות שהם ענין חכ' שהו\"ע צמצום ניתנו ברמיזא ובקיצור הרבה גופי תורה, אבל שיחתן של עבדי בתי אבות כתי' באריכות מפני שהגיע למדריגה גבוה שהוא ענין א\"א, כמו לע\"ל שיהי' יום שכולו ארוך שהו\"ע א\"א, וגם קרבנות כתי' ג\"כ באריכות בתורה מפני שקרבן הוא גימט' ארך אפים שהוא ג\"כ ענין א\"א.\n<b>ומעתה</b> יובן מה שדרש ר' שמלאי תרי\"ג מצות נאמרו למשה מסיני רמ\"ח מ\"ע ושס\"ה מל\"ת ובא דוד והעמידן על אחד עשר, שלא בא ח\"ו לגרוע מהם אלא העמידן על אחד עשר כללים שע\"י הי\"א כללים יכולין לבוא לקיים כל התרי\"ג מצות, והציע דברים שיש למעלה ג\"כ, כמו הולך תמים שלמעלה הוא הצור תמים פעלו, פועל צדק למעלה הו\"ע הוי' צדקות אוהב, צדיק הוי' בכל דרכיו, לא עשה לרעהו רעה, וינחם ה' על הרעה, שזהו ענין כללים. אך צ\"ל מה שחשיב בהי\"א",[["1211","12","<b>ר\"ח. . ואינו נק' בכתוב יום המעשה. . שדיבור מקבל אז מחכמה</b>: ראה בכ\"ז בארוכה סה\"מ תרל\"ב ח\"א ע' ס. וש\"נ. וע' סה. [ובהנסמן שם בתחילת המאמר]."]]],[2000460385,"כללים וכספו לא נתן בנשך, הלא אין זה כלל אלא פרט. אך הנה ביום הכפורים אומרים כל ישראל על חטא שחטאנו לפניך בנשך ובמרבית, לכאורה הלא יש עני שאינו לווה ואינו מלוה בריבית מה הוא אומר על חטא הלא אין בו החטא הזה. אך מ\"מ יכול כאו\"א למצוא בעצמו החטא באופן אחר ע\"ד מארז\"ל אין נשך בלא תרבית ואין תרבית בלא נשך, פי' נשך הוא כמארז\"ל אם השיך הנחש בלי לחש, שקודם הנחש לא הי' תאות לא מבעי תאות איסור בודאי לא הי' אלא אפי' תאות היתר לא הי', ואחר הנחש נתהוה התאות, וזהו ענין נשך, אין נשך בלא תרבית מאחר שעושין נשך בקדושה נעשה ריבוי בקליפה, נמצא שכל או\"א יכול למצוא בו החטא באופן כזה. ואח\"כ בא ישעי' והעמידן על שש ואח\"כ על שתים, עד שבא חבקוק והעמידן על אחת וצדיק באמונתו יחי' שע\"י שיהי' באיש ישראלי חיות באמונה יכול לבוא לקיים כל התרי\"ג מצות."],[2000460386,"<h3>לריח שמניך</h3>\n<b></b><b>בס\"ד, הנחה פ' ויקרא שנת תרל\"ט.</b>\n<b>לריח</b> שמניך<sup data-n=\"1212\">1</sup> טובים שמן תורק שמך ואי' במדרש כל המצות שעשו אבות אינם אלא ריחות אבל אנו שמן תורק שמך רמ\"ח מ\"ע ושס\"ה ל\"ת. וצ\"ל מפני מה המצות שעשו אבות אינן אלא ענין ריח ומצות שלנו הם עצמי'. ועוד צ\"ל משארז\"ל במד\"ר ע\"פ ששים המה מלכות ושמונים פלגשים ועלמות אין מספר אחת היא יונתי פי' ששים מלכות היינו ס' מסכתות, ושמונים פילגשים היינו ברייתות ועלמות אין מספר היינו המימרות והלכות שבגמ', אחת היא יונתי היינו כנס\"י, משמע מזה שכנס\"י הם גדולים מאורייתא שנק' בש' אחת, והלא אי' בזהר תלת קשרין מתקשרין דא לדא ישראל באוריי' ואוריי' בקוב\"ה משמע שאוריי' הוא מדריגה גבוה מישראל שע\"י אמצעות התורה מתקשרין כנס\"י בקוב\"ה.\n<b>אך</b> להבין כ\"ז צ\"ל תחילה מ\"ש וידבר אלקים אל משה ויאמר אליו כו' וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי להם. וצ\"ל מה זו תשובה על הטענה הקודמת שטען משה אדני למה הרעותה לעם הזה והשיב וארא מה היא התשובה. ועוד צ\"ל מה שאמר משה להקב\"ה למה הרעותה לעם הזה האיך בא משה לומר דבר שכנגדו ית'. ואי' במד\"ר על הטענה שאמר להקב\"ה אדני למה הרעותה כך אמר לפני הקב\"ה נטלתי ספר בראשית וראיתי בו שמעשה דור המבול דין הי' ודור",[["1212","1","<b>לריח שמניך</b>: הנחה מד\"ה ששים המה מלכות, הנדפס לעיל ע' קיא. ההנחה שלפנינו נמצאת בכת\"י מס' 1185 [ורשום ע\"ז: ”מה ששמעתי בהיותי פעם ראשונה בליובאוויץ מאת אדמו\"ר שליט\"א\". וניכר שזהו כותרת המעתיק בלבד ולא רשימת המניח עצמו].\nהמ\"מ להמאמר, ראה לעיל בפנים הספר ולעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."]]],[2000460387,"הפלגה ומעשה סדום דין הי', ופי' מתנות כהונה דין אמת, אבל אלו מפני מה נשתעבדו. ועוד אי' במד\"ר פ' וארא ע\"פ ופניתי אני לראות חכ' הוללות וסיכלות כי מה האדם שיבוא אחר המלך את אשר כבר עשהו ודרשו שם שקאי על שלמה ומשה, על שלמה שנתחכם כנגד חכמת התורה, ועל משה שאמר אד' למה הרעותה מסיק שם שחכ' ודעת של משה הוא מהוללות וסיכלות כי מה האדם שיבוא אחר המלך את אשר כבר עשהו, כי מה לו לחשוב אחר גזירות המלך.\n<b>ולהבין</b> כ\"ז צ\"ל מ\"ש וארא אל אברהם באל שדי ושמי הוי' לא נודעתי, הלא יש כמה פעמים ש' הוי' אצל אברהם שאפי' בעת שהי' שמו אברם<sup data-n=\"1213\">2</sup> מצינו ג\"כ אצלו ש' הוי' כמ\"ש ויאמר הוי' אל אברם לך לך, וארא אל אברם, והוי' אמר המכסה אני מאברם. אך הענין הוא הנה כתי' ויקרא הוי' הוי' ופסיק טעמא בגווייהו ואי' בזהר דהפסיק טעמא הוא ע\"ד מ\"ש יהי רקיע בתוך המים ויהי מבדיל בין מים למים, ויש שם שני הבדלות הא' יהי רקיע בתוך המים ויהי מבדיל והשני ויעש אלקים את הרקיע ויבדל, והשני הבדלות אלו הא' הוא ע\"ד מ\"ש והבדילה הפרוכת בין קודש לקה\"ק, והשני הוא בין קודש לחול, והגם שבגמ' חשיב שם ז' הבדלות, אך זהו בדרך פרט ובכלל הם ב' הבדלות בין קודש לקדה\"ק ובין קודש לחול.\n<b>ולהבין</b> זה צ\"ל תחילה פי' של ש' הוי', שיש כמה שמות, אלקים הוא לשון דיין, וא\"ל הוא כח ויכולת, שד\"י שאמר לעולמו די, ומהו פי' של הוי'. הנה הוי' הוא לשון מהוה שהוא מקור כל ההויות שממנו נתהוה עולמות, כי הנה יש ענין השתל' עילה ועלול ה\"ז ע\"ד השתל' ברוחניות אבל להיות ענין בריאה יש מאין צ\"ל דוקא ע\"י ש' הוי', לפיכך יש בש' הוי' יו\"ד בראשו שיו\"ד הו\"ע צמצום כי בכדי שיוכל להיות בריאה יש מאין אפי' בחי' בראתיו יצרתיו אף עשיתיו צ\"ל ע\"י צמצום דוקא, ואח\"כ ה' התפשטות, וא\"ו המשכה, עד שיוכל להיות ה' אחרונה בהבראם בה' בראם שש' הוי' הוא מקור כל ההויות. ואף שהוא מקור כל ההויות מ\"מ הוא קדוש ומובדל מגדר עולמות, לא כמו הנשמה שממלא את כל הגוף ה\"ה מתלבשת בגוף ומתפעלת ממקרי הגוף, אבל ש' הוי' הוא קדוש ומובדל מגדר עולמות, ואעפ\"י שהוא קדוש ומובדל מ\"מ ה\"ה מהוה את העולמות, וזהו\"ע הוי' תתאה, אבל הוי' עילאה שם לא שייך לומר עולמות אלא כלול בעצמותו והוא עד\"מ כמו שבאדם יש בו מחשבה ודיבור, דיבור הוא לזולתו, אבל מחשבה הוא צפון ונעלם, וזהו\"ע הוי' עילאה שהוא כלול בעצמות. וזהו\"ע מ\"ש עד שלא נברא העולם הי' הוא ושמו בלבד, כי מיד שעלה ברצונו לברא את העולם מיד נבראו אלא שהי' כלולים בעצמו', וזהו פי' עד שלא נברא העולם הי' הוא ושמו אחד שש' הוי' הי' כלול בעצמו'. ותיבת הוא, הוא ג\"כ ר\"ת הוא ושמו אחד, שהי' השם כלול בעצמו', וזהו\"ע ב' שמות הוי'. וזהו פי' וארא אל אברהם באל שדי ושמי הוי' לא נודעתי, והגם שמצינו כמה פעמים ש' הוי' אצל אברהם, זהו רק הוי' תתאה שבאל שדי שאמר לעולמו די, אבל הוי' עילאה",[["1213","2","<b>וארא אל אברם</b>: הוא טעות בכת\"י המעתיק כאן. ואוצ\"ל: וירא ה' אל אברם (לך לך יב, ז)."]]],[2000460388,"לא נתגלה להם. ומפני זה ניחא מה שכתי' לא נודעתי ולא כתי' לא הודעתי שעפ\"י כללי הדקדוק הי' צריך לכתוב לא הודעתי אבל עכשיו שקאי על ש' הוי' עילאה לכן כתי' לא נודעתי, אבל אחר מ\"ת כתי' לכן אמור לבנ\"י אני הוי' שנתגלה להם הוי' דלעילא.\n<b>אך</b> צ\"ל מפני מה אנו משיגים ש' הוי' עילאה והם לא השיגו רק ש' הוי' תתאה. אך הענין הוא כי הנה כתיב עם לבן גרתי ופרש\"י תרי\"ג מצות שמרתי, וכן ארז\"ל במשנה קיים אברהם אבינו את כל התורה עד שלא ניתנה, וצ\"ל איך קיימו את המצות הלא יש מצות כמו מצות תפלין שתפילין היא מצוה גדולה וגבוה וניתנה בד' בתים קדש והי' כי יביאך כו' ומה כתי' בה ענין יצ\"מ, ומאחר שלא הי' עדיין השיעבוד האיך שייך סיפור יצ\"מ, ועד\"ז כל המצות. אך להבין מצות שלהם צ\"ל תחילה המצות שלנו. כי ענין המצות שלנו הו\"ע רמ\"ח פקודין אינון רמ\"ח אברין דמלכא, וצ\"ל הלא אין לו גוף ולא דמות הגוף ואיך שייך לומר אברים. אך הנה ענין אבר הו\"ע כלי, כמו שאברים הם כלים להשראת החיות כך המצות הם כלים להשראת אוא\"ס, ויש למעלה בחי' אדם כמו למטה, כמו למטה אדם נחלק לג' כלים ראש גוף ורגל, ראש הוא חב\"ד וגוף הו\"ע חג\"ת ורגל הו\"ע נה\"י, ובפרט יש רמ\"ח אברים, כך למעלה כתיב בצלם אלקים עשה את האדם, שבכלל נחלק לג' כלים חב\"ד חג\"ת נה\"י, ובד\"פ יש רמ\"ח שז\"א הוא בעל ט' ספי' ט' פעמים ט' עולה פ\"א ראש תוך סוף הוא רמ\"ג וה' חסדים המגדילים הם רמ\"ח וזהו רמ\"ח פקודין אינון רמ\"ח אברים דמלכא, והאבות ע\"י העבודה שלהם נעשו מרכבתא עילאה לבחי' אדם העליון ע\"ד מ\"ש והחיות נושאות את הכסא ודמות כמראה אדם שעל הכסא, שהחיות ע\"י ביטול שלהם מנשאות את הכסא ודמות כמראה אדם שעל הכסא, רק שם נאמר כ\"א דמות כמראה אדם שזהו רק דמות מחמת שהמלאכים הם בבריאה בלבד וברי' לגבי אצי' אין לה ערוך כלל שבאצי' שם הוא הפרשת אוא\"ס ושם בחי' אדם גופא, והאבות ע\"י ביטולם ומס\"נ כמ\"ש בעשרה נסיונות נתנסה אברהם אבינו שהם כנגד עשרה כוחות הנפש עי\"ז נעשו האבות מרכבתא עילאה לאדם גופא דאצי' וזהו בדרך כלל. ובד\"פ אברהם הי' מרכבה לבחי' החסד ויצחק למדת הגבורה ויעקב הי' כלול משניהם. וזהו\"ע מ\"ש כי יעקב בחר לו יה ישראל לסגולתו, וענין לסגולתו הוא ע\"ד והייתם לי סגולה, כי המצות הם ענין סגולה, כי ענין סגולה הוא למעלה מטו\"ד כי אין אנו מבינים מפני מה זה מ\"מ ה\"ז סגולה, כך מצות הם ג\"כ למעלה מטו\"ד כגון מצות תפילין שע\"י שמניח הד' בתים ממשיך ד' מוחין, ומה הם הד' מוחין והאיך ממשיכים אותם אין אנו יודעים מ\"מ הרי ממשיכים. וזהו פי' כי יעקב בחר לו יה ישראל לסגולתו ויש בו ב' פי' הא' שיעקב בחר לו י\"ה והב' שי\"ה בחר לו יעקב כדי שיהי' לאחר מ\"ת ישראל לסגולתו, שיעקב הי' הכנה למ\"ת.\n<b>ומעתה</b> יובן מ\"ש וארא אל אברהם כו' ושמי הוי' לא נודעתי הגם שנזכר אצלו ש' הוי' אך זהו רק הוי' תתאה שבאל שדי שאמר לעולמו די אבל ש' הוי' עילאה לא נודעתי, מפני שאבות קיימו המצות בלא ציווי אלא מעצמן בביטול"],[2000460389,"כמארז\"ל קיים עד שלא ניתנה, ונברא בביטול שלו אינו יכול להשיג אלא עד מקור הנבראים שזהו ש' הוי' תתאה אבל ש' הוי' עילאה שהוא למעלה ממקור הנבראים אינו יכול להשיג, אבל אחר מ\"ת ניתנו לנו במתנה שנוכל להשיג גם ש' הוי' דלעילא, ולכן נק' בשם מתן תורה שהו\"ע מתנה שניתן לנו במתנה להשיג ש' הוי' עילאה. ועוי\"ל שמפני זה אנו יכולים להשיג ש' הוי' דלעילא משום שניתנו לנו המצות בעשי' גשמי' ועשי' היא לעילא כמ\"ש והוי' פקד את שרה ויעש הוי' לשרה, והוי' פקד אני וב\"ד ועל ויעש אי' בזהר איהו בלחודוהי נמצא שעשי' היא לעילא, וכמ\"ש על לע\"ל עדן עין לא ראתה אלקים זולתיך יעשה למחכה לו משמע מזה ג\"כ שעשי' היא לעילא, כמו עד\"מ באדם יש דיבור ומעשה שדיבור הוא שלא נעשה דבר אבל מעשה הלא דבר הוא, ולכן אנו שניתנה לנו התורה בעשי' יכולים להשיג ש' הוי' עילאה אבל האבות שקיימו התורה ברוחניות לא השיגו רק ש' הוי' תתאה.\n<b>ולבאר</b> היטב ענין זה צ\"ל מ\"ש הללויה הללו ש' הוי' הללו עבדי הוי' ופעם נא' הללו עבדי הוי' הללו את ש' הוי', נמצא שיש למעלה ענין הילול ושבח, ולכאו' צ\"ל הלא כתי' מי כמוך כו' נורא תהלות היינו יראים מלהללו. אלא שבהלול יש בו ב' פי' הא' הו\"ע הילול ושבח והב' לשון בהילו נרו על ראשי שהו\"ע המשכות האור. ובאמת שניהם הם אמת כי ע\"י הילול ושבח ממשיכים האור, כמו עד\"מ אדם אעפ\"י שהוא חכם גדול מ\"מ חכמתו הוא צפון ונעלם רק ע\"י הילול ושבח שמשבחים אותו נתגלה חכמתו, וכן במדות שכשאדם הוא חסדן או נדבן ה\"ה צפון אצלו המדות רק ע\"י הילול ושבח נתגלה, כמו\"כ למעלה. רק שזהו שייך באדם שיש בו מדות רק שהי' בהעלם וע\"י הילול ושבח מתגלה מהעלם אל הגילוי, אבל למעלה ששם הוא לאו מכל אינון מדות כלל, וע\"י הילול ושבח ממשיכים מלאו מכל אינון מדות במדות. וזהו\"ע מ\"ש וידבר הוי' אל משה, וידבר אלקי' אל משה, הוי' הוא מדת הרחמים אלקי' הוא מדת הדין, ובכדי שיוכל להיות המדות זהו ע\"י הילול ושבח יכול להמשיך מלאו מכל אינון מדות במדות, כדי שיהי' מה רב טובך אשר צפנת ליריאיך חנון ורחום הוי'. וזהו מ\"ש הללויה שע\"י הילול ושבח ממשיכים י\"ה, הללו את ש' הוי' שע\"י הילול ושבח נמשך ו\"ה ונעשה שם שלום, וזהו ע\"י הללו עבדי הוי' שע\"י ההילול שבבחי' עבודה בביטול באמת נמשך שיהי' שם שלם. וזהו דוקא בהוי' תתאה אבל הוי' עילאה שם נא' נורא תהילות יריאים מלהללו, אלא ע\"י ההודאה שהו\"ע עצמי' יכולין להמשיך ש' הוי' עילאה שהוא כלול בעצמי'. ולכן בחנוכה קבעוה בהלל ובהודאה, שע\"י הילול ושבח ממשיך הוי' תתאה וע\"י הודאה ממשיך ש' הוי' דלעילא.\n<b>ומעתה</b> יובן מ\"ש וידבר הוי' אל משה וארא אל אברהם באל שדי ושמי הוי' לא נודעתי, שמה שנזכר אצלו ש' הוי' אינו אלא הוי' תתאה וש' הוי' דלעילא לא נתגלה להם, אבל אחר מ\"ת כתי' לכן אמור לבנ\"י אני הוי' שנתגלה להם הוי' דלעילא. ובזה ניחא מה שאי' במד' לריח שמניך טובים שמן תורק שמך שכל המצות שעשו אבות אינן אלא ריחות אבל אנו שמן תורק שמך רמ\"ח מ\"ע ושס\"ה ל\"ת, שכל"],[2000460390,"המצות שעשו אבות אינן אלא ריחות, מפני שהמה לא השיגו אלא הוי' תתאה שהוא בחי' ריח שריח לא מלתא, היא שאפי' במאכלים האסורים ג\"כ ריחא לאו מלתא, אבל אנו שמן תורק שמך רמ\"ח מ\"ע ושס\"ה ל\"ת כדבר שמריקין מכלי אל כלי שהוא עצמי' כך ע\"י רמ\"ח ושס\"ה ל\"ת אנו יכולין להשיג ש' הוי' דלעילא שכלול בעצמי'."],[2000460391,"<h3>ששים המה מלכות</h3>\n<b></b><b>בס\"ד פ' צו, שנת תרל\"ט לפ\"ק</b>\n<b>ששים</b> המה מלכות<sup data-n=\"1214\">1</sup> ושמונים פילגשים ועלמות אין מספר, הנה בכלל הפסוק הזה קאי על תושבע\"פ שאי' במד\"ר ששים המה מלכות היינו ס' מסכתות ושמונים פלגשים קאי על ברייתות ועלמות אין מספר קאי על מימרות והלכות שבגמרא אחת היא יונתי קאי על כנס\"י, משמע מזה שכנס\"י הם גדולים ממדריגת התורה שנק' בש' אחת וצ\"ל הלא אי' תלת קשרין מתקשרין דא בדא ישראל באוריי' ואוריי' בקוב\"ה. אלא לפי האמת שניהם הם אמת. ולהבין זה צ\"ל תחילה מ\"ש וארא אל אברהם ואל יצחק באל שדי ושמי הוי' לא נודעתי, ונת' שמה שכתי' לא נודעתי קאי על הוי' דלעילא ולכן נא' לא נודעתי ולא כתי' לא הודעתי, אבל לאחר מ\"ת כתי' לכן אמור לבנ\"י אני הוי' שנתגלה אז הוי' דלעילא. וצ\"ל מה זו תשובה על הטענה שטען משה אד' למה הרעותה לעם הזה, ואי' במד\"ר שכך היתה טענת משה נטלתי ספר בראשית וראיתי בו שמעשה דור הפלגה דין היתה פי' דין אמת אבל אלו מה חטאו, ומה השיב לו וארא אל אברהם כו' מהו תשובה על מה שטען. אך הענין הוא שלא יכלו ישראל לקבל את התורה ושיתגלה הוי' דלעילא אלא ע\"י אבן בוחן דמצרים, שע\"י שעבוד מצרים יכלו לקבל את התורה. והוא ע\"ד מ\"ש במד\"ר על פסוק זית רענן יפה פרי תואר קרא הוי' שמך, ואמרו מפני מה נמשל לזית הלא יש אילנות משובחים ובאמת נמשלו ישראל להם. הענין הוא כי מה זית אינו מוציא שמנו עד שמגרגרין אותו וכותשין אותו ובותשין אותו אז מוציא שמנו, כך ישראל אינם יכולים לבוא לידי תשובה עד שכותשין אותם וכופתין אותם אז באים לידי תשובה כמ\"ש ויאנחו בנ\"י מן העבודה ותעל שועתם אל האלקים, בצר לך ומצאוך ושבת עד הוי' אלקיך, וגם זה הי' השעבוד דמצרים כדי שיוכלו ישראל לקבל את התורה, אך צ\"ל אלו מה חטאו מפני מה דור הזה דוקא.",[["1214","1","<b>ששים המה מלכות</b>: הנחה מד\"ה ”אך הנה כדי שיוכלו לקבל התורה\" לעיל בהספר ע' קטז. ולעיל נדפס גם הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ממאמר זה (שם רק חלק מהמאמר). ההנחה שלפנינו נמצאת בכת\"י מס' 1185 [ורשום שם ע\"ז: הנחה מה ששמעתי מאת כ\"ק אדמו\"ר שליט\"א בהיותי בליובאוויץ שנת תרל\"ט לפ\"ק].\nהמ\"מ למאמר זה נמצאים לעיל על המאמר בפנים הספר, ועל הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."]]],[2000460392,"<b>אך</b> הנה אי' בפע\"ח שנשמות שהי' בשעבוד מצרים הי' גלגול דור הפלגה וע\"י השעבוד נזדכך החטא שלהם, לכן מה הי' החטא שלהם של דור הפלגה הוא כמ\"ש ותהי להם הלבינה לאבן לכן השעבוד שלהם הי' ג\"כ בחומר ובלבינים, ולכן אמר פרעה ואת תוכן הלבינים תתנו לא תגרעו, היינו שכמספר האבנים שעשו במגדל בעת החטא כך נעשה ג\"כ במצרים בעת הזיכוך, וע\"י הזיכוך נזדכך החטא.\n<b>אך</b> יש להקשות על פע\"ח ממשנה דסנהדרין שאי' שם שדור הפלגה אין להם חלק לעוה\"ב כמ\"ש ויפץ הוי' אותם ומשם הפיצם, פי' משם הפיצם מעוה\"ב. והכא משמע שנזדככו ע\"י השעבוד של מצרים. אך יש לתרץ שמה שאמר שאין להם חלק לעוה\"ב היינו עולם התחי' שיתלבשו נשמות בגופים זה אין להם, אבל הנשמה עצמה נתקן בשעבוד מצרים, כי הנשמה בעצמה נמשכה ממקום גבוה ע\"ד מ\"ש וירד הוי' לראות את העיר ואת המגדל אשר בנו בני האדם, אמר ר' ברכי' וכי בני חמרייא או בני גמלייא הוה ומאי כתי' בני אדם, אלא בני אדם קדמאה, שנשמתן הי' משרש גבוה רק שנפלו בשבה\"כ ובאו לבנות עיר ומגדל, כי דבר שניטל משרש גבוה נופל בשבה\"כ למקום נמוך דוקא, ע\"ד ופני ארי' אל הימין שהוא למעלה משרש גבוה ולמטה ע\"י שבה\"כ נעשה חיה טמאה, מפני זה יכול להיות שהנשמה שלהם יזדכך שזהו ע\"י השעבוד דמצרים נזדככו. וצ\"ל מה הי' החטא שלהם. הנה החטא שלהם הי' שאמרו הבה נבנה לנו עיר ומגדל.\n<b>ולהבין</b> ענין מגדל דלעו\"ז צ\"ל תחילה מהו\"ע עיר ומגדל דקדושה שענין מגדל בקדושה הוא כמו שאי' בס\"י שתי אבנים בונות שתי בתים ושלש אבנים בונות ששה בתים, וענין אבנים הו\"ע אותיות כמו עד\"מ מריבוי אבנים נעשה בית ומריבוי בתים נעשה עיר, כמו\"כ מריבוי אותיות נעשה תיבה ומריבוי תיבות נעשה כללות עולם הדיבור שהו\"ע עיר אלקינו. וזהו מ\"ש כי מציון תצא תורה ודבר הוי' מירושלים, דבר הוי' שהוא מקור כל ההויות זהו מירושלם שהוא כללות עולם הדיבור ומציון שהוא פנימי' ירושלים תצא תורה שתורה הוא פנימי' האותיות. וזהו\"ע מגדל ע\"ד מ\"ש מגדל עוז ש' הוי'. וזהו שנא' גדול הוי' ומהולל מאד בעיר אלקינו ובכלל עיר קאי על ש' אלקים ומגדל נק' ש' הוי', וזהו\"ע עיר ומגדל דקדושה. ובכדי שיוכלו להמשיך מבחי' זו צריך להיות תחילה יראה וביטול כמ\"ש את אלקים ירא, אמנם הנה דור הפלגה באמת ידעו שההשפעה צריך להיות דוקא מבחי' עיר ומגדל דקדושה ולזה צריכים יראה וביטול אך הם לא רצו לקבל בבחי' יראה וביטול אלא הי' רוצים שיהי' השפעה גשמי' בלא יראה וביטול, ע\"ד מ\"ש והתברך בלבבו לאמר שלום יהי' לי כי בשרירות לבי אלך פי' הגם שבשרירות לבי אלך מ\"מ שלום יהי' לי. מה עשו, עשו עיר ומגדל דלעו\"ז כמ\"ש ותהי להם הלבינה לאבן, אבן הוא א' ב\"ן שש' הוי' במילוי אלפין בגימט' מ\"ה ומ\"ה הוא מברר ב\"ן, ומ\"ה הו\"ע ביטול, והם לא רצו לקבל בבחי' ביטול, מה עשו ותהי להם הלבינה, לבינה הוא מל' דנוגה שמחי' ע\"ד מקיף כך הם רצו שיהי' להם השפעה בלא ביטול אלא ע\"ד מקיף והוא כמו השבעות השמות וקבלה מעשיות שמשביע את הש' הגם"],[2000460393,"שאינו יודע מהו\"ע של הש' מ\"מ פועל בבחי' מקיף ועי\"ז עשו עיר ומגדל בלעו\"ז שהו\"ע שפחה כי תירש גבירתה, ומפני זה גדול החטא שלהם שאין להם חלק לעוה\"ב. ועד\"מ עיר הנידחת ג\"כ אי' במשנה שאין לה חלק לעוה\"ב ופליגו בה שני תנאים ח\"א עיר הנידחת לא היתה ולא תהי' אלא דרוש וקבל שכר וח\"א אני ראיתיה וישבתי על תילה, הגם שכתי' לא ידח ממנו נידח אלא מאחר שעיר עושים הסכם הוא ע\"ד דור הפלגה.\n<b>וזהו</b> החטא של דור הפלגה, וע\"י השעבוד וביטוש במצרים נזדככו וזכו למ\"ת. וראי' לזה שע\"י ביטוש וביטול יכולים להזדכך הוא כמו שאי' בזהר בריש מתיבתא אעא דלא שליט בי' נהורא מבטשין לי', גופא דלא סליק בו נהורא דנשמתא מבטשין לי' וסליק בו נהורא דנשמתא, ואף סט\"א בעית למעבד הכי ולא יכלית, לפי שבקדושה הנשמה היא משרש גבוה מתהו שקדמה לתיקון רק שנפלה בשה\"כ וע\"י ביטוש וביטול היש לאין יכול להחזירה למקורה ויכולה לקבל אורות דתהו, וזהו ג\"כ אבן בוחן דמצרים, והוא ע\"ד הוי' צדיק יבחן שדוקא צדיק אז הוא יבחין לפי שבקדושה ע\"י שמאלו תחת לראשי נעשה התקרבות אבל סט\"א בעית למעבד הכי ולא יכלית לפי שבסט\"א אדרבא ע\"י ביטוש וביטול הוא בועט ומחרף ומגדף. וזהו\"ע השעבוד של מצרים כדי לזכך החטא של דור הפלגה.\n<b>ועתה</b> מתורץ מה שהוצרך השעבוד ומ\"מ דוקא בדור הזה. ועיקר כונת השעבוד הוא הבכי' כמ\"ש ויאנחו בנ\"י מן העבודה ותעל צעקתם אל האלקים, בצר לך ומצאוך, ושבת עד הוי' אלקיך, מן המיצר קראתי י\"ה, וע\"י הבכי' נתגלה להם הוי' דלעילא. והוא ע\"ד מ\"ש מים תחתונים בוכים אנן בעינן למהוי קדם מלכא, ומהו הבכי' שלהם הוא ע\"ד מ\"ש יהי רקיע בתוך המים ויהי מבדיל שיש פרסא המבדיל כמ\"ש ויקרא הוי' הוי' ופסיק טעמא בגווייהו לכן בכו אנן בעינן למהוי קדם מלכא שיתגלה לנו הוי' דלעילא, וע\"י הבכי' נתגלה להם הוי' דלעילא, כך ע\"י ויאנחו בנ\"י מן העבודה עי\"ז נתגלה להם ש' הוי' דלעילא, שבכי' הוא התעוררות רחמים רבים, שיש ב' בחי' רחמים, רחמים בסדר השתל' שחסד משפיע לרחמים שיש מדת דין כנגדו וזהו הוי' רחום וחנון שהוי' משפיע לרחום, ויש רחמים שלמעלה מסדר השתל' וזהו כמ\"ש חנון ורחום הוי' והוא בחי' ואתה ברחמיך הרבים לא עשיתם כלה, וזהו\"ע העלאה והמשכה, בכי' הו\"ע העלאה ועי\"ז נמשך הוי' דלעילא, ע\"ד חתן וכלה חתן הוא המשכה מלמעלמ\"ט וכלה הוא העלאה מלמטלמ\"ע, ועד\"ז תורה ותפלה שזהו\"ע אתוון נוקבין ואתוון דוכרין. ובלעו\"ז מצינו ג\"כ ענין העלאה והמשכה, הרהורי עבירה קשה מעבירה עצמה, אדם מטמא עצמו מעט מלמטה מטמאין אותו מלמעלה הרבה.\n<b>ועל</b> לע\"ל כתי' ג\"כ בבכי יבואו ובתחנונים אובילם, ומה הוא הבכי' שלהם. אלא הענין הוא כמ\"ש כימי צאתך מארץ מצרים אראנו נפלאות שמשמע כמו שביצי\"מ הי' התחדשות בגילוי כמו\"כ לע\"ל יהי' ג\"כ התחדשות, וצ\"ל מהו"],[2000460394,"ההתחדשות. הענין הוא הנה כתי' ובלילה שירה עמי שיש מדרגה באורייתא שנק' בש' שירה ורננה דאורייתא, שמצינו בדוד שאמר זמירות היו לי חוקיך אמר לו הקב\"ה זמירות קרית לי' ונענש ע\"ז משום שיש בחי' שהיא גבוה מזמירות. כי בתורה יש ד' בחי' טנת\"א שהם כנגד דצח\"מ, אותיות הם בחי' דומם, ותגין הו\"ע צומח, ונקודות הם ענין חיה, טעמים הו\"ע מדבר. הנה אותיות הם מחג\"ת שהם כלים שע\"י נמשך השכל לידי גילוי כי בלא אותיות אינו יכול להמשיך השכל לידי גילוי ע\"ד כמו שמצינו באדם אף שהוא חכם גדול הרי צפון ונעלם אצלו השכל אלא ע\"י אותיות ממשיך השכל לידי גילוי, ואפי' כשיש אצלו אותיות מ\"מ צריך ג\"כ צמצום, כי עצם השכל כמו שהוא אינו יכול לימשך באותיות אלא ע\"י צמצום דוקא, והוא עד\"מ חבית גדולה של יין אין יכולים לשתות ממנה כ\"א כשמצמצם בכלים קטנים, כך השכל אין יכול להמשיך כ\"א ע\"י צמצום דוקא שצ\"ל צמצום התפשטות והמשכה ובחג\"ת צ\"ל ג\"כ צמצום התפשטות והמשכה, ופעם נת' שהם כנגד ג' ידות, וזהו\"ע אותיות. ותגין הם גבוהים מאותיות שתגין הוא בחי' כתר כמ\"ש דאשתמש בתגא חלף, וכשעלה משה למרום מצא להקב\"ה שקושר כתרים לאותיות, ות\"ת דאימא נעשה כתר לז\"א נמצא שתגין הוא מבינה. ונקודות הוא מחכ' שנקודה הוא יו\"ד ויו\"ד הו\"ע חכ', וכמו שחכ' הוא מנהיג למדות כך נקודות מנהיגים אות האותיות כמו אב או אם, אם הוא נקוד בפתח אז הוא אב ובאם הוא בנקודה אחרת נושא פי' אחר, ואֵם אם הוא בצירי אזי הוא אֵם, ואם הוא בחיריק הלא אז הוא תיבת אִם, ובכלל הוא ע\"ד נקודה בהיכלא שההיכל הולך אחר הנקודה, וזהו\"ע נקודות.\n<b>וענין</b> טעמים הוא למעלה מחכ', שהוא בחי' כתר שהו\"ע תענוג שלמעלה מחכ' כמ\"ש אז תתענג על הוי' שהוי' הו\"ע חכ', הוי' בחכ', ועונג הוא למעלה מחכ' כמ\"ש ואהי' אצלו שעשועים יום יום, שעשועי המלך בעצמותו. ומהו\"ע תענוג הוא כמו שמצינו באדם שבא לו איזה השכלה הנה הוא מתמלא תענוג וזהו דוקא שהשכל הוא חדש אצלו אז הוא קרוב למקורו לכן יש לו תענוג, אבל לאחר שנתיישן ה\"ה רחוק ממקורו אז אין לו תענוג, וזהו ע\"ד מים חיים שמיד שהם נובעים מהמקור אז נק' בש' מ\"ח אבל כשהם רחוקים מהמקור כמו נהר אז אינן נק' מ\"ח, נמצא מזה שטעמים הוא בכתר. והגם שנת' במ\"א שטעמים הוא בחכ', אלא לפי האמת שניהם אמת, שבשעה שאנו אומרים שהאותיות הם ממל' שיש ב' מיני אותיות שיש אותיות שבדבר הוי' שמים נעשו שהוא ממל' אז טעמים הוא בחכ', אבל בשעה שמדברים אותיות שהם אותיות התורה שהוא מחג\"ת אז טעמים הוא בכתר, שיש טעם גלוי וטעם שאינו גלוי ע\"ד שתוק כך עלה במח' וכי אין בה טעם אלא שהוא טעם שאינו גלוי, וטעם שאינו גלוי הוא בכתר וטעם גלוי הוא מחכמה.\n<b>והנה</b> עכשיו לא נתגלה כ\"א אותיות תגין נקודות, אותיות ע\"ד מ\"ט א\"ק, מנלן א\"ק, תגין כמארז\"ל ר\"ע הי' דורש על כל קוץ וקוץ תילי תילי של הלכות, ונקודות"],[2000460395,"יש אם למקרא יש אם למסורה, אבל טעמי תורה לא נתגלה אלא דוקא לע\"ל ע\"י בבכי יבואו ובתחנונים אובילם יתגלה טעמי תורה שלמעלה מחכ', כי כדי להשיג למעלה מהחכ' צריך לזה דוקא ע\"י בכי', ע\"ד שמצינו בחנה שנא' ותתפלל חנה על הוי' ועל מה היתה תפילתה על בנים ובנים לאו בזכותא תלי' מלתא אלא במזלא ובחי' מזל הוא למעלה מחכ' שאבא יונק ממזלא ואבא הוא חכ' ויונק ממזלא, וע\"י בכה תבכה באתה למד' זה, וכך לע\"ל ע\"י בבכי יבואו ובתחנונים אובילם יתגלה להם טעמי תורה. וזהו בלילה, ע\"י בכה תבכה בלילה, שירה עמי יתגלה שירה ורננה דאורייתא שזהו טעמי תורה.\n<b>ועתה</b> יובן מה שנא' ששים המה מלכות ושמונים פילגשים ועלמות אין מספר, אחת היא יונתי, אחת פי' שנמשך מאחד היינו למסור נפשו באחד, שמס\"נ הוא למעלה מטו\"ד, שיש אהבה עפ\"י טו\"ד דהיינו לאהבה את הוי' כי הוא חייך ומה שאדם אוהב חיי נפשו וזה שהוא חיי החיים כש\"כ שהוא אוהב אבל מס\"נ הוא למעלה מטו\"ד. וכשישראל הם במדריגת אחד אז ישראל במדריגה גבוה שהם למעלה מחכ' ואורייתא מחכ' נפקת אז ישראל משפיעים באוריי' ונק' אז התורה בשם מאורסה, וזהו דוקא שישראל הם בבחי' אחד אבל אם אינם במד' זו אז אורייתא משפיע בישראל שנשמות ישראל הם מקושרי' בז\"א ואורייתא מחכ' נפקת. וזהו שארז\"ל מט\"ט קושר כתרים לקונו בתפילותיהם של ישראל, שתפילה הו\"ע יהי רצון שיומשך רצון חדש שלמעלה מהחכ', כי ע\"פ חכ' יוכל להיות גזר דין כמארז\"ל אין יסורים בלא עון אבל ע\"י תפלה שתפילה הו\"ע רעוא דכל רעוין מקור כל הרצונות יומשך רצון חדש שיכבשו רחמי את כעסי, שעל ידי תפילה יוכל להמשיך מדריגה שלמעלה מבחי' חכ' כמו על ידי מסירות נפש. ולע\"ל על ידי בבכי יבואו יתגלה הוי' דלעילא. הגם שלאחר מ\"ת גם כן נתגלה הוי' דלעילא, אך זה שנתגלה זהו רק ההוי' שבחכמה אבל לע\"ל יתגלה טעמי תורה שלמעלה מהחכמה. וזהו כימי צאתך מארץ מצרים אראנו נפלאות, כמו שקודם מתן תורה אינו נתגלה רק הוי' תתאה ולאחר מתן תורה נתגלה להם הוי' דלעילא אך איזהו שבבחי' חכמה, אבל לע\"ל יתגלה הוי' דלעילא שלמעלה מחכ'."],[2000460396,"<h3>ואכלתם אותו בחפזון</h3>\n<b></b><b>בס\"ד, ליל שני של חג הפסח, שנת תרל\"ט</b>\n<b>ואכלתם</b> אותו בחפזון<sup data-n=\"1215\">1</sup> פסח הוא להוי' ואי' במד\"ר שיציאת מצרים הי' בחפזון ע\"ש כי בחפזון יצאת ממצרים, אבל לע\"ל כתי' כי לא בחפזון תצאו ובמנוסה לא תלכון. ואי' שם משל ע\"ז משל למה\"ד לסוחר אחד שהלך לשהות בפונדק עמד שם כל היום ובלילה נטל כל אשר לו ויצא לדרכו, ובבקר עמדה הפונדקית והתחילה צווחת ראו מה שעשה לי הפרגמטוטוס הזה, הנה פרגמטוטוס הו\"ע סוחר ע\"ש פרגמטי', נטל כל אשר לי והלך לו, כיון ששמע זאת הפרגמטוטוס אמר מי גרם לי שאשמע כזאת זה שיצאתי בלילה מכאן ואילך נשבע אני שלא אצא בלילה עוד, כך ישראל התקינו עצמן בלילה לילך בהשכמה לכך אחר ג' ימים רדפו מצרים אחריהם ואמר שנטלו את כל אשר לנו והלכו, אמר הקב\"ה מי גרם שאשמע כזאת זה שיצאתם בחפזון מכאן ואילך נשבע אני שלא תצאו עוד בחפזון. והגם שבאמת נטלו ממצרים שעשאוה כמצולה מ\"מ איתא בגמ' שעבודה של ששים ריבוא אנשים שעבדו במצרים הוא שוה יותר מהכסף והזהב שנטלו ממצרים נמצא שמה שנטלו נטלו משלהם, ועתה מי גרם שיאמרו מצרים כן זה שיצאתם בחפזון אבל לע\"ל כתי' כי לא בחפזון תצאו ובמנוסה לא תלכו כי הגאולה דלע\"ל לא תהי' עוד בחפזון. ועד\"ז אי' בזהר ע\"פ כי ימכור איש את בתו לאמה לא תצא כצאת העבדים, וקאמר התם שקאי על הגאולה דלע\"ל שהגאולה דלע\"ל לא תהי' כצאת העבדים שהיא בחפזון אבל הגאולה דלע\"ל לא תהי' בחפזון. נמצא שיש הפרש בין יצ\"מ ובין הגאולה דלע\"ל שגאולת מצרים הי' בחפזון אבל גאולת דלע\"ל לא תהי' בחפזון.\n<b>ועוד</b> יש שם במד\"ר הפרש בין גאולת מצרים ללע\"ל, שלשעבר אני וב\"ד שנא' והוי' הולך לפניהם יומם ולילה ובכל מקום שנא' והוי' הוא אני וב\"ד, אבל לע\"ל אני לבדי שנא' הולך לפניכם הוי' ומאספכם אלקי ישראל, נמצא שיש עוד הפרש בין יצ\"מ ולע\"ל שיצ\"מ הי' אני וב\"ד ולע\"ל יהי' אני לבדי. ועוד יש הפרש שגאולת מצרים הי' בלילה נס עובר אבל לע\"ל לא יהי' עוד בלילה אלא והי' אור הלבנה כאור החמה ולילה כיום יאיר שהלילה גופא נעשה יום. נמצא שיש ג' הפרישים, בין חפזון ללא בחפזון, ובין אני ובית דיני לאני לבדי, ובין לילה ליום שהלילה גופא נעשה יום, והכל תלוי באני וב\"ד כשהי' אני ובית דיני וענין בית דינו קאי על ש' אלקים כמו שמצינו למטה שב\"ד נק' אלקי' כמ\"ש עד האלקים יבוא דבר שניהם, אשר ירשיעון אלקי', כן למעלה נק' ב\"ד אלקים אז הי' צריך להיות בחפזון ובלילה ונס עובר אבל לע\"ל כשיהי' אני לבדי אז לא יהי' בחפזון ויהי' ביום ולילה גופא כיום יאיר.",[["1215","1","<b>ואכלתם אותו בחפזון</b>: הנחה מד\"ה וככה תאכלו אותו, לעיל בהספר ע' קלח. המאמר כאן הוא מתוך כת\"י מעתיק מס' 1185. ולעיל נדפס גם הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע ממאמר זה.\nהמ\"מ למאמר זה, נמצאים על המאמר בפנים הספר, ועל הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."]]],[2000460397,"<b>ועוד</b> יש הפרש בין גאולת מצרים ולע\"ל הובא במד\"ר תהלים ע\"פ כי עמך מקור חיים באורך נראה אור עובדא הוה בחד בר נש שהלך באישון לילה באפילה הי' מדליק וכבה מדליק וכבה אמר עד כמה אתייגע אמתין עד שיזרח השמש ואלך לאור היום, כך ישראל בתחילה נגאלו ממצרים ע\"י משה ואהרן וחזרו וגלו לבבל, ואח\"כ נגאלו ע\"י חנני' מישאל ועזרי' וחזרו וגלו למוקדון, ואח\"כ נגאלו ע\"י מתתיהו ובניו וחזרו וגלו, נגאלו ונשתעבדו נגאלו ונשתעבדו, אמרו ישראל עד כמה נתייגע אין אנו רוצים עוד ליגאל ע\"י בשר ודם נמתין עד שיזרח השמש שמש של משיח ונלך לאורו של הקב\"ה וזהו כי עמך מקור חיים באורך נראה אור, שבאורך אז נראה אור. נמצא שיש עוד הפרש בין יצ\"מ ללע\"ל שיצ\"מ נק' בש' נר וגאולה העתידה להיות נק' בש' שמש. וכן אי' בזהר ע\"פ כי תחבול שלמת ריעך עד בוא השמש תשיבנו לו וגו', ששמש קאי על לע\"ל והכי קאמר משכנתא שנתמשכן ישראל בגלות לא לעולם היא אלא עד ביאת משיח, נמצא שגאולת לע\"ל נק' בשם שמש.\n<b>ועוד</b> יש הפרש בין עוה\"ז לעוה\"ב בין שיר לשירה, שכל השירים שבזמן הזה נק' בש' נקבה כמ\"ש אז ישיר משה ובנ\"י את השירה הזאת, ובדוד כתי' וידבר דוד את דברי השירה הזאת, אבל לע\"ל כתי' שיר לשון זכר כמ\"ש ביום ההוא ישיר את שיר הזה, והיינו מפני שענין נקבה יולדת ומתעברת יולדת ומתעברת שגם שהיא יולדת מ\"מ ה\"ה מתעברת, ועיבור ולידה הו\"ע גלות וגאולה, לידה הו\"ע גאולה כמ\"ש חלה גם ילדה ציון את בניה, ועיבור הו\"ע גלות כמארז\"ל בכל פרשת העיבור יהיו צרכיהם לפניך, אפי' כשאתה מתמלא עליהם עברה כאשה עוברה יהי' צרכיהם לפניך, ולכן בעוה\"ז שירה לשון נקבה כמו שבנקבה יש שינוים שיולדת ומתעברת כן בישראל נגאלו ונשתעבדו נגאלו ונשתעבדו אבל על לע\"ל שיהי' גאולה שלימה כתי' שיר לשון זכר שבזכר ליכא שינוים.\n<b>ונמצא</b> שיש ה' הפרשים בין שיר לשירה, ובין אור הנר לאור השמש, ובין לילה ליום, ובין אני לבדי ואני וב\"ד, ובין חפזון ללא בחפזון. והכל תלוי כמו שנת' שתלוי בההפרש מאני לבדי לאני וב\"ד, בעת שהי' אני וב\"ד הי' בחפזון ובלילה כו' אבל לע\"ל כשיהי' אני לבדי היינו ש' הוי' לבדו אז לא יהי' כל הדברים האלה.\n<b>ולהבין</b> ש' הוי' הענין הוא כי על שם הוי' כתי' אני הוי' לא שניתי, שאין בש' הוי' שום שינוי, כי הוי' הו\"ע אמת כמ\"ש ואמת הוי' לעולם. וזהו מ\"ש וארא אל אברהם באל שדי ושמי הוי' לא נודעתי להם ופירש\"י לא ניכרתי במדת אמת שלי, כי הוי' הוא מדריגת אמת. הגם שכל השמות הם אמת, רק יש כמה מדריגות אמת, אמת ושפת אמת ואמת לאמיתו, וש' הוי' הוא אמת. ומהו\"ע אמת, אמת הו\"ע היפך הכיזוב, וענין כזב הוא ע\"ד מים כוזבין שנפסקים לפעמים הגם שעכשיו הולכים מ\"מ מאחר שעתיד ליפסק נק' בש' כזב כמארז\"ל נהרות המכזבין אפי' פעם אחת בשבוע היינו לשבע שנים פסולין לקידוש מי חטאת הגם שעכשיו יש מים מ\"מ כיון שיפסקו לפעמים אינו נק' בש' אמת, ואמת הוא דבר שלא נפסק לעולם כמוצא מים אשר לא"],[2000460398,"יכזבו מימיו, ובזהר קרא זה מבוע דלא פסק מימיו לעלמין, כמ\"ש ונהר יוצא מעדן שיוצא תמיד שזה מדריגת אמת. ונהרות שמכזבין פעם אחת ביובל אי' ברש\"י ובברטנורא שכשירין לקידוש מי חטאת הגם שנפסקים לפעמים אך כיון שנפסקים פעם אחת ביובל הו\"ע על יובל ישלח שרשיו שהו\"ע יחוד י\"ה תרין ריעין דלא מתפרשין לעלמא וזיווגייהו תדירו ולא נק' כזב. ובכלל הוא ההפרש בין תורה לתפילה, תורה נק' חיי עולם כמ\"ש וחיי עולם נטע בתוכינו ותפלה נק' חיי שעה, והיינו כי תורה נק' תורת אמת לכך נק' חיי עולם אבל תפילה שכתי' אני תפילה ואני הו\"ע מל' שהוא יחוד ו\"ה שזיווגייהו לפרקים לכך נק' חיי שעה מפני שאין יחוד שלם. וזהו שכתי' ביחזקאל ואני הייתי בתוך הגולה וראיתי על נהר כבר פי' שהי' כבר נהר אבל עכשיו אינו נהר, ומה פי' נהר הוא כמ\"ש ונהר יחרב ויבש יחרב בבית ראשון ויבש בבית שני פי' שהי' שם גילוי אלקות אבל עכשיו אין שם גילוי אלקות, והיינו מפני שלא הי' שם בתחילה יחוד שלם.\n<b>ושרש</b> הענין הוא שכתי' ושם הגדולה לאה ושם הקטנה רחל פי' שם ה' גדולה לאה ושם ה' קטנה רחל, וענין ש' הגדולה לאה שגדולה במתנותיה כהונה לעולם ומל' בית דוד לעולם, כהונה לעולם כמ\"ש ברית מלח עולם, הנה מלח אנו רואים שהוא דבר שלא נפסד לעולם ואף מקיים שארי דברים שלא יאבדו. וכן כהונה לעולם ומל' בית דוד לעולם כמ\"ש ודוד עבדי נשא עליהם היינו מלך עליהם לעולם. ושם הקטנה רחל שקטנה במתנותיה, כי יוסף לפי שעה ושאול לפי שעה ומשכן שילה לפי שעה. ומהו\"ע ש' הגדולה לאה, כי ה' גדולה הוא בחי' בינה והתגלות עתיק הוא בבינה ששם אינו שייך שינוים כלל. ובזה יובן מה שאי' בגמ' כמה לא חלי ולא מרגיש גברא דמאריה סייעיה שאול באחת ועלתה לו דוד בשתים ולא עלתה לו, היינו לא עלתה לו לרעה, היינו מפני כי מל' שאול הי' ע\"פ חכ' כמ\"ש משכמו ולמעלה הי' גבוה מכל העם פי' שכמו היינו כתפי ואחוריים שהם מדות, שהמדות שלו הי' גבוה מראש ומוחין של כלל ישראל, הלכך גזר חכמתו שיהי' מלך, ואח\"כ מיד שחטא גזר חכמתו שלא יהי' עוד מלך. ע\"ד שאי' שאלו לחכ' נפש החוטאת במה תכופר אמרה חטאים תרדף רעה שאלו לנבואה אמרה נפש החוטאת תמות, ולכאורה צ\"ל הלא חכ' סתם הוא חכ' תתאה ונבואה מדריגה גבוה מחכ' ולמה החמירה הלא כל שמדריגתו גבוה ה\"ה מקיל, כמו שאי' שאלו לתורה במה תכפר יביא אשם, שאלו להקב\"ה אמר יעשו תשובה, הרי כל שמדריגתו גבוה מקיל ביותר ולמה החמירה הנבואה, אך הענין הוא שזהו ע\"ד חכם עדיף מנביא שידיעת המציאות ממד' גבוה טובה מהשגת המהות של מד' הנמוכה ולכן החכ' הקילה מהנבואה. ועוי\"ל שהנבואה שרשה בינ\"ה אבל חכ' הגם שהיא חכ' תתאה מ\"מ שרשה היא בחכ' עילאה כמ\"ש הוי' בחכ' יסד ארץ פי' ארץ היא חכ' תתאה ושרשה היא בחכ' עילאה, אבא יסד ברתא, ולכן ה\"ה במד' גבוה יותר מנבואה ולכן הקילה. ועד\"ז כאן שמל' שאול הי' ע\"פ חכ' ומאי קאמר חכ' חטאים תרדף רעה לכן כשחטא נענש שרוח רעה מבעתיה, אבל דוד בשתים ולא עלתה לו לרעה כי בדוד כתי' רמה קרני וארז\"ל רמה קרני ולא רמי פכי שאול שנמשח בפך לא נמשך מל' אבל דוד שנמשח בקרן נמשך מל', כי דוד"],[2000460399,"הי' מד' רוממות היינו בחי' כתר כמ\"ש ואתה מרום לעולם הוי' כמו שמצינו בתפילה בלאל ברוך שחשיב שם כל הע\"ס כי הוא לבדו מרום וקדוש פועל גבורות עושה חדשות בעל מלחמות כו', כי הוא לבדו קאי על א\"ס עצומ\"ה, מרום הוא כתר, קדוש הוא בחי' חכ', פועל גבורות הוא בחי' בינה, עושה חדשות הו\"ע חסד, בעל מלחמות הו\"ע גבור כו' חושב שם ע\"ס נמצא שמרום הו\"ע כתר, וכן בדוד כתי' רמה קרני הו\"ע כתר ובכתר לית שמאלא בהאי עתיקא ששם אין שייך שינוים ולכן נמשך מל'.\n<b>וע\"י</b> מה זכה דוד לזה זהו דוקא ע\"י קרן, כי פי' קרן הוא ע\"ד קרן זוית שהוא מחבר ב' דפנות מזרחית צפונית, הלא כל הכותל של מזרח הוא מזרח וכל הכותל של צפון הוא צפון ומהו הקרן, קרן אין לו שום מהות מחמת שכל מה שנמשך למזרח כולו מזרח וכל מה שנמשך לצפון כולו צפון ומהו\"ע קרן, קרן הוא ביטול, כמו\"כ דוד שהי' תמיד בביטול כמ\"ש ואנכי תולעת ולא איש כי עני ואביון אני לכן זכה לבחי' רוממות היינו בחי' כתר ששם ליכא שינוים ולכן נמשך מל'. ובזהר אי' שרוממות הקרן הוא מבחי' עה\"ח דקראו אתר דלא משתנה, ולכן כתי' ועתה פן ישלח אדם את ידו ולקח מעה\"ח ואכל וחי לעולם ולכאו' מאי איכפת שיחי' לעולם, אך הנה כיון שיאכל מעה\"ח יתקיים הרע לעולם, כי מאחר שאכל עה\"ד נתערב רע בטוב רק אעפ\"כ הרי הרע יוכל להתברר כמ\"ש ובערת הרע מקרבך אבל כשיאכל גם מעה\"ח הרי הרע הי' ח\"ו קיים לעולם לכן ויגרש את האדם, שעה\"ח הו\"ע כתר אתר דלא משתנה. ואף שבכמה מקומות נת' שבחי' עה\"ח הוא ת\"ת, הרי ידוע שת\"ת עולה עד הכתר וה\"ז דבר אחד. ולכן מצינו בילקוט שדוד רצה לבנות הבהמ\"ק אמר לו הקב\"ה אתה לא תבנה הבית, מפני מה השיב לו הקב\"ה מפני שאם אתה תבנה אותו יהי' קיים לעולם, ולכאורה מאי איכפת להקב\"ה, השיב לו הקב\"ה שגלוי וידוע לפני שעתידין ישראל לחטוא מוטב שאכלה חמתי על עצים ואבנים ואל אכלה חמתי על ישראל. נמצא שדוד שנמשך מעה\"ח גם מעשה ידיו הי' קיים לעולם, אבל עה\"ד קראו בזהר אתר דמשתנה שעה\"ד הוא בחי' מל', ומל' הוא יחוד ו\"ה שזווגייהו לפרקים ששייך שם שינוים, ולא מל' בעצם הוא עה\"ד שבמל' אין שייך רע, אלא מפני שמתלבש בעה\"ד לברר הרע נק' מל' עה\"ד. ולכן משה ואהרן שגם הם לא נמלטו מהחטא, שגם אלו שמתו בעטיו של נחש לא נמלטו מהחטא שהרי מתו, ולכן גאולת משה לא הי' נצחי', ולכן מצינו שמשה הי' מסרב לילך בשליחותו של הקב\"ה וטען לא איש בעל דברים אנכי כי כבד פה וכבד לשון אנכי, והיינו מפני שרצה שיהי' הגאולה ע\"י הקב\"ה בעצמו ויהי' גאולה שלימה. וכן אי' במד\"ר ע\"פ מי אנכי שמשה טען וכי אני הוא האנכי שאמר הקב\"ה ליעקב אנכי ארד עמך מצרימה ואנכי אעלך גם עלה, לכן שאל אם אני הוא האנכי שרצה שיהי' הגאולה ע\"י הקב\"ה בעצמו כדי שיהי' גאולה שלימה.\n<b>ומעתה</b> יובן מה שהי' לשעבר אני וב\"ד היינו ע\"י ש' אלקים ששייך שם שינוים, לכן הי' הגאולה ע\"י משה ואהרן ולא הי' גאולה שלימה, אבל לע\"ל שיהי' אני לבדי ונסו יגון ואנחה ושמחת עולם על ראשם, יהי' גאולה שלימה. וצ\"ל הלא"],[2000460400,"קודם הי' ג\"כ ע\"י ש' הוי' שהי' הוא וב\"ד, אני וב\"ד כמ\"ש בתורה חומש וידעתם כי אני הוי', לכן אמור לבנ\"י אני הוי', ויושע הוי' ביום ההוא, אך עכ\"ז הי' נמשך ע\"י בחי' ש' אלקי' ששם שייך שינוים. וכמו שמצינו שאמר הקב\"ה למשה הנה אנכי שולח מלאך לפניך כו' השיב לו משה אם אין פניך הולכים אל תעלינו מזה, ואף שמלאך הו\"ע שליח ואין לו רק כח המשלחו ולא מוסיף ולא גורע רק כגרזן ביד החוצב בו ומצינו שיהושע קבלו עתה באתי רק מ\"מ מאחר שהוא ע\"י שליח יוכל להיות שינוים. וכמו\"כ ביצ\"מ שהי' הגאולה ע\"י ש' אלקים לכן לא הי' גאולה שלימה, ואף שהי' שם גילוי ש' הוי' לא כמ\"ש שמש ומגן הוי' אלקים שהמגן מכסה את השמש רק הי' גילוי ש' הוי' שהי' ניסים היוצאים מדרכי הטבע לגמרי ואלקים הוא בגימט' הטבע, ואף שבש' אלקים יש ג\"כ ניסים וגם נסים תכופים אך עכ\"פ מוסתר בדרך הטבע ושם הי' נסים יוצאים מדרכי הטבע לגמרי שהי' גילוי ש' הוי, אך עכ\"ז הי' ע\"י ש' אלקים ע\"ד שילוב הוי' באדני שהי' גילוי ש' הוי' אבל התגברות הוא מש' אד' ששם שייך שינוים, אבל לע\"ל שיהי' אני לבדי, ע\"י ש' הוי' לבדו שאני הוי' לא שניתי ששם לא שייך שום שינוי ויהי' גאולה שלימה. והגם שיש כמה שמות הוי' ג\"כ יש הוי' הנראה והוי' שאינו נראה שהו\"ע הוי' דסוכ\"ע והוי' ממכ\"ע ויקרא הוי' הוי', אך מ\"מ הכל הוא ש' הוי', ולע\"ל יהי' גילוי ש' הוי' ע\"ד שאמר יעקב והי' הוי' לי לאלקים שיתגלה ש' הוי' כמו ש' אלקים.\n<b>ולכאורה</b> צ\"ל הלא ש' אלקים הוא מחולק משאר שמות שאלקי' יכולים לומר אלקינו אבל ש' הוי' לא שייך לומר כך ואיך שייך לומר שיהי' גילוי ש' הוי' כמו אלקים. אך הענין הוא שהגילוי יהי' ע\"י ש' אלקים רק שיהי' ע\"ד שילוב אד' בהוי' שיהי' התגברות מש' הוי' רק שיהי' נמשך בהתלבשות ע\"י ש' אלקים. ועוי\"ל כמארז\"ל עתידין צדיקים שיקראו ע\"ש של הקב\"ה ופרש\"י שיהי' שמם הוי', א\"כ לפ\"ז יוכלו לקבל הגילוי של ש' הוי' בלא שם אלקים מחמת שיקראו שמם הוי'. וזהו\"ע לשעבר אני וב\"ד שהי' יחוד ע\"י ש' אלקים שהו\"ע אתר דמשתנה ולכן הי' בחפזון וגם נס בלילה ונס עובר ונמשל לאור הנר כמארז\"ל אור לארבעה עשר<sup data-n=\"1216\">2</sup> בודקין את החמץ לאור הנר שלא הי' גאולה שלימה, אבל לעתיד לבוא שיהי' בחי' גילוי ש' הוי' יהי' גאולה שלימה שנמשך מבחי' אתר דלאו משתנה.",[["1216","2","<b>אור לארבעה עשר</b>: הנחה מד\"ה ”והנה יצ\"מ\" הנדפס לעיל ע' קמד. מאמר זה הוא מתוך כת\"י מעתיק מס' 1185.\nהמ\"מ למאמר זה, ראה לעיל ע' קמד ואילך שם, ולעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."]]],[2000460401,"<h3>אור לארבעה עשר</h3>\n<b>בס\"ד</b>\n<b>אור</b> לארבעה עשר בודקין את החמץ לאור הנר ונת' במאמר הקודם שגאולת מצרים נמשל לאור הנר ומפני זה הי' בחפזון ובלילה והי' נס עובר מפני שהי' נמשך מאתר דמשתנה, וצ\"ל איך נמשלה לנר הלא אי' עד שנגלה עליהם מלך מלכי המלכים וגאלם, פי' מלך מה\"מ, מלכים הו\"ע ז\"א ומל', מלכי המלכים הו\"ע חו\"ב, וממה\"מ הו\"ע כתר מל', נמצא שהי' גילוי גבוה ולמה נמשלה לנר. ועוד צ\"ל מה שכתי' כי נר מצוה ותורה אור, קרא מצות בשם נר, הלא מצות הם תרי\"ג מצות דאורייתא וז' מצות דרבנן שהם תר\"ך עמודי אור שהו\"ע כתר ואיך נמשל לאור הנר ובפרט שמצינו שלע\"ל יהי' מעשה גדול. וכה\"ג צ\"ל מה שאי' בגמ' זו דרש ר' מנחם ב\"ר יוסי תלה הכתוב מצות בנר ותורה לאור לומר לך מה נר אינה מאירה אלא לפי שעה כך מצות אינם מגינים אלא לפי שעה, ותורה לאור לומר לך מה אור מאירה לעולם כך תורה מגינ' לעולם, וצ\"ל הלא מצות הם תר\"ך עמודי אור והאיך נמשלו לאור הנר.\n<b>והענין</b> הוא דאי' בגמ' שכר מצוה בהאי עלמא ליכא פי' מה ששכר מצוה מצוה בהאי עלמא ליכא, ואף שמצינו שאי' אלו דברים שאדם אוכל פירותיהם בעוה\"ז אך זהו פרטי מצות אבל בד\"כ שכר מצוה בהאי עלמא ליכא, ולכן תלה הכתוב מצות בנר לומר לך מה נר אינה מאירה אלא לפי שעה כך מצות אינן מגינין אלא לפי שעה, פי' שבהאי עלמא ליכא השכר שלהן, אבל תורה נמשלה לאור מפני שת\"ת כנגד כולם לכן נמשלה לאור לומר לך מה אור מאירה לעולם כך תורה מגינה לעולם פי' שבהאי עלמא ג\"כ אי' השכר שלה.\n<b>ועוד</b> אי' שם דבר אחר עבירה מכבה מצוה ואין עבירה מכבה תורה, וצ\"ל מהו הפי' של עבירה מכבה מצוה זה א\"א לומר שעצם המצוה עבירה מכבה אותה, זה בודאי אינו, כי הלא אי' מחצה עוונות ומחצה זכיות הרי זה מנוחלי עוה\"ב, שעל העבירה נפרעין ממנו ונותנין לו עונשין ועל המצות ה\"ז מנוחלי עוה\"ב, אלא הפי' של עבירה מכבה מצוה כי ענין של מצוה שע\"י שאדם עושה מצוה ממשיך על עצמו מקיף דקדושה שמעלה ומגביה את נפשו, וע\"ז קאמר עבירה מכבה מצוה שאותה מקיף שנעשה מהמצוה עבירה מכבה אותה. וצ\"ל מהו\"ע של המקיף.\n<b>הנה</b> אנו אומרים בנוסח התפלה המלך המרומם לבדו מאז וכו' אלקי עולם ברחמיך הרבים רחם עלינו אדון עוזינו צור משגבינו מגן ישעינו משגב בעדינו, וצ\"ל"],[2000460402,"מהו השייכות זל\"ז. אך הענין הוא שהמלך המרומם קאי על הקב\"ה שהוא קדוש ומרומם מגדר עולמות, ששם אינו יכול להיות אפי' מקור לעולמות שזהו בחי' סוכ\"ע, ומה שנברא העולם זה אינו אלא משם והארה בעלמא כמו שכתי' מלכותך מלכות כל עולמים כי מלך שמו נק' עליהם, שאינו אלא מש' והארה בעלמא, וכשיתבונן איך שהקב\"ה בעצמו הוא קדוש ומובדל מגדר עולמות ומה שנברא העולם זהו אלא מש' והארה, אזי ברחמיך הרבים מתעורר ר\"ר על נפשו כשיתבונן שנשמתו היא חלק אלקה ממעל כמ\"ש כי חלק הוי' עמו רק שנתרחק ונתגשם מאלקות אזי אדון עוזינו הוא ממשיך עליו מקיף כללי, והגם שאהוי\"ר פנימי' אינו פועל מ\"מ קבלת עול מלכות שמים ה\"ה פועל לכה\"פ, ואח\"כ כשיקבל מלכותו יקבל גזירותיו ומקיים תומ\"צ וע\"י המצות ממשיך עליו ג' מקיפים פרטים שהוא צור משגבינו מגן ישעינו משגב בעדינו שזהו כנגד ג' עולמות בי\"ע ונגד ג' לבושים מחשבה דו\"מ ונגד ג' בחי' נר\"נ, ובמצות יש ג\"כ הג' לבושים מחדו\"מ, מחשבה כמארז\"ל אם כיון לבו יצא ואם לאו לא יצא, ויש מצות שהם בדיבור, ורוב מצות הם במעשה, וע\"י עשיות המצות ממשיך עליו ג' מקיפים שלמעלה הם לבושים ולמטה הם מקיפים. וזהו מ\"ש והלך לפניך צדקיך וכבוד הוי' יאספיך, והלך לפניך צדקיך זהו כללות כל המצות, כי כללות כל המצות נק' בש' צדקה כמ\"ש וצדקה תהי' לנו כי נשמור לעשות את כל המצוה הזאת, וכבוד הוי' יאספך שעי\"ז הוא אוסף וכונס בבחי' מקיף. ועתה ניחא מה שיש שייכות זל\"ז המלך המרומם, פי' כשיתבונן שהקב\"ה הוא קדוש ומובדל ומה שנבה\"ע אינו אלא מש' והארה בעלמא אזי ברחמיך הרבים ה\"ה מתעורר ר\"ר על נפשו וממשיך אדון עוזינו מקיף כללי, שזהו קבעומ\"ש, ואח\"כ מקבל גזירותיו שמקיים תומ\"צ, ועי\"ז ממשיך ג' מקיפים פרטיים שלמעלה הם לבושים ולמטה הם מקיפים.\n<b>וזהו</b> הפי' של מצוה גוררת מצוה, שע\"י שאדם עושה מצוה הוא ממשיך עליו מקיף והמקיף גורר עוד מצוה. וע\"ז אמר עבירה מכבה מצוה, שעצם המצוה אין עבירה מכבה אותה רק המקיף שנמשך מאותה מצוה עבירה מכבה אותה, ואין עבירה מכבה תורה שע\"י תורה נעשה כ\"כ התקשרות למעלה שאפי' המקיף שנעשה ממנה אין עבירה מכבה. לכן אי' במד\"ר ע\"פ אותי עזבו ואת תורתי לא שמרו, קאמר שם הלואי שאותי עזבו רק את תורתי ישמרו שהמאור שבה מחזירן למוטב, שלא די שאין קוראין אותה נר אלא שנק' עוד מאור, ולא די שאין עבירה מכבה אותה רק שעוד מחזירה למוטב, שהאור והמאור שבה מחזירה למוטב. ועוד י\"ל עבירה מכבה מצוה כי מהו ענין מצוה רמ\"ח פקודין אינון רמ\"ח אברין דמלכא, ותרין דרועין הו\"ע נר, ופי' תרין דרועין זהו האוי\"ר שנולד מהמצוה, וע\"ז קא' עבירה מכבה מצוה שהאוי\"ר שנולד מהמצוה עבירה מכבה אותה, ואין עבירה מכבה תורה שהאוי\"ר שנולד ממנה אין עבירה מכבה אותה.\n<b>ועתה</b> יובן מה שאנו קוראין מצות בש' נר, הגם שמצות הם תר\"ך עמודי אור שהו\"ע כתר, הרי כ\"ז הוא למעלה אבל כאן שבאו למטה באו בש' מצות"],[2000460403,"המלך שזה תלוי באדם לכן נמשלו לנר, כי מה ענין של נר, נר הו\"ע מל' סיהרא דלית לה מגרמ' כלום, וכמו שלנר צריכים להמשיך ג' דברים אור ושמן ופתילה, אור הו\"ע כתר ושמן הו\"ע חכ' ופתילה הו\"ע יסוד, וכ\"ז צריך להיות בנר והוא ע\"י שמיחד השלשה דברים אלו ע\"י האדם, כמו\"כ כאן צ\"ל אתעדל\"ת ואח\"כ אתעדל\"ע. אבל תורה הו\"ע יחוד י\"ה תרין ריעין דלא מתפרשין לעלמא וזיווגייהו תדירו שזהו אתעדל\"ע שלמעלה מאתעדל\"ת.\n<b>ומעתה</b> יובן מ\"ש ואכלתם אותו בחפזון ואי' במד\"ר שגאולת מצרים הי' בחפזון ע\"ש כי בחפזון יצאת מאמ\"צ, והיינו מפני שגאולת מצרים הי' בלילה כמ\"ש ויהי בחצי הלילה והוי' הכה כל בכור, וכתי' ליל שימורים, ושימורים הוא לשון רבים שיש בו ב' פי' הא' פי' שימורים לשון שמירה כי לילה הו\"ע מל' ומל' הוא מקור לבי\"ע ובבי\"ע יש רע, בעשי' רובו רע, וביצי' מחצה רע, ובבריאה מיעוטא רע, והגם ששם אינו רק מיעוט רע מ\"מ ה\"ז רע לכן צריך שמירה שלא יהי' יניקה לחיצוני', אבל אצי' שהיא מדת יום שם כתי' לא יגורך רע, והגם שיש קליפה שהיא נגד אצי' ג\"כ, מ\"מ מעמדה היא בבריאה. וזהו\"ע מה שאי' בזהר תליסר עלין מסחרין לשושנה, שושנה זהו ענין מל' ומל' היא מקור לבי\"ע ובבי\"ע יש רע לכך מסחרין לה שלא יהי' יניקה לחיצוני'. ואי' שם שיש ה' עלין תקיפים לאגנא עלה, פי' לאגנא להגן שלא יהי' יניקה לחיצונים. ובזה ניחא מה שבברכות נשואין ברכה ראשונה פותחת בברוך ואינה חותמת בברוך וברכה שני' פותחת בברוך וחותמת בברוך, והיינו כי מהו ענין חתימה, חתימה הו\"ע שמירה, לכך ברכה ראשונה שהיא כנגד יום ויום אינו צריך שמירה, לכך אינה חותמת בברוך, וברכה שני' מפני זה חותמת בברוך שהו\"ע שמירה, מפני שהיא כנגד מדת לילה כמ\"ש יום ליום יביע אומר ולילה ללילה יחוה דעת, ולילה צריכה שמירה כמו שאי' בגמ' שלש משמורת הוה הלילה ראשונה חמור נוער שני' כלבים צועקים שזהו\"ע קליפות לכך צריכה שמירה שלא יהי' יניקה לחיצונים. לפיכך מצינו שאפי' לילה בשבת צריכה ג\"כ שמירה שאנו אומרים מגן אבות.\n<b>ובדרך</b> עבודה הענין הוא דהנה תושב\"כ נק' בש' יום ותושבע\"פ נק' בשם לילה, כמו שאי' בילקוט ויהי שם משה בהר ארבעים יום וארבעים לילה ופריך מנא הוה ידע אימתי יום ואימתי לילה הא נהורא שרי' עמו, ומתרץ כשלמדו עמו תושב\"כ ידע שהוא יום וכשלמדו עמו תושבע\"פ ידע שהוא לילה, נמצא שתושב\"כ הוא יום ותושבע\"פ הו\"ע לילה, ובתורה שייך שמירה כמ\"ש ושמתם ואי' בגמ' זכה נעשה לו סם טוב לא זכה ח\"ו להיפך, ואיזה שמירה שייך בתורה שלא יפול בגסות ויוהרא, וזה לא שייך אלא דוקא בתושבע\"פ, כי בתושב\"כ כשלומד פ' חומש שם לא שייך שום גסות ויוהרא רק כשלומד פוסקים ומשנה יכול לבוא עי\"ז לידי גסות ויוהרא לכך צריכה שמירה. וכן כתי' זכור זו מקרא ושמור זו משנה, שמשנה צריכה שמירה."],[2000460404,"<b>זהו</b> פי' הראשון של שימורים, והפי' הב' של שימורים הוא לשון שימור והמתנה ע\"ד ואביו שמר את הדבר, שיושב ומצפה מתי יבוא הדבר, והוא ע\"ד אשה משתמרת לביאה, כמו\"כ כאן משמר וממתין על יחוד דסובב וממלא ומפני זה נק' מצה, מצה שמורה, ע\"ש שמשמר על היחוד דסובב וממלא, וזהו כמו שאי' זכור לדוכרא ושמור לנוקבא זמין לדוכרא לאזדווגא בי', שמשמר על היחוד דסובב וממלא, ומפני זה נק' מצה לחם עוני כשם שעני מצפה על השפעות העשיר כמו\"כ כאן מצפה על היחוד סובב וממלא. וזהו השני פי' של שימורים. ובאמת השני פי' הו\"ע אחד מפני שמצפה על יחוד דסובב וממלא שהוא יחוד גבוה מאד לכן צריכה שמירה שלא יהי' יניקה לחיצונים. כמו שאי' בזהר ועד בחילופי אתוון אחד, כדי שלא ישלוט בו עין הרע, כי אחד כמו שהוא למעלה שהו\"ע יחו\"ע שם לא שייך עין הרע רק אחד שבא למטה כגוונא דאינון מתייחדין לעילא אוף הכי איהי אתייחדת לתתא ברזא דאחד, ומפני שהוא יחוד גבוה כ\"כ צריכה שמירה להסתיר על היחוד כדי שלא תשלוט בו עין הרע. וכן מצינו במשנה שארז\"ל עשרה נסים נעשו לאבותינו בבית המקדש וחשיב שם שלא אירע קרי לכה\"ג ביוהכ\"פ, ולכאורה צ\"ל מהו הרבותא שלא אירע קרי הלא כה\"ג הי' גדול בישראל והי' נכנס לבהמ\"ק לקה\"ק וביום הכפורים הלא כל ישראל קדושים ובפרט שהי' מפרישין אותו ז' ימים קודם יוהכ\"פ, ומהיכי תיתא שיראה קרי, ואיזה נס הי' שם. אלא היא הנותנת דוקא מפני שהי' גדול בישראל ונכנס לפני ולפנים וביום הכפורים הקנאה יותר גדול לכך צריך שמירה יותר ומפני זה הנס גדול.\n<b>וע\"ד</b> עבודה הענין הוא כמ\"ש כי ברח העם, ופריך בתניא מה הי' להם לברוח הלא אם הי' אומר ה' לפרעה שיניח אותם לילך לגמרי הי' מניחם שהי' מוכרח ולמה הי' להם לברוח, אלא מה שברחו לא ברחו מפני פרעה אלא שברחו מעצמם מפני שהיו משוקעים במ\"ט שערי היפך לכן היו בורחים מרע שלהם גופא. והיכן ברחו כתי' דרך שלשת ימים נלך במדבר, והענין של שלשת ימים הוא כנגד ג' לבושים מחשבה דיבור ומעשה שבתורה. וזהו כמו שאי' בראתי יצה\"ר בראתי תורה תבלין, אם פגע בך מנוול זה משכהו לבהמ\"ד אם אבן הוא נימוח, אם רעב שונאך האכילהו לחם, שונאך פרש\"י יצה\"ר, וגם על מנוול פרש\"י יצה\"ר, האכילהו לחם, לחמה של תורה, והוא ישלימנו לך. וגם אי' במד\"ר פנו לכם צפונה, הצפינו לכם בדברי תורה.\n<b>ומעתה</b> יובן מה שאיתא שגאולת מצרים הי' בחפזון ע\"ש כי בחפזון יצאת ממצרים, ופריך השל\"ה מהו המעלה של חפזון, ועתה כמו שנתבאר יהי' ניחא שהחפזון הוא ע\"ד כמו יראת חטא שפי' יראת חטא שהוא ירא מהחטא עצמו כמו\"כ הכא ברחו מהרע שלהם. והגם שביארנו שחפזון הוא מעלה, מ\"מ מצינו בכמה מקומות שבלא חפזון זהו יותר נעלה וכמו שמצינו שכתוב נחלה מבוהלת בראשונה ואחריתה לא תבורך, וקאמר במדרש זה נחלת בני גד ובני ראובן שנחפזו ליקח נחלה מעבר לירדן שאילו המתינו היו נוטלים חלק בא\"י שנק' ארץ הקדושה והם נחפזו"],[2000460405,"ונטלו חלק בחו\"ל שנק' ביהושע ארץ טמאה אחוזתכם. וכן מצינו באדה\"ר שעיקר החטא שלו הי' שהזדווג בערב שבת שאילו הי' ממתין עד שבת הי' כל זרעו קודש נמצא שחפזון אינו מעלה. והגם שאי' זריזין מקדימין למצות, אך זהו רק הכנה למצוה צ\"ל בזריזות אבל המצוה עצמה צ\"ל מתון מתון. מ\"מ אינו דומה חפזון זו לחפזון דמצרים, שהחפזון זו הי' שלא בזמנו, דהיינו חפזון של אדה\"ר הי' שלא בזמנו שאי' אשר פריו יתן בעתו זה עונת ת\"ח בליל שבת והוא נחפז בערב שבת, לכך החפזון אינו מעלה, אבל הכא שלא היו יכולין בענין אחר החפזון זה הוא מעלה.\n<b>עכ\"ז</b> הגם שביארנו שחפזון הוא מעלה מ\"מ במקום שאינן צריכין לחפזון בלא חפזון הוא יותר נעלה, כמו לע\"ל אז כתי' כי לא בחפזון תצאו ובמנוסה לא תלכון שהוא ע\"ד כמו שאי' חסידים הראשונים היו שוהין תשע שעות בתפילתן ומהו ענין של השהי' שהאהוי\"ר הנולד מהתפלה שלא יהי' בבחי' נופל שהוא חולף ועובר, אלא שיהי' בבחי' בר קיימא, הרי מצינו ששהי' הוא מעלה. ובכלל ההפרש הוא בין צדיקים לבינונים, שצדיקים שאין להם רע אצליהם שהי' היא מעלה, אבל בינונים שיש בהם עוד רע ויכול להיות שאפי' בעת התפילה יפול בהם מח\"ז, אצליהם חפזון היא מעלה. וזהו ג\"כ ההפרש בין גאולת מצרים לגאולה העתידה, להיות גאולת מצרים שהי' שם עוד רע הי' חפזון מעלה שברחו מרע שלהם, אבל גאולה שלע\"ל שלא יהי' שם עוד רע כמ\"ש ואת רוח הטומאה אעביר מן הארץ שם בלא חפזון יותר נעלה. ובכלל המעלה של גאולה לע\"ל לגבי גאולת מצרים ההפרש הוא בין חיצוניות הלב לפנימיות הלב, בין אהבה כמים הפנים אל הפנים לאהבה דבכל מאודך, דבאהבה דבכל מאודך כתי' ומל הוי' את לבבך אבל באהבה דכמים הפנים כתי' ומלתם את ערלת לבבכם שיש שם עוד רע, וגם בתי' ערלת יש אותיות רע, ושם כתי' ומלתם אתם בעצמכם שזהו אתעדל\"ת ואח\"כ יהי' אתעדל\"ע, אבל באהבה דבכל מאדך כתי' ומל הוי' שזהו בחי' שאדם אינו יכול לבוא למד' כזו אלא שהו\"ע אתעדל\"ע שלמעלה מאתעדל\"ת. ועתה ניחא מפני שגאולת מצרים שהי' שם עוד רע לכן הי' בחפזון אבל גאולת לע\"ל ששם לא יהי' עוד רע כתי' כי לא בחפזון תצאו ובמנוסה לא תלכון."],[2000460406,"<h3>להבין כו' שגאולת מצרים נמשלה לנר</h3>\n<b></b><b>להבין כו' שגאולת מצרים נמשלה לנר</b>\n<b>להבין</b> ענין מה שנת\"ל<sup data-n=\"1217\">1</sup> שגאולת מצרים נמשל לאור הנר, הלא אי' עד שנגלה עליהם מלך מלכי המלכים וגאלם שהי' גילוי גבוה מאד ואיך נמשל לאור הנר. אך הנה אי' במד\"ר ע\"פ ואכלתם אותו בחפזון פסח הוא, שיצ\"מ הי' בחפזון ע\"ש כי בחפזון יצאת ממצרים, אבל לע\"ל כתי' כי לא בחפזון תצאו ובמנוסה לא תלכון. ואי' בילקוט בשם המכילתא שחפזון זו הי' חפזון דשכינה, ואעפ\"י שאין ראי' לדבר זכר לדבר איכא דכתי' קול דודי הנה זה בא מדלג על ההרים ודילוג הו\"ע חפזון. וצ\"ל איך שייך חפזון על דודי הלא דודי הוא בחי' ת\"ת שהו\"ע ז\"א מדת דאצי' ואיך שייך חפזון הלא הוא מדת יום, בשלמא על שכינה שייך חפזון שהו\"ע מל' ונק' בש' לילה כמ\"ש ליל שימורים הוא, ויש בשימורים ב' פי' א' פי' שמירה מפני שלילה הו\"ע מל' שיורד' להוות ולהחיות ג' עולמות בי\"ע ששם יש רע ושייך שמירה, ופי' הב' של שימורים לשון שימור והמתנה ע\"ד אשה משתמרת לביאה, שפי' ענין זה כאן ששומר וממתין על יחוד דסובב וממלא, שהוא יחוד גדול ויש קנאה ולכן צריך שמירה, אבל מדות דאצי' ששם כתי' לא יגורך רע ואיך שייך שמירה. והוא ע\"ד ברכה ראשונה של ברכות נשואין שאינה חותמת בברוך מפני שהוא כנגד אדם שהוא מדות יום. וכמו\"כ למעלה מדות דאצי' שהוא מדות יום איך שייך חפזון, ואף שיש קליפה שהוא כנגד אצי' מ\"מ מעמדה היא בבריאה ושם דוקא שייך שמירה למל'.\n<b>והענין</b> הוא דהנה אי' בזהר ע\"פ אכלו ריעים שתו ושכרו דודים, דודים הוא דתיאבין דא לדא ולא משתכחין, שפי' ענין ריעים ודודים הוא שריעים הוא יחוד י\"ה בחי' חו\"ב, והם תרין ריעין דלא מתפרשין לעלמא וזווגייהו תדירו, ודודים הו\"ע יחוד ו\"ה וזווגייהו לפרקים, ולכן י\"ל חפזון גם על המשפיע שלא יהי' מונע היחוד, ולכן בגאולת מצרים שהי' יחוד ו\"ה לפרקים לכן הי' בחפזון, אבל לע\"ל לא יהי' בחפזון. ולהבין זה הנה כתי' והי' ביום ההוא יהי' הוי' אחד ושמו אחד, ואי' בלקו\"ת מהאריז\"ל שפי' שעכשיו ש' הוי' הוא י\"ה ו\"ה, שי\"ה זווגייהו תדירו אבל ו\"ה זווגייהו לפרקים, ולע\"ל יהי' ש' הוי' ב\"פ י\"ה שו\"ה יהי' ג\"כ כמו י\"ה שזווגייהו תדירא, לכן יהי' בלא חפזון.\n<b>אך</b> עתה צ\"ל למה אמר אעפ\"י שאין ראי' לדבר הלא הוא ראי' גמורה על דודי. אך הנה באמת עיקר חפזון שייך רק על שכינה שהו\"ע מל' כמ\"ש ושכנתי בתוכם, גלו לבבל שכינה עמהם, אנכי ארד עמך מצרים שזה קאי על בחי' מל', אך הואיל שבחי' דודים הו\"ע ז\"א ומל' שהוא בחי' ו\"ה ובה' שייך חפזון מפני שהו\"ע מל', יש",[["1217","1","<b>להבין ענין מה שנת\"ל</b>: הנחה מד\"ה ”והנה בילקוט פ' בא\" הנדפס לעיל ע' קמט. (והוא המשך לד\"ה וככה תאכלו אותו וד\"ה אור לארבעה עשר שלפני\"ז). המאמר נדפס כאן מכת\"י מעתיק מס' 1185.\nהמ\"מ למאמר זה, ראה לעיל בפנים הספר ולעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."]]],[2000460407,"לומר ג\"כ חפזון על דודי שהו\"ע משפיע שלא יהי' מונע היחוד, ולכן אינו רק זכר לדבר.\n<b>נמצא</b> נתבאר מפני מה יצ\"מ דוקא הי' בחפזון, אבל צ\"ל מפני מה יצ\"מ מפני שנמשל לנר הי' בחפזון ולא הי' גאולה שלימה, אבל לע\"ל שנמשלה לאור היום כמ\"ש ולילה כיום יאיר לא יהי' בחפזון ויהי' גאולה שלימה. ולהבין ענין זה הנה אי' בתרגום יונתן ע\"פ כי אתה נרי הוי' והוי' יגיה חשכי, פי' הוי' יפקינני מחשוכא לנהורא, נמצא שמפרש הפסוק על עוה\"ז ועוה\"ב. ובמד\"ר תהלים אי' בפירוש שגאולת מצרים נמשלה לנר ולכן לא הי' גאולה שלימה, שמתחילה בגאולת מצרים נגאלו ע\"י משה ואהרן ואח\"כ גלו לבבל ואח\"כ נגאלו ע\"י חנני' מישאל ועזרי' וגלו למוקדון ונגאלו עוד ע\"י מתתיהו ובניו וחזרו וגלו עד שאמרו אין אנו רוצים עוד ליגאל ע\"י בשר ודם אלא נמתין לאור הבוקר, היינו לאורו של הקב\"ה שיהי' אל הוי' ויאר לנו ויהי' אז גאולה שלימה, וזה מ\"ש והוי' יגיה חשכי.\n<b>ולהבין</b> כ\"ז צ\"ל איך נמשלה יצ\"מ לאור הנר הלא אי' עד שנגלה עליהם ממה\"מ וגאלם שהי' גילוי גבוה ואיך נמשל לנר. אך הנה כתי' מלכותך מלכות כל עולמים, פי' מלכות כל עולמים הוא מדות מל' דאצי' שיורד להחיות ולהוות מציאות היש דג' עולמות בי\"ע כמ\"ש כל הנקרא בשמי ולכבודי בראתיו יצרתיו אף עשיתיו, ופי' עולמים לשון רבים שבריבוי השתל' נעשה העלם אחר העלם ריבוי העולמות, ופי' מלכותך מלכות כל עולמים הו\"ע מל' דא\"ס כמו שהוא כלול בעצמותו עד\"מ אור וזיו השמש כמו שהוא כלול בגוף כדור השמש ה\"ה בטל לגמרי במקורו, ומה שמאיר לארץ ולדרים עליה אינו רק התפשטות מזיו ואור השמש, כמו\"כ למעלה כי יש אור שם ומל', ומל' דא\"ס כלול בעצמותו וזהו\"ע עד שלא נברא העולם הי' הוא ושמו בלבד, כי שמו כמו שהוא כלול בהוא שהוא ושמו אחד, וגם הוא ר\"ת הוא ושמו אחד, וזהו פי' מלכותך מלכות כל עולמים שמל' דא\"ס מאיר במל' דאצי' שיהי' גילוי בעולמות.\n<b>ומעתה</b> יובן הפי' נגלה עליהם כו' מלכים הו\"ע יחוד ז\"א ומל', מלכי הו\"ע חו\"ב, ומלך הו\"ע אור הכתר דכתר עליון איהו כתר מל', שהו\"ע מל' דא\"ס, ואף שהי' גילוי כ\"ע דאיהו כתר מלכות מ\"מ נמשלה לאור הנר כי כמו נר הוא בשמן ואור ופתילה ויש ב' גוונין אור רק בכלל הוא אור אחד, ובלה\"ק פי' נר הוא כלי המחזיק שמן ואור ופתילה, ופי' שמן הו\"ע חכ' ופתילה הו\"ע יסוד ואור הוא אור הכתר, לכך אף שהי' גילוי כתר עליון דאיהו כתר מלכות אך הואיל שנתגלה ע\"י ד' אותיות דש' הוי' נמשלה לנר. וגם כי כמו נר שמדליקו בבית אינו רק דוחה החושך ולא מהפך, והראי' כשמכבין את הנר חוזר, כמ\"כ גאולת מצרים הגם שהי' גילוי ממה\"מ דאיהו כתר עליון מ\"מ לא הי' גאולה שלימה שחזרו ונשתעבדו לכן נמשלה לנר. אבל לע\"ל שהגאולה נמשלה לאור היום ולילה כיום יאיר יהי' גאולה שלימה. וההפרש בין גאולת מצרים לשארי גאולות דזמה\"ז הוא למשל כמו בין אור הנר"],[2000460408,"לאור האבוקה, אור הנר מאיר רק במקום שהוא דולק אבל אבוקה מאיר למרחוק, כן גאולת מצרים שהי' גילוי ממה\"מ נמשלה לאבוקה שהי' הגאולה לזמן רב לערך תשע מאות שנה, וגם הי' ניסים היוצאים מדרכי הטבע, אבל שארי הגאולות נמשלו לאור הנר שהיו לזמן מועט וגם הניסים היו מוסתרים בדרכי הטבע. אך מ\"מ גם גאולת מצרים נמשלה לנר, כי אבוקה נק' ג\"כ בש' נר כמו שאי' בגמ' מס' סוטה ע\"פ כי נר מצוה ותורה אור משל לאדם אחד שנזדמן לו אבוקה של אור וניצל מן הקוצים ומן הברקנים וזה קאי על נר מצוה הרי נמצא שאבוקה נק' ג\"כ בש' נר.\n<b>נתבאר</b> שגאולת מצרים אף שהי' גילוי ממה\"מ דאיהו כתר עליון רק מפני שנתגלה ע\"י ד' בחי' דש' הוי' חו\"ב וז\"א ומל' לכן נמשלה לאור הנר, והגם שבכמה דרושים נת' שהגילוי לא הי' ע\"י ד' בחי' הנ\"ל, לא הפי' שלא הי' כלל ע\"י ד' בחי' הנ\"ל רק שלא הי' בדרך התלבשות, שאם הי' בדרך התלבשות לא הי' נגוף ורפוא מפני שיש מדת הדין המנגד שטען הללו והללו, רק שהי' הגילוי בדרך מעבר והי' נגוף למצרים ורפוא לישראל. ומאחר שהוא הי' בדרך מעבר ע\"י ד' בחי' חו\"ב ז\"א ומל' לכן נמשלה לאור הנר ולא הי' גאולה שלימה, אבל לע\"ל שנמשלה לאור היום והי' אור הלבנה כאור החמה, ולילה כיום יאיר, יהי' גאולה שלימה. ובזה יובן ההפרש שיש בשירים, שבעוה\"ז השיר בלשון נקבה ולע\"ל יהי' שיר לשון זכר, כי כמו נקבה יולדת ומתעברת אף שיולדת מכל מקום היא מתעברת כן גאולת הזמן הזה נמשלה לנקבה שנגאלו ונשתעבדו נגאלו ונשתעבדו, אבל לע\"ל שיהי' הגאולה כמו אור היום בלא שינוים יהי' השיר לשון זכר. ע\"ד ברכות נשואין שברכה ראשונה שהוא מדת יום הוא בחי' אדם אבל ברכה שני' שהוא מדת לילה הוא מדת חוה, כמו\"כ לע\"ל שיהי' הגאולה נמשל לאור היום יהי' שיר לשון זכר שיהי' גאולה שלמה.\n<b>ומעתה</b> יובן פי' נר מצוה ותורה אור, כי פי' תורה אור אינו אור סתם אלא אור יום, כמו אור יום שיהי' לע\"ל, כי תורה נק' בשם אור יום כמו שאי' בגמ' הנ\"ל כיון שעלה עמוד השחר ניצול מכל וזה קאי על תורה הרי התורה נק' בש' יום וכמ\"ש והיו הדברים האלה אשר אנכי מצווך היום, והיו הדברים, בדברי תורה הכתוב מדבר, אשר אנכי, זהו בחי' אנכי מי שאנכי, מצוה, לשון צוותא וחיבור, היום, שכולו יום, שתורה הוא למעלה מהזמן. וזהו ההפרש שבין נר מצוה לתורה אור, כי המצות נק' בש' נר הגם שמצות הם תרי\"ג מצות דאורייתא וז' מצות דרבנן שהם תר\"ך עמודי אור שהוא אור הכתר, אך כ\"ז הוא שורש המצות כמו שהן למעלה אבל מצות כשנמשכים למטה נק' בש' מצות המלך שמלך הוא מקור על זמן כמ\"ש מלך מלך וימלוך שהוא ענין זמן, כי מצות תלוי בזמן, עד\"מ מצות מצה אינו שייך רק בפסח אבל לא לאחר הפסח, וכן מצות סוכה אינו שייך רק בסוכות אבל לא כל השנה, אבל תורה יכולים ללמוד הלכות פסח בסוכות והלכות סוכות בפסח ולא יסתור כלל. ואף שאי' דבר בעתו מה טוב, אינו רק מה טוב, אבל עכ\"פ מקיים מצות לימוד התורה ג\"כ כשלומד שלא בזמנו, הרי תורה למעלה מהזמן. וזהו שאי' הכל"],[2000460409,"מודים שבשבת ניתנה תורה, כי בשבת גם הלילה נק' יום כמ\"ש בשי\"ב ויהי ערב ויהי בוקר ועל יום השבת לא כתי' ויהי ערב ויהי בוקר, וזהו שאי' במד\"ר ל\"ו שעות שמשה אותה אורה י\"ב שעות של ע\"ש וי\"ב שעות דליל שבת וי\"ב דיום השבת. נמצא שתורה הוא ענין אור היום שלמעלה מהזמן וכמ\"ש והגית בו יומם ולילה שתורה היא למעלה מהזמן. וגם אי' אין לך בן חורין גדול יותר מהעוסק בתורה, הרי התורה היא ענין חירות כמו לע\"ל מפני שהיא אור יום. והגם שבמצות גם כן כתיב והי' אם שמוע תשמעו אל מצותי אשר אנכי מצוה אתכם היום, הרי נקרא ג\"כ בשם יום, אך עם כל זה הם לאו דוקא יום רק תלוי בזמן כי המצות ניתנו בזמן ומקום וכלי, שיש מצות התלוים בזמן ויש מצות התלוים במקום וגם מצות התלוים בכלי כגון כלי המקדש, אבל תורה ה\"ה למעלה מהזמן נקרא בשם יום כמו אור יום שאינו נשתנה כן תורה הוא קיום לעולם, כי מעין ודוגמא שלע\"ל שנמשלה לאור היום יש גילוי מעט בתורה, ולכן נקרא תורה אור. נמצא שנתבאר ההפרש שבין גאולת מצרים לע\"ל, שגאולת מצרים נמשלה לאור הנר, הגם שהי' הגילוי של ממה\"מ אך מ\"מ הי' הגילוי ע\"י ד' בחי' חכמה ובינה וז\"א ומלכות לכן נמשלה לאור הנר ולא הי' גאולה שלימה והי' בחפזון, אבל לע\"ל שנמשלה לאור היום ויהי' גאולה שלימה ויהי' ונסו יגון ואנחה, ויהי' שמחת עולם על ראשם ולא בחפזון תצאו ובמנוסה לא תלכון.\n<b>ועוד</b> יש הפרש בין גאולת מצרים לע\"ל ע\"ד מ\"ש קומה הוי' למנוחתיך, קומה הוי' ויפוצו אויבך. קומה הוי' למנוחתיך קאי על גאולה העתידה להיות, וקומה הוי' ויפוצו אויביך קאי על יציאת מצרים, כי ביציאת מצרים כתי' וחמושים עלו בני ישראל ופירש רש\"י ושרשו מירושלמי שחמשה כלי זיין הי' סייף קשת תריס עלה רומח, שהי' צריכים למלחמה כמ\"ש הוי' איש מלחמה, הוי' ילחם לכם, הגם שהי' הוי' מ\"מ ילחם והיכן שייך מלחמה אצל אויב כמ\"ש כי תצא למלחמה על אויבך לכך כתי' קומה הוי' ויפוצו אויבך, אבל לע\"ל שלא יהי' עוד מלחמה כמ\"ש וכתתו חרבותם לאיתים וחניתותיהם למזמרות לא ישא גוי אל גוי חרב ולא ילמדו עוד מלחמה לכן כתי' קומה הוי' למנוחתיך. וכן מצינו בילקוט כשרצה דוד לבנות את בהמ\"ק אמר לו הקב\"ה אתה לא תבנה הבית כי אם שלמה בנך כו', והיינו מפני שדוד הי' איש מלחמה, והכתוב קראו איש הדמים, אבל שלמה עליו כתי' והוא יהי' איש מנוחה, והמקדש שהוא מעין דלע\"ל לכן צריך להיות דוקא ע\"י איש מנוחה. וההפרש שבין יצי\"מ לגאולה שלע\"ל, שביצ\"מ שהי' שם עוד רע והי' צריך עוד מלחמה לכן כתי' קומה הוי' ויפוצו אויבך, אבל לע\"ל שלא יהי' עוד רע כמ\"ש אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם הוי' ולעבדו שכם אחד, שכל מה שיוכל להתברר יתברר, לא שייך שם עוד מלחמה, לכך כתיב קומה הוי' למנוחתיך שאז יהי' מנוחה."],[2000460410,"<h3>אז ישיר משה</h3>\n<b>הנחה בס\"ד שביעי ש\"פ</b>\n<b>אז</b> ישיר משה<sup data-n=\"1218\">1</sup> ובנ\"י את השירה הזאת לה' ויאמרו לאמר אשירה להוי' כי גאה גאה סוס ורוכבו רמה בים, ואי' במד\"ר כל פרגמטי' של משה הוה באז, קנטורו הי' באז כמ\"ש ומאז באתי אל פרעה לדבר בשמך הרע לעם הזה, שירתו הי' באז כמ\"ש אז ישיר כו', וצ\"ל מהו מעלת ויתרון של אז. אך להבין זה צ\"ל תחילה כמה דקדוקים שיש בפסוק הזה, א' מה שכתי' ישיר משה ובנ\"י חשיב משה ובנ\"י שני כללים בפ\"ע וכתי' ישיר ל' יחיד, הל\"ל ישירו ל' רבים. ואי הוה כתי' בנ\"י לחוד ניחא שכתי' ישיר ל' יחיד כמו שמצינו מ\"ש אז ישיר ישראל עלי באר ענו לה, אבל כאן שכתי' משה ובנ\"י שני כללים למה כתי' ישיר לשון יחיד הל\"ל ישירו. ועוד מהו פי' את השירה הזאת ומהו הכפל לשון של ויאמרו לאמר. ולהבין כ\"ז צ\"ל תחילה מהו\"ע קי\"ס שכתי' וידעו מצרים כי אני הוי' וצ\"ל מהו\"ע הידיעה הלא כתי' בפרשה זה גופא ולא נשאר בהם עד אחד וכמ\"ש בתהלים ויכסו מים צריהם אחד מהם לא נותר. אך הענין הוא דאיתא על שלשה דברים העולם עומד על תורה ועבודה וגמ\"ח, שעל שלשה דברים אלו יש לעולם קיום, על תורה כמ\"ש אם לא בריתי יומם ולילה חוקות ארץ ושמים לא שמתי, ועבודה הו\"ע קרבנות וכתי' לנטוע שמים וליסוד ארץ, וזה קאי על קרבנות כמ\"ש ע\"פ סולם מוצב ארצה וראשו מגיע השמימה פי' מוצב ארצה דא כבש המזבח וראשו מגיע השמימה דא ריחו העולה למעלה, וגמ\"ח הו\"ע חסד וכתי' וחסד ה' מעולם ועד עולם.\n<b>ולהבין</b> ענין העמידה צ\"ל תחילה ענין עבודה וגמ\"ח מהו\"ע עבודה. הנה עבודה הו\"ע קרבנות, ומהו\"ע קרבנות שע\"י שמקריבין בהמה גשמי' ע\"ג המזבח הי' יורד אש מלמעלה ואוכל את הזבח שזהו\"ע המשכה ובזהר נק' ארי' דאכל קורבנין שהאש שהי' יורד הי' כדמות ארי' וארי' הו\"ע חסד, אך זהו בזמן שבהמ\"ק הי' קיים אבל עכשיו שאין קרבנות, תפלה כנגד תמידין תיקנו, שע\"י שמקריב נה\"ב למעלה, עולה ונכלל באהבה רבה הבאה לו מלמעלה שזהו ג\"כ ענין המשכה, והיכן הוא מרומז בתפלה בח\"י ברכאן דצלותא ברוך אתה ה', פי' ברוך הו\"ע ברכה והמשכה כמ\"ש ברוך הוי' מעולם ועד עולם, שהו\"ע המשכה מעלדאת\"כ לעלדאת\"ג. והנה ענין עלדאת\"כ ועלדאת\"ג הוא כמארז\"ל כל מה שיש ביבשה יש בים חוץ מחולדה, רק ההפרש הוא שברואים שבים הם מובלעים בתוך מי הים ואינם נראין ונגלין, וזהו\"ע עלדאת\"כ, אבל ברואים שביבשה הם נראים ונגלים וזהו\"ע עלדאת\"ג. והנה בקבלת חיותם יש ג\"כ הפרש שהברואים שבים הם מובלעים במי הים ואינם יכולים ליפרד מהים אפי' על רגע א' כי דגים שבים מיד שהם פורשים מיד מתים, אבל ברואים שביבשה יכולים להיות נפרדים, אפי' צומח הגם שמקבל חיות מן הארץ",[["1218","1","<b>אז ישיר משה</b>: הנחה מד\"ה זה הנדפס לעיל ע' קנב. מאמר זה הוא מכת\"י מעתיק מס' 1185.\nהמ\"מ למאמר זה, ראה לעיל שם (ע' קנב ואילך), ולעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."]]],[2000460411,"מ\"מ אנו רואים שדוקא כשהוא בקטנות צריך לארץ אבל לאחר שנתגדל יכול להיות נפרד מן הארץ, וכ\"ש חי ומדבר, והגם שהם ג\"כ מקבלים חיות מן הארץ שכתי' ארץ ממנה יצא לחם, מ\"מ אנו רואים שיכול ליזון באויר ושט ע\"פ המים, כמו\"כ יש הפרש בין עלדאת\"כ לעלדאת\"ג שבעלדאת\"כ עומדים תמיד בביטול ואינם יכולים להיות נפרדים מאלקות אפי' רגע אחת, אבל ברואים שבעדאת\"ג יכולים להיות נראים נפרדים מאלקות. והנה בנפש האדם יש ג\"כ ענין עלדאת\"כ ועלדאת\"ג שהו\"ע מח' ודיבור, מח' הו\"ע עלדאת\"כ מפני שהוא העלם העצמי לגבי עצמו שיכול לחשוב אדם כל היום ואין הזולת יודע מה שהוא חושב והו\"ע עלדאת\"כ, אבל דיבור הוא דבר לזולתו שהדיבור הוא נפרד וגם המקבל הוא ג\"כ נפרד והו\"ע עלדאת\"ג. לכן מצינו במשה שכתי' אצלו מן המים משיתיהו שהי' מעלדאת\"כ רק שנשפל בעלדאת\"ג, לכן אמר כבד פה אנכי כי דיבור הו\"ע עלדאת\"ג, והגם שנשפל בעלדאת\"ג מ\"מ להשפיל א\"ע לידי דיבור כ\"כ לא הי' יכול לכך אמר כבד פה אנכי. וזהו\"ע עבודת הכהנים להמשיך מעלדאת\"כ לעדאת\"ג, שיהי' הביטול בעלדאת\"ג כמו בעלדאת\"כ, וזהו ג\"כ הפי' ברוך אתה הוי' להמשיך מעלדאת\"כ לעלדאת\"ג שיהי' הביטול בעלדאת\"ג כמו בעלדאת\"כ.\n<b>וענין</b> עבודת הלוים הוא ג\"כ שיהי' התחברות עלדאת\"כ לעלדאת\"ג כמ\"ש ועבד הלוי הוא, פי' הוא הו\"ע עלדאת\"כ, רק עבודתם הי' שתתעלה עלמא דאתגלי' לעלדאת\"כ. וע\"י מה הי' עבודתם, ע\"י שירה וזמרה, כי כשאדם צריך לעלות במדריגה יותר גבוה צריך להיות דוקא ע\"י שירה וזמרה, והוא ע\"ד כמו שאנו רואים באדם שמתבונן באיזה דבר ומבין ההתבוננות ויש לו התפעלות מההתבוננות מ\"מ אינו ניכר ההתבוננות, אך כשמנגן איזה ניגון אז ניכר ההתבוננות, כי ניגון הו\"ע תנועות וכל תנועה הוא מוליד חום ומוליד ההתפעלות. וזהו משארז\"ל כל בעלי השיר יוצאין בשיר, פי' יוצאין בשיר כי לצאת מגדר הגבלה הוא דוקא ע\"י שיר, ובעלי השיר קאי על מלאכים ונשמות, כי מלאכים יש להם ג\"כ גופים רק שהגופים שלהם הם דקים יותר, כי באדם הגוף שלו הוא מד' יסודות ארמ\"ע והגופים שלהם הוא מב' יסודות ומאיזה שבהם מהדקות מאש ורוח, כמ\"ש עושה מלאכיו רוחות משרתיו אש לוהט, לכן כשצריכים לצאת מגדר הגבלתם הוא דוקא ע\"י שירה. וכן נשמות יושבין בג\"ע ומשיגין השגות שהשגה הו\"ע הגבלה, ולכן כשצריכין לצאת מהשגה להשגה זהו דוקא ע\"י שירה וזמרה, וזהו ג\"כ עבודת הלוים שע\"י שירה וזמרה עולים מעלדאת\"ג לעלדאת\"כ.\n<b>וזהו</b> פי' מה שכתי' אז ישיר משה ובנ\"י את השירה הזאת, פי' זאת כי הנה כתי' לזאת יקרא אשה כי מאיש לוקחה זאת, איש קאי על הקב\"ה ואשה הוא מדת המל' כנס\"י מקור נש\"י, וזהו פי' השירה הזאת שמל' אומרת שירה. ולכאורה צ\"ל איך שייך לומר שמל' יאמר שירה, בשלמא כל הנבראים מלאכים וכל צבא מעלה שיש להם גופים ונפש שייך לומר שהם אומרים שירה אבל מל' שהיא ספי' מע\"ס ואיתא הוא אינון ואינון הוא, והאיך שייך שאומרת שירה. ובאמת מצינו שמל' אומרת"],[2000460412,"שירה כמו שאיתא בזהר נהורא תתאה קורא תדיר לנהורא עילאה ולא שכיך, וקאי על מדת המל', כמ\"ש אלקים אל דמי לך אל תחרש ואל תשקוט אל. אך הענין הוא דהנה אי' בזהר איהו וחיוהי חד איהו וגרמוהי חד, פי' איהו וחיוהי כשאיהו מתייחד עם האורות, ופי' איהו וגרמוהי כשאיהו מתייחד עם הכלים. כי הנה מה שאנו קוראים חכ' וחסד אינו קאי על האורות, כי האורות שוים בכל הע\"ס, רק שזה קאי על הכלים, כלי החכ' וכלי החסד, ולפעמים נק' הכלים בש' גופים כדאי' וכמה גופים תקינת לון, ואי' שם וכד אנת תסתלק מנהון אשתארו כולהו שמהן כגופא בלא נשמתא, שכד אנת שהוא האורות מסתלק מן הכלים אשתארו כגופא בלא נשמתא, כמו שאנו רואים באדם בעת שישן שהנשמה מסתלק מהגוף ולא נשאר בגוף רק קיסטא דחיותא, וכמו\"כ כאשר מסתלק האורות המאיר בהכלים אשתארו הכלים כגופא בלא נשמתא, רק קיסטא דחיותא נשאר בהם. ומוכרח לומר שהקיסטא דחיותא שנשאר בהם הוא מהארת הקו גופא, כמו באדם שכשהוא ניעור מאיר בו החיות בגילוי בשכל ובמדות אבל כשהוא ישן נסתלק ממנו החיות ונשאר בו רק קיסטא דחיותא, אך הקיסטא דחיותא הוא מחיות הנפש גופא שאנו רואים שיש לו הרכבת חלומות, וכמו\"כ הכא ג\"כ כשמסתלק האורות מן גרמוהי ונשאר בהם קיסטא דחיותא הוא ג\"כ מהארת הקו גופא, כי דבר שבקדושה אינו נעקר לגמרי כמו שאיתא במשנה לענין בהכנ\"ס הגם שנחרב יש בו ג\"כ קדושה דכתי' והשימותי את מקדשיכם וקאמרינן מקדשיכם אפי' כשהן שוממין, ובהכנ\"ס הוא מקדש מעט לכן גם כשנחרב יש בו קדושה מפני שדבר שבקדושה אינו נעקר ממקומו לגמרי, כן הכא כשהאורות מסתלקים מהכלים מ\"מ נשאר בהכלים רשימה מהארת הקו שזהו בחי' איהו וגרמוהי שאין דבר שבקדושה נעקר לגמרי ומוכרח לומר כן, כי הנה אי' בתניא איהו וגרמוהי שאיהו מתייחד עם גרמוהי כדי לברוא בו וע\"י בריאה יש מאין, כי עיקר בריאה הוא מאיהו ובלא איהו אינו יכול להיות בריאת העולמות, ומה שהוא נמשך ע\"י גרמוהי דוקא הוא בכדי שיוכל להיות ריבוי ההתחלקות וריבוי התהוות הנבראים, וכתי' המחדש בכל יום תמיד מע\"ב שחיות העולמות וקיום העולמות והתהוות העולמות הוא בכל עת ורגע, א\"כ מוכרח לומר שכשהאורות מסתלקים מן הכלים ונשאר בהם קיסטא דחיותא הוא רשימה מאור הקו גופא שזהו בחי' איהו וגרמוהי שאל\"כ הי' חוזר העולם לתוהו ובוהו.\n<b>וזהו\"ע</b> מה שמל' אומרת שירה שתוכלל מבחי' איהו וגרמוהי לבחי' איהו וחיוהי שזהו שיר שלמעלה מעבודת הכהנים ומעבודת הלוים, שעבודת הכהנים הוא המשכה מעלדאת\"כ לעלדאת\"ג ועבודת הלוים הוא העלאה מעלדאת\"ג לעלדאת\"כ והשיר הזה הוא למעלה מעלדאת\"כ ומעלדאת\"ג, ובקי\"ס ג\"כ שהפך ים ליבשה שעלדאת\"כ נעשה עלדאת\"ג אמרו שירה שהו\"ע העלאת מבחי' איהו וגרמוהי לאיהו וחיוהי.\n<b>ובעבודה</b> בנפש האדם מצינו ג\"כ בחי' שירה הזאת, כי יש אדם שצריך לשיר והתפעלות זהו כמו שיר הלוים, אכן יש בחי' רעו\"ד רצון פשוט ליכלל"],[2000460413,"בעצמותו ית' בלא התפעלות כמ\"ש אם ישים אליו לבו זהו בחי' שירה, היינו העלאה מבחי' איהו וגרמוהי לאיהו וחיוהי. וזהו מ\"ש אתה הוא הוי' לבדך, אתה קאי על עבודת הכהנים כמ\"ש אתה כהן לעולם על דברתי מלכי צדק, שזהו\"ע המשכה מעלדאת\"כ לעלדאת\"ג. והוא קאי על עבודת הלוים כמ\"ש ועבד הלוי הוא, שזהו העלאה מעלדאת\"ג לעלדאת\"כ, לבדך הוא מצד מ\"ש ונשגב הוי' לבדו ביום ההוא, שזהו בחי' גבוה מעלדאת\"כ ומעלדאת\"ג. ובקי\"ס שכתי' ויולך הוי' גו' ברוח קדים, רוח קדמונו של עולם, שהי' מד' גבוה שלמעלה מעלדאת\"כ ומעלדאת\"ג, אז אמרו שירה שלמעלה מהשיר של הכהנים והלוים. ועתה יובן מה שכתי' משה ובנ\"י שני כללים וכתי' ישיר לשון יחיד, והיינו מפני שמשה הי' מעלדאת\"כ ובנ\"י הם מעלדאת\"ג, ועכשיו שהי' מד' גבוה שלמעלה מעלדאת\"כ ומעלדאת\"ג שגם עלדאת\"כ שוה כמו עלדאת\"ג לכן כתי' ישיר לשון יחיד להורות שבאו למדריגה שלמעלה מעלדאת\"כ ומעלדאת\"ג, שבנ\"י היו ג\"כ במדריגת משה, והגם שהיא מדריגה גבוה כ\"כ מ\"מ השיגו בנ\"י ג\"כ לשם, והיינו מפני שראתה שפחה על הים מה שלא ראה יחזקאל בן בוזי הכהן.\n<b>ועתה</b> יובן מהו המעלה של אז, כי מהו ענין אז, אז הוא אל\"ף זיי\"ן שהא' הוא על הז', ז' הוא ז' ימי בראשית שנת' בכמה מקומות [שהוא בחי'] גבוה מאד, וא' הוא למעלה מהז' שבז' ימים יש בחי' שבת וא' הוא למעלה משבת שהוא בחי' תענוג, כמ\"ש אז תתענג על הוי' שלמעלה מבחי' ש' הוי' ובשבת כתי' שבת לה' הרי תענוג למעלה משבת, ולכן כתי' וקראת לשבת עונג שצריכים לקרות בשבת עונג, שבחי' עונג הוא למעלה משבת. אף שבשבת כתי' שער החצר הפנימי' הפונה קדים סגור יהי' ששת ימי המעשה וביום השבת יפתח, שבשבת מתגלה בחי' זו, מ\"מ עונג למעלה משבת.\n<b>ועתה</b> יובן הפי' לשון של ויאמרו לאמר, שזהו ע\"ד מארז\"ל כל עיסקא דשבתא כפול, עומר כפול מזמורו כפול קרבנו כפול, כי יש ב' בחי' שבת, שבתא דמעלי שבתא ושבתא דיומא, וזהו\"ע כפול עילוי אחר עילוי, וכמ\"כ הכא לכן הוא כפול מפני שהי' עילוי אחר עילוי. אשירה להוי שהשיגו מדריגה גבוה שהוא בחי' המשכה לש' הוי', סוס ורוכבו רמה בים רמה פרש\"י השלכה והיינו מפני שמצרים התנשאו לקבל השפעה ממקום גבוה ששם כחשיכה כאורה, והגם ששם כחשיכה כאורה מ'מ לא קיבלו רק השפעה מבחי' אחוריים לכך פרעה אותיות העורף אבל בחי' פנימי' אינו מאיר אלא לבנ\"י דוקא, כמ\"ש יאר הוי' פניו אליך דוקא, לי ולא לו, ולכן בקי\"ס שהי' מאיר מפנימי' דש' הוי' נטבעו בים כמ\"ש אם תגביהי כנשר משם אורידך נאום הוי', וזהו וידעו מצרים כי אני הוי' מאחר שהי' מפנימי' דש' הוי' נטבעו בים.\n<b>ועתה</b> יובן מה שאי' על שלשה דברים העולם עומד, כי מהו\"ע עולם, עולם הוא לשון העלם, ובריבוי העלמות יש ריבוי שינויים, וכדי שיהי' בבחי' עמידה"],[2000460414,"דהיינו בבחי' קיום צריך להמשיך מבחי' אני הוי' לא שניתי, וזהו ע\"י ג' קוין שזהו כהנים בעבודתם שהוא המשכה מעלדאת\"כ לעלדאת\"ג, ולוים בדוכנם שהוא העלאה מעלדאת\"ג לעלדאת\"כ, ותורה הוא בחי' קו האמצעי וז\"ע ישראל במעמדם וכמ\"ש ויקם עדות ביעקב ותורה שם בישראל. ובקי\"ס מצינו ג\"כ שהי' ג' קוין כמ\"ש והמים להם חומה מימינם ומשמאלם, ימין הו\"ע חסד שמאל הו\"ע גבורה וישראל הלכו באמצע, וע\"י ג' קוין אלו ממשיכים שיהי' עמידה וקיום בעולם, בחי' אני הוי' לא שניתי, זה הוי' קיוינו לו."],[2000460415,"<h3>כל הולך על גחון</h3>\n<b></b><b>בס\"ד פ' שמיני תרל\"ט הנחה</b>\n<b>כל</b> הולך על גחון<sup data-n=\"1219\">1</sup> וארז\"ל למה נקראו ראשונים סופרים שהיו סופרים אותיות שבתורה שהיו אומרים וא\"ו דגחון אמצע של תורה באותיות, עי' תלוי' דיכרסמנה חזיר מיער חצי' של תהלים באותי', ואי' ע\"ז בחידושי אגדות של מהרש\"א וא\"ו דגחון מפסיק כח הנחש שנתקלל על גחונך תלך וע' דיכרסמנה חזיר מיער מפסיק כח דחזיר שכתי' אצלו כי מפריס פרסה הוא, וצ\"ל מהו הענין של הוא\"ו והע' ומהו\"ע של החצי. אך הענין הוא דהנה תהלים מכוון כנגד תורה, כמו שתורה נחלקת לחמשה ספרים כמו\"כ תהלים יש בו ג\"כ ה' ספרים, ולמאן דסבר שתורה נחלקת לז' חצבה עמודיה שבעה כך תהלים נחלק לשבעת ימי השבוע, אך ההפרש בין תורה לתהלים הוא מה שאי' בגמ' כל מי שיש בו תורה ואין בו יראת שמים דומה לגזבר שנמסרו לו מפתחות הפנימי' ומפתחות חיצוני' לא נמסרו לו בהי עייל, שאין לו פתח לעייל, ובכלל קאי על תורה ותהלים שתורה נק' מפתחות הפנימי' ותהלים נק' מפתחות החיצוני' מפני שתהלים הו\"ע סיפור ושבח של מקום, השמים מספרים כבוד אל, והללויה מן השמים הללו אל בקדשו כו' שהו\"ע סיפור ושבח של מקום, ולכן כל התפלה ברוב פסוקי דתלים, ולפיכך סיפרו דוד דוקא ואף שידעו מתהלים קודם דוד מ\"מ מי סיפרו דוד דוקא, מפני שדוד הי' מרכבה למדה זו. וע\"פ קבלה תורה הוא בחי' ת\"ת ותהלים הוא בחי' מל' ולכן סיפרו דוד מפני שהי' מרכבה למדת המל'. וזהו מה שאי' בס\"י בשלשה דברים נברא העולם בספר וסיפור וסופר, בספר קאי על תורה וסופר קאי על תהלים, וצ\"ל הטעם מפני מה שתהלים הוא סיפור ושבח של מקום עש\"ז אנו קוראין אותו חיצוני'.\n<b>והענין</b> הוא דכתב רבינו נ\"ע שמפתחות חיצוני' קאי על תפלה, שאו' בתפלה אתה עשית את השמים ואתה מחי' את כולם שהו\"ע מציאות העולם שזהו",[["1219","1","<b>כל הולך על גחון</b>: מאמר זה הוא הנחה מכת\"י 1138. וראה בהנסמן ע\"ז לעיל בהמ\"מ לד\"ה זה להנחות כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."]]],[2000460416,"חיצוני', מפני שזה שנתהוה העולם אינו אלא משם והארה בעלמא שאינו נוגע באוא\"ס כלל. כידוע לחכמי המחקר שיש ב' בחי' השפעה אור ושפע, שפע הו\"ע השפעה פנימי' שפועל שינוי בהמשפיע בין קודם ההשפעה בין שעת ההשפעה, כמו למשל השפעת הרב לתלמידו שצריך לצמצם את שכלו בכדי שיבין תלמידו וצריך לשנות לו דרך קצרה הרי זה פועל בהמשפיע שינוי בין קודם ההשפעה בין שעת ההשפעה. אבל אור הוא דבר שאין בו שינוי כמו נר שמביאין אותה לחדר אפל אין שום שינוי באור אם מאיר או לא, ולכן נק' בש' אוא\"ס מפני שכל התהוות העולמות שנתהווה ממנו ית' אינו נוגע בו כלל ואינו פועל בו שום שינוי, לכן נק' מציאות העולם בש' חיצוני', ותהלים שהו\"ע סיפור ושבח של מקום איך שנבראו העולמות נק' חיצוני', אבל תורה נק' פנימי' כי בתורה כתי' והיו הדברים האלה אשר אנכי מצוך פי' מצוה הוא לשון צוותא וחיבור, אשר אנכי מי שאנכי, כי תורה היא להמשיך א\"ס לכן נק' בחי' פנימיות.\n<b>ולבאר</b> היטב ענין חיצוני' ופנימי' י\"ל כי הנה כמו שאנו רואים באדם שיש בו ג\"כ ענין חיצוני' ופנימי', שג' לבושים מחשבה דיבור ומעשה הם נק' בכלל חיצוני', ובהם גופא יש חיצוני' ופנימיות עד\"מ מעשה הו\"ע חיצוני' לגבי דיבור כי אנו רואים שאדם יוכל לעשות איזה מלאכה ומדבר בעת מעשה, ובמעשה גופא יש חיצוני' ופנימי' למשל כח הזריקה הוא כח היותר חיצון, כי ענין זריקה נמצא גם בבהמה כמו שאי' שהיו צרורות מנתזין מתחת רגלי', אך בהמה מפני שאין לה דעת לכן היא מזקת אבל אדם שמורגל שלא להזיק לכן אינו מזיק שזהו חיצוני' שבמעשה, אבל כתיבה הו\"ע פנימי' שבמעשה שיוכל לכתוב דבר שכל, ומ\"מ בכלל נק' מעשה חיצוני' לגבי דיבור ודיבור לגבי מח' נק' ג\"כ חיצוני' כי מח' הוא גילוי העלם עצמי לגבי עצמו אבל דיבור הוא גילוי לגבי זולתו כי לעצמו א\"צ דיבור כלל, ובדיבור גופא יש פנימי' וחיצוני' היינו כשמדבר דברי עולם הו\"ע חיצוני' שבדיבור אבל כשמדבר דברי תורה או כשמספר שבחו של מקום הו\"ע פנימי' ומ\"מ לגבי מח' נק' דיבור חיצוני', ובמח' גופא יש ג\"כ חיצוני' ופנימי' דהיינו סתם מח' היא חיצוני' ויש עומק המחשבה שהיא פנימי'. ובכלל הג' לבושים אלו הם חיצוני' אך שיש בכל או\"א חיצוני' ופנימי', מפני שיש בכל או\"א חב\"ד חג\"ת נה\"י אך שיש ביניהם לבוש פנימי' תיכונה וחיצונה, ובכלל הם חיצוני' לגבי עצמי' שהוא שכל ומדות שכתב רבינו בתניא ששכל ומדות זהו עצמי' הנפש. אך פעם כתב רבינו בדרוש ששכל ומדות ג\"כ אינם עצמי' הנפש אלא לבוש לעצמי' רק שהוא ע\"ד גוף ונפש שגוף ג\"כ הוא לבוש להנפש רק לא כמו שארי לבושין שיכול לפשוט כמו שיש בגדי חול ובגדי שבת שפושט בגדי חול ולובש בגדי שבת אבל גוף ונפש הוא לבוש שמיוחד עם הנפש שאינו יכול לפשוט כי בע\"כ אתה חי, וגם ה\"ה מתיחד עם הגוף שאין אתה יכול להפליג לומר זה גוף וזה נפש שהם שני דברים נפרדים כי בהם יחוד באופן אחר. כך שכל ומדות לגבי עצמי' הנפש, מ\"מ לגבי לבושין נק' פנימי'. ובזהר אי' שיש ד' בחי' נר\"נ ונשמתא לנשמתא, כמו באדם שיש ראש גוף ורגל שזהו נשמה רוח נפש ונשמתא לנשמתא היא עצמי' הנפש. כך למעלה יש ג' לבושין שהם ג' עולמות בי\"ע"],[2000460417,"שהם נק' חיצוני' לגבי מקור שלהם, דכתי' כי בי\"ה הוי' צור עולמים ביו\"ד נברא עוה\"ב ובה' נברא עוה\"ז, ואפי' עלמין סתימין דלא אתגליין שנבראו ממחשבה ה\"ז ג\"כ חיצוני', אבל ע\"ס נק' פנימי' ששם שורה אוא\"ס, ואף שהם ג\"כ לבושים עכ\"ז ה\"ה ע\"ד לבוש גוף ונפש שהע\"ס מתייחדים עם אוא\"ס, ובע\"ס יש חכמה שהיא ראשית השתל' ששם שורה אוא\"ס יותר משאר הספי', וזהו חכ' שבסדר השתל', ויש חכ' שלמעלה מסדר ההשתל' כמו באדם יש בו חכ' ועומק החכ' מקור החכ', ולמעלה נק' הבחי' הזו לית מחשבה תפיסא בי' כלל.\n<b>וזהו\"ע</b> שתורה נק' פנימי' מפני שבה מאיר פנימי' החכ', כי הנה זהו ידוע שחיצוני' שבעליון נעשה פנימי' לתחתון, ופנימי' שבחכ' שהוא ראשית ההשתל' אינו שורה בשום עולם רק בתורה שאוריי' מחכ' נפקת לכן מאיר בה פנימי' שבעליון, ומפני שתורה היא מד' גבוה לכן ניתנה דוקא בעולם העשי' דלמטה. ע\"ד שכתי' במצרים ועברתי אני במצרים אני ולא מלאך, פי' דוקא במצרים שהוא מקום שפל אני ולא מלאך, והוא ע\"ד אותי' החקוקות על אבן טוב לעוצם בהירותו אינו נראה האותי' כלל אלא דוקא כשנוטלין אותם על שעוה שם נראים, והוא ע\"ד נעוץ תחילתן בסופן התחילה נעוץ דוקא בסופו, כמ\"כ תורה לעוצם רוממותו אינו מאיר אלא למטה.\n<b>ומעתה</b> יובן מה שכתי' כי תשמע בקול הוי' אלקיך לשמור את כל מצותיו גו' לעשות הישר בעיני ה' אלקיך, פי' כי תשמע בקול הנה קול פי' רבינו נ\"ע שהוא התחברות רוחני' בגשמי', ומהו הקול הוא קול של תורה, ובחי' בקול זהו פנימי' שבתורה הארת קו וחוט שמאיר בתורה. וזהו\"ע וא\"ו דגחון הנה וא\"ו הוא במילוי א' ושני וואוי\"ן, א' מורה על אנכי מי שאנכי והב' ואוי\"ן מורה על תושב\"כ ותושבע\"פ, ווא\"ו רבתא הוא המשכת אוא\"ס בתו' כי עיקר לימוד התורה אינו רק ידיעת התורה אלא כדי להמשיך א\"ס בתורה וזהו\"ע לימוד התורה לשמה היינו לש' התורה כדי להמשיך אוא\"ס בתורה. וזהו כי תשמע בקול, כי ע\"י קול של תורה יוכל כל איש להמשיך אוא\"ס בתורה שזהו\"ע וא\"ו דגחון שמפסיק כח הנחש. דהנה נחש בגימט' שטן ושטן הוא יצה\"ר וע\"י וא\"ו דגחון מפסיק כחו לבוא לאהבה את הוי' בכל לבבך בשני יצריך אפי' ביצה\"ר, כי היצה\"ר כמו שהוא למעלה אינו רע כמו שאי' בגמ' שטן ופנינה לשם שמים נתכוונו, והגם שארז\"ל נתן עינו בבית ראשון והחריבו אך זהו אחר ריבוי השתל', ובהארת הקו שבתורה מפסיק כחו של יצה\"ר, לכן נק' תורה תבלין ליצה\"ר אם פגע בך מנוול זה משכהו לביהמ\"ד.\n<b>וענין</b> חצי של תורה, כי הנה בתורה יש חצי של חסד וחצי של גבורה, חצי חסד שנק' תורת חסד, וחצי גבורה זהו עונשין שבתורה, וזהו\"ע מ\"ע ומל\"ת, וזהו ידוע שיניקת חיצוני' הוא מקו השמאל, הגם שאברהם ילד את ישמעאל הרי זה הי' קודם שמל אבל יצחק ילד את עשו אחר שמל מפני שיצחק הוא גבורה ומגבורה יש יניקה לחיצוני', כי גבורה למעלה הו\"ע רשפי אש וכשבא למטה נעשה כעס גמור"],[2000460418,"וכמו באדם כשמתפלל ברשפי אש ולאחר התפלה הוא בא לידי כעס הגם שהכעס הי' תחילה על היצה\"ר מ\"מ ע\"י השתל' נעשה רע. אך זהו דוקא כשהוא מגבורה לחוד, אבל כשנכלל חסד וגבורה ביחד לאכללא שמאלא בימינא נפסק יניקת חיצוני', וזהו ע\"י חצי של תורה שנק' ת\"ת שכולל חסד וגבורה אז נפסק כח יניקת חיצוני', ולא ת\"ת לחוד כולל חסד וגבורה אלא הארת הקו שבתורה שמחבר חו\"ג הוא מפסיק יניקת חיצוני', כמ\"ש המשל ופחד עמו עושה שלום במרומיו מיכאל שר של מים גבריאל שר של אש ואין מכבין זה את זה, והיינו מפני שהמשל ופחד עמו והיינו הארת אוא\"ס שמאיר שם. לשמור מצותיו, כי אוא\"ס שבתורה צריכה שמירה ומהו השמירה זהו המצות כי המצות הם כלים לקבל אוא\"ס שבתורה.\n<b>וזהו</b> מ\"ש אל יתהלל חכם בחכמתו כ\"א בזאת יתהלל המתהלל השכל וידוע אותי כי אני הוי' עושה חסד ומשפט וצדקה בארץ, וצ\"ל מהו השייכות זל\"ז. הענין הוא כי חסד ומשפט הו\"ע חו\"ג וצדקה הוא כללות כל המצות שנק' בשם צדקה, והכי פי' השכל העיקר השכלה הוא וידוע אותי שיומשך אותי אוא\"ס, והכלים לזה הם המצות. ולעשות הישר בעיניו, זהו כמ\"ש עין בעין יראו שיש עין עילאה ועין תתאה, עין תתאה הוא שלמטה היש ולמעלה הו\"ע אין, ועין עילאה שלמעלה היש אמיתי ולמטה הוא אין, פי' ה' אלקיך שיומשך עין עילאה בעין תתאה, שיהי' הביטול למטה כמו למעלה, וע\"י מה יוכל לימשך הוא ע\"י ביטול היש, לכן תהלים שהוא סיפור שבחו של מקום שכל הנבראים אומרים שירה תנינים וכל תהומות, ושירה הו\"ע ביטול עי\"ז נמשך מעין עילאה בעין תתאה. וזהו\"ע שע' דיכרסמנה חזיר מיער מפסיק כחו של חזיר שע' קאי על שבע מדות שכלולים מע\"ס שזהו ז' מדות תחתונות דבינה שהם מקור לז' מלכין קדמאין שנפלו בשבה\"כ, ע\"ז קאמר שע\"י שנמשך עין עילאה בעין תתאה עי\"ז מבררין רפ\"ח ניצוצים, וזהו\"ע שמע דק\"ש שמע הוא שם ע' שם בגימט' רפ\"ח [עם ב\"ן] וע\"י ביטול דק\"ש מבררין רפ\"ח ניצוצים, והע' תלוי' מורה על מקיף דלבונה שיונקים החיצונים ממנה. וע\"י שנמשך עין בעין מפסיק יניקת החיצונים. והענין של חצי שבתהלים כי דוד אמר חצות לילה אקום להודות לך, כי לילה נחלקת לשנים האחד הוא גבורה והב' הוא חסד, וחצות זה רגע שמחבר השני חצאין, וזהו אוא\"ס שמאיר ברגע הזו שמחבר חו\"ג ומפסיק כח של יניקת חיצונים. וזהו קול מחצצים בין משאבים, מחצצים לשון רבים שיש שני מיני קולות קול של תפלה היא העלי' מלמטלמ\"ע, וקול תורה שיומשך מלמעלמ\"ט. וזהו וא\"ו דגחון מפסיק כחו של נחש וע' דיכרסמנה חזיר מיער מפסיק כחו של חזיר, כדי שיבוא לאהבה את הוי' בכל לבבך בשני יצריך שאפי' יצה\"ר יבוא לידי אהבה."],[2000460419,"<h3>והמשכילים יזהירו</h3>\n<b></b><b>בס\"ד, פ' תזריע ומצורע תרל\"ט, ליובאוויץ.</b>\n<b>והמשכילים</b> יזהירו<sup data-n=\"1220\">1</sup> כזהר הרקיע ומצדיקי הרבים ככוכבים לעולם ועד. וארז\"ל במתניתא תנא זה הדן דין אמת לאמיתו וגבאי צדקה, וצ\"ל מהו שייך לפ' והמשכילים כו'.\n<b>ולהבין</b> זה, צ\"ל מהו\"ע רקיע, כי הנה יש מתיבתא דרקיע כמו שארז\"ל קמיפלגי במתיבתא דרקיע אם בהרת קדמה לשער לבן טמא ושער לבן שקדמה לבהרת טהור, ואם ספק הקב\"ה אומר טהור ומתיבתא דרקיע אמרו טמא, ומאן נוכח נוכח רבה בר נחמני שאמר ע\"ע אני יחיד בנגעים ואני יחיד באהלות ואמר טהור טהור. וכן ארז\"ל שהראי' הוא מפסוק לטהרו או לטמאו פתח הכתוב בטהרה תחילה. וצ\"ל ענין הפלוגתא, וגם להבין ענין מה שמצינו שהתנאים ואמוראים עשו ע\"י תורתם נסים גדולים ועצומים היוצאים מדרכי הטבע לגמרי, כמו רפב\"י אמר גינאי נהרא חלוק לי מימיך ונתחלקו המים שזה הי' אצל משה רבינו ושר\"י<sup data-n=\"1221\">2</sup> פלא גדול, וכמארז\"ל זוטרא דבכו מחי' מתים, שזה לא נמצא אלא בנביאים ואיזה מהם כמו אלי' ואלישע ויחזקאל.\n<b>אך</b> להבין זה צ\"ל תחילה מה שכינו הגמרא אותו ית' בשם קוב\"ה. והענין הוא כי קוב\"ה פי' שני תיבות קדוש וברוך, קדוש פי' שהוא קדוש ומובדל מגדר עולמות ולא כמו שהנשמה ממלא את הגוף הקב\"ה ממלא את העולם, כי הנשמה בהתלבשותה בהגוף ה\"ה מתפעלת ממקרי הגוף ויש בה שינוים פעמים כך ופעמים כך, אבל הקב\"ה קדוש ומובדל מגדר עולמות ולכן כתי' אני הוי' לא שניתי, אתה הוא קודם שנברא העולם ואתה הוא לאחר שנברא העולם בשוה שהו\"ע סוכ\"ע שכללות העולמות אינו נוגע ואינו פועל בו שום שינוי, ואף שעיקר החיות הוא מסוכ\"ע אך הוא מחי' בדרך מקיף, ובאמת הוא בהעלם כמ\"ש את השמים ואת הארץ אני מלא רק שהוא בהעלם וזהו פי' קדוש. ובלשון הקבלה פי' קדוש הו\"ע דת\"י<sup data-n=\"1222\">3</sup> שהוא קו האמצעי שעולה עד הכתר, ויש בו ב' מדריגות מלמטלמ\"ע ומלמעלמ\"ט, דעת הו\"ע העלאה ממטלמ\"ע שהו\"ע העמקת הדעת והתבוננות איך שאני הוי' לא שניתי ועי\"ז בא לדביקות והתקשרות לא\"ס ב\"ה, וכמ\"ש דע את אלקי אביך שפי' דע הו\"ע התקשרות שזהו העלאה ממטלמ\"ע, ובחי' ת\"י<sup data-n=\"1223\">4</sup> הו\"ע השפעת והמשכת החיות מלמעלמ\"ט וזהו פי' קדוש.",[["1220","1","<b>והמשכילים יזהירו</b>: הנחה מרשימות א' השומעים מהמאמר הנדפס לעיל ע' קנח ואילך. [וראה בהנסמן שם, ולא נכפלו כאן עוה\"פ המ\"מ וציונים]. בכותרת המאמר נרשם: מאמר ששמעתי מכ\"ק אדמו\"ר שליט\"א בליובאוויץ, בהיותי פעם ראשונה שנת תרל\"ט פ' תזריע מצורע."],["1221","2","<b>ושר\"י</b>: וששים רבוא ישראל. [וכ\"ה לעיל ע' קנט]."],["1222","3","<b>דת\"י</b>: דעת תפארת יסוד."],["1223","4","<b>ת\"י</b>: תפארת יסוד."]]],[2000460420,"<b>ותיבת</b> ברוך יש בו ב' פי', א' מלשון המשכה כמ\"ש רחום וחנון שאין פי' רחום שהוא כלי המחזיק רחמים אלא שהוא משפיע רחמים, וכן חנון, וכמו\"כ פי' ברוך הוא ראש המשכות חיות ממכ\"ע שיומשך לעולמות, וזהו שר\"ת ברוך ראש ומקור כל ברכה שפי' הו\"ע המשכה. והפי' הב' בתי' ברוך הוא ע\"ד מ\"ש והמלך שלמה ברוך שפי' מתברך היינו שמקבל ברכה, ופי' שלמה מלך שהשלום שלו ופי' שלום הוא המחבר שני דברים הפכים. וזהו למטה ענין שלום שייכות למלכות ומהו ענינו למעלה. והענין הוא כי מל' ידוע שאין מלך בלא עם, ועם הוא מלשון עוממות נפרדים, שענין מלוכה אינו שייך כ\"א לנפרדים, והעיקר הוא להיות ביטול היש כי בלא ביטול כתי' אין אני והוא יכולין לדור, וזהו\"ע מלך שהשלום שלו. ופי' והמלך שלמה ברוך הו\"ע חכ' תתאה ומקבל מח\"ע. וזהו פי' קוב\"ה קדוש הו\"ע סוכ\"ע, וברוך הו\"ע ממכ\"ע, וידוע שמקיפים ופנימי' דבוקים ואחוזים זה בזה, ולכן כינו רז\"ל אותו ית' בש' קוב\"ה.\n<b>ועתה</b> צ\"ל ענין מתיבתא דרקיע, הנה כתי' ודמות שעל ראשי החי' רקיע כעין הקרח וידוע שיש חיוון תתאין שהו\"ע מרכבתא תתאה מחנה מיכאל ומחנה גבריאל, וחיוון עילאין הו\"ע האבות הן הן המרכבה, וצ\"ל מהו פי' החי', לכאורה הי' צ\"ל החיות. אך פי' החי' קאי על בחי' מל' שיורד ומתלבש להוות ולהחיות ג' עולמות בי\"ע וכמ\"ש ואתה מחי' את כולם, ועל ראשי החי' זה קאי על האבות שהן הן המרכבה, וזהו אברהם יצחק ויעקב, יצחק הו\"ע צמצומים העלאה ממטלמ\"ע, ואברהם הוא מדת חסד המשכה מלמעלמ\"ט, ויעקב הו\"ע ת\"ת קו האמצעי שכולל שניהם. וזהו פי' החי' שקאי על מל' שיורד ומתלבש להחיות ג' עולמות בי\"ע. ועל ראשי החי' רקיע כעין הקרח, פי' רקיע, הענין הוא כי הנה יש אור מים רקיע, ובנפש האדם הו\"ע משכיל מקור השכל, וגילוי השכל, וכשהשכל בא בהשגה והבנה, והנה כשהשכל בא בהשגה והבנה לא יכול לשנותו וה\"ה ענין רקיע דאגלידא מיא שעומדים על מקום אחד, אבל ברק המבריק שהוא בריקת וסקירת השכל הרי יכול לנטותו לכאן ולכאן ה\"ה כמו מים דניידי ואזלי, ומשכיל מקור השכל הו\"ע אור. וכן למעלה על ראשי החי' רקיע, הו\"ע בינה עילאה והתגלות א\"ס ב\"ה הוא בבינה. וזהו שארז\"ל להבין דבר מתוך דבר, תוך דבר הו\"ע ממכ\"ע ודבר הו\"ע סוכ\"ע, וצ\"ל מממכ\"ע<sup data-n=\"1224\">5</sup> שיש עוד בחי' סוכ\"ע שהיא גבוה ממנו.\n<b>נמצא</b> הפי' מתיבתא דרקיע הוא מדריגה גבוה שהו\"ע מארז\"ל אתי הקב\"ה לאשתעשע עם צדיקי', ומאן זוכה לזה דוקא התנאים ואמוראים שע\"י לימוד התורה לשמה וכמו רב יהודה הי' מצלי מתלתין יומין לתלתין יומין, וענין תפילה הו\"ע ההתבוננות איך ולגדולתו אין חקר פי' ולגדולתו העצמי' אין חקר שהו\"ע סוכ\"ע, איך שאני הוי' לא שניתי כמו קודם הבריאה כן לאחר הבריאה,",[["1224","5","<b>וצ\"ל מממכ\"ע</b>: וצריך להבין מממלא כל עלמין."]]],[2000460421,"שכללות העולמות הן רק מהארה בעלמא שאינו תופס מקום כלל ולא שייך לומר אפי' כטפה מים אוקיינוס שיש להטפה איזה ערך לגבי ים כמו שאמר ר' יוחנן יכולני לשער כמה טפות יש בים שיש ערך, אבל לגבי ית' אין ערוך לך כתי' שהוא בחי' סוכ\"ע ולמחתב\"כ, ולכן כשמתבונן בזה יש לו דאגות ומרירות מפני מה אינו משיג א\"ס עצומ\"ה וכמארז\"ל אין מוסרין רזי תורה אלא למי שלבו דואג בקרבו. וזהו ע\"י ההתבוננות שאו מרום עיניכם וראו מי ברא אלה, אלה הו\"ע ו\"ק שכלולים מוא\"ו ולכן אלה בגימט' ל\"ו והו\"ע ראשי החיות, ומי ברא אלה שאלה נתהוה בדרך בריאה יש מאין ממי, כמו והחכ' מאין תמצא שחכ' נתהוה מכתר בדרך מציאה יש מאין כמו\"כ אלה נתהוה ממי בדרך יש מאין. וזהו מ\"ש מבטן מי יצא הקרח, קרח הו\"ע רקיע ונתהוה בדרך בריאה יש מאין ממי, שהוא יותר גבוה, וכן אלה נתהוה בדרך בריאה יש מאין. וכשמתבונן בכל זה אזי בא לו דאגות ומרירות על העדר השגתו בבחי' א\"ס ב\"ה הסוכ\"ע ולמתב\"כ. וע\"י לימוד התורה נעשה פקודי הוי' ישרים משמחי לב, לב הדואג משמח ע\"י לימוד התורה שנתפס בו ואוריי' וקודב\"ה כולא חד, ותורה הו\"ע מקיף ומוקף שהו\"ע יחוד שאין כמוהו ועי\"ז משמח הלב. ופי' ענין פקודי הוי' ישרים הענין הוא כי בסדר ההשתל' העולמות מה שלמטה יותר נתמעט כמו מאות עשיריות יחידות, בברי' מאות וביצי' עשירות ובעשי' יחידות, אבל התורה הו\"ע פקודי הוי' ישרים שנמשך למטה כמו למעלה. ולפ\"ז פי' קדוש וברוך שקדוש בעצמו מתברך ויומשך למטה, וזהו מה שאנו מברכים אשר קדשנו במצותיו וציונו על ד\"ת, פי' קדשנו במצותיו שגם הקדוש בעצמו יומשך למטה, ועד\"ז כל המצות.\n<b>וכ\"ז</b> הוא ע\"י לימוד התורה בדיבור כמו שונה פרקו מאה פעמים ויש שונה פרקו מאה פעמים ואחד שע\"י לימוד התורה בדיבור ובנפיחתו ברוח פיו עי\"ז ממשיך בחי' אוא\"ס למטה כמו שאי' בס\"י עשר ספירות בלי מה כשלהבת הקשורה בגחלת שענין שלהבת הקשורה בגחלת הוא בהעלם וע\"י נפיחה מוציאין השלהבת מהעלם לגילוי, כן ע\"י לימוד התורה בדיבור וברוח פיו שמדבר הוא לרוח ממללא עי\"ז ממשיך א\"ס ב\"ה כי רוח הוא מד' גבוה מאד כמ\"ש יערה עלינו רוח ממרום וכמ\"ש בס\"י אחר שלהבת הקשורה כו' אחת הוא רוח אלקי' חיים, לכן ע\"י דיבור תורה ברוח פיו ממשיך בחי' הוי' כמ\"ש הוי' אלקיך אש אוכלה הוא וע\"כ ע\"י לימוד התורה ממשיכין זה, וזהו אפי' גם עכשיו כמ\"ש נותן התורה, נותן הוא לשון הוה, רק הוא לפי ערך האדם שאיזה אדם הוא, לכן התנאים ואמוראים שהי' מבחי' מוחין דגדלות הי' ממשיכין ע\"י לימוד תורתם אוא\"ס ב\"ה, ולכן הי' ביכולתם לעשות נסים היוצאים מדרכי הטבע כמו רפב\"י שאמר גינאי נהרא חלוק לי מימך וחלק לו מימיו, ונעשה מים יבשה, כי ים ויבשה הו\"ע עלדאת\"כ ועלדאת\"ג, והו\"ע העלם וגילוי, וזהו בהשתל' העולמות בכל עולם ועולם אבל במד' שלמעלה מסדר השתל' לא שייך בחי' העלם וגילוי כמ\"ש מקצה השמים ועד קצה השמים ואי' בזהר ע\"ז שמים דא עלמא עילאה שהו\"ע עלדאת\"כ וקצה הוא הגבלה אבל באוא\"ס אינו שייך ענין הגבלה ולכן הם המשיכו ע\"י תורתם בחי' א\"ס שלמעלה מסדר השתל' לכן נעשה להם ניסים"],[2000460422,"היוצאים מדרכי הטבע היינו להפך ים ליבשה, שזה דוקא הי' רבותא בקי\"ס הוא מפני שהי' קודם מ\"ת<sup data-n=\"1225\">6</sup> אבל ע\"י לימוד התורה יכול להיות נסים היוצאים מדרכי הטבע. ובזה יובן הפלוגתא, אם ספק הקב\"ה אומר טהור ומתיבתא דרקיע אמרי טמא, מתיבתא דרקיע אמרי טמא כי כל ספיקא דאורייתא לחומרא, אבל הקב\"ה אומר טהור כי קדוש הוא קדוש ומובדל בחי' מקיף ושם לא שייך רע לכן אמר טהור, ומאן נוכח רבה בר נחמני שהוא הגיע למד' מקיף והמשיך גם למטה ולכן אמר טהור טהור.\n<b>ומעתה</b> יובן פי' הפסוק והמשכילים יזהירו כזוהר הרקיע, פי' המשכילים הו\"ע אור שלמעלה מבחי' מים ורקיע, כי הנה כתי' משכיל לאיתן פי' איתן הוא מלשון חוזק כשאדם פועל בעצמו ביטול היש למעלה מהטו\"ד ה\"ה מגיע לבחי' משכיל שהו\"ע אור שלמעלה ממים ורקיע. וזהו מארז\"ל שקאי על גבאי צדקה כי על צדקה כתי' וצדקה כנחל איתן שמגיע לבחי' משכיל. ובזה יובן ג\"כ מה שאמרו במתניתא תנא זה הדן דין אמת לאמיתו, כי הנה ארז\"ל הדן דין אמת לאמיתו נעשה שותף להקב\"ה במעשה בראשית, פי' כי בריאת העולמות הי' בב', וכ\"ו דורות הי' הא' קורא תגר למה לא נברא מע\"ב בא' שהוא ראשון באותיות, והענין הוא כי מא' הי' יכול לימשך ארור, אבל ב' הו\"ע ברכה, פי' כי מעוצם רוממות הא' ששם הוא כחשיכה כאורה יכול להיות נמשך ג\"כ ארור לכן נברא בב' שממנו נמשך ברכה. אבל מ\"ת התחיל בא' אנכי הוי' אלקיך כו', והטעם הוא הואיל שקודם הי' ב' שהו\"ע ברכה יכול להיות אח\"כ בא'. והוא ע\"ד כמו שאי' ביצ\"מ בעבור זה לא אמרתי אלא בשעה שיש מצה ומרור, פי' כי ביצ\"מ הי' גילוי גבוה שלמעלה מסדר השתל' ולא אמרתי אלא בשעה שיש מצה פי' ביטול בחי' חכ' ולכן יכול אח\"כ להיות שנמשך לי ולא לו. כמו\"כ יובן כאן מאחר שנברא תחילה בב' שהו\"ע ברכה יכול להיות אח\"כ א'. ולפ\"ז י\"ל עוד פי' א' על קב\"ה שמצד מד' קדוש שהו\"ע כחשיכה כאורה יכול לימשך ג\"כ למקום שאינו ראוי, ולזה צריך להמשיך מקדוש בברוך למקום הראוי דוקא. וזהו שאמר תנא זה הדן דין אמת לאמיתו שהוא מגיע לבחי' משכילים, כי הדין צ\"ל אפי' כשבאים לפניו בע\"ד עם עדות ועדות מעידים לבע\"ד אחד צ\"ל בחכמתו<sup data-n=\"1226\">7</sup> איך שהדין מרומה ומאחר שצריך הדיין להבין בחכמתו מגיע לבחי' משכילים. וכן למעלה ג\"כ כתי' ויבואו בני אלקים וקטרגו לפניו ית' הללו והללו ח\"ו ישראל חטאו וטענתם חזקה, אך הקב\"ה שהוא דיין אמת מבין בחכמתו שהצדק עם ישראל, וזהו למעלה ענין משכילים שהו\"ע אור שלמעלה מענין מים ורקיע. ועפ\"י הפשוט פי' והמשכילים יזהירו כזהר הרקיע קאי על תורה ותפלה, כי ע\"י תפלה שהו\"ע התבוננות איך שאני הוי' לא שניתי כמו קודם שנבה\"ע כך לאחר שנבה\"ע בלי שום שינוי ח\"ו, שכללות העולמות הם מזיו והארה בעלמא שאינו מגיע לו ית',",[["1225","6","<b>שזה דוקא הי' רבותא בקי\"ס הוא מפני שהי' קודם מ\"ת</b>: ראה לעיל ע' קסג בשולי הגליון מגוכי\"ק."],["1226","7","<b>צ\"ל בחכמתו</b>: צריך להבין (או: צריך להכיר)."]]],[2000460423,"עי\"ז בא לו דאגות ומרירות על שאינו משיג בחי' א\"ס עצומ\"ה וע\"י התורה ממשיך בחי' א\"ס ועי\"ז מגיע לבחי' והמשכילים שהו\"ע אור שלמעלה מבחי' מים ורקיע."],[2000460424,"<h3>הללוי' הללו את ה' מן השמים</h3>\n<b>בס\"ד</b>\n<b>הללויה</b> הללו את הוי' מן השמים הללוהו במרומים הללוהו כל מלאכיו, ואי' ברש\"י בשבת שב' מזמורות של הילולים הללוי' הללו את ה' מן השמים והללו אל בקדשו הם עיקר פסוד\"ז. ובזהר אי' ששני מזמורים הללו הם שבחא דכולהו, שבהללו אל בקדשו נכלל כל ע\"ס, ובהללויה גו' מן השמים נכלל כלליות שמים וארץ. ובסידור האריז\"ל אי' בפרט שבהללויה גו' מן השמים נכלל ד' עולמות אבי\"ע וד' יסודות ארמ\"ע וד' בחי' דצח\"ם, הללויה גו' מן השמים קאי על אצי', הללוהו במרומים קאי על בריאה, הללוהו כל מלאכיו קאי על יצירה, הללוהו כל צבאיו קאי על עשי', וזהו המשכה מלמעלמ\"ט. ואח\"כ חשיב התכללות מלמטלמ\"ע שמש וירח זהו התכללות מעשי' ביצי', כל כוכבי אור זהו התכללות מיצי' בברי', שמי השמים זהו ההתכללות מבריאה באצי', והמים אשר מעל השמים זהו התכללות בעצמיות המאציל. והדר חשיב ד' יסודות, אש זה יסוד האש, שלג וקיטור זהו יסוד המים, כי קיטור העשן הוא מיסוד המים כי אנו רואים שעץ כל מה שיש בו לחלוחית יותר ביותר הוא מעלה עשן, והיינו מפני שעשן הוא מיסוד המים, רוח סערה עושה דברו זה יסוד הרוח, ההרים וכל גבעות זה יסוד העפר והוא דומם, עץ פרי וכל ארזים זהו צומח, והחי' וכל בהמה זה חי בלתי מדבר, מלכי ארץ וכל לאומים שרים וכל שופטי ארץ בחורים וגם בתולות זקנים עם נערים זהו מדבר. והדר גמר וירם קרן לעמו כו' לבנ\"י עם קרובו, פי' שבנ\"י הם קרובים להוי', והגם שכתי' כי מי גוי גדול אשר לו אלקים קרובים אליו ואי' במד\"ר אשר לו גוי קרוב אין כתיב כאן אלא אשר לו אלקים קרובים אליו שאלקים קרוב לבנ\"י כבי', אלא הענין הוא כי התם בש' אלקים שם אלקים קרוב לישראל אבל הכא שקאי על יהללו את ש' הוי' שלגבי ש' הוי' בנ\"י קרובים לש' הוי' וזהו\"ע של המזמור.\n<b>והנה</b> ענין דפסוד\"ז הוא לבוא לידי אריכות ההתבוננות, כדאי' כל המאריך באחד ופי' המאריך באחד הו\"ע אריכות ההתבוננות, ומהו האריכות ההתבוננות זהו"],[2000460425,"פסוד\"ז ובק\"ש, ואף שהראשונים תנאים ואמוראים לא האריכו בתפלה וכש\"כ בפסוד\"ז, רק מפני שהם היו נשמות גבוהים במעלה גדולה הי' די להם בהתבוננות מעט נקבע בלבם אחד האמת בקביעות שלא יהי' חולף ועובר, אבל אנו שנתרחקנו ונתגשמנו מרוחניות צריכין אנו לאריכות ההתבוננות. ומהו אריכות ההתבוננות זהו פסוד\"ז ובק\"ש כדי שנוכל לבוא לידי שמ\"ע ישראל גו' הוי' אחד, שמע ישראל הוא ע\"ד לבנ\"י עם קרובו.\n<b>וענין</b> הוי' אחד מכאן למד הרמב\"ם מצות ליחדו, משמע שהפסוק בא להורות על יחוד אלקות. ולכאורה הל\"ל יחיד שמורה יותר על א\"ס שהוא יחיד ומיוחד, אבל אחד הוא אחד המנוי כמו בשי\"ב כתי' ששת ימים עשה וכתי' ויהי ערב ויהי בוקר יום אחד, וכמו בי\"ב שבטים שאחד מהם נק' אחד כמו אחיכם אחד, שילחו מכם אחד, ויפתח אחד את שקו, ואצלו ית' כתי' הוא אחד ואין שני לו, והל\"ל יחיד שהוא מורה יותר על אחדותו ית', ובפרט שמצינו כמה פעמים שאנו אומרים יחיד כמו יחיד חי העולמים מלך, מלך יחיד חי העולמים, והכא שהרמב\"ם לומד מכאן מצות ליחדו להוציא השיתוף כש\"כ שצריך למימר יחיד שמורה יותר על אחדותו ית', ומאחר שאנו אומרים אחד משמע שמאחד מצינו לידע אחדותו ית' מה שמיחיד אין יכולים לידע. וצ\"ל מהו\"ע של יחיד. הנה יחיד מורה על א\"ס שגבוה מסובב וממלא, שאצלו כתי' אני הוי' לא שניתי אתה הוא עד שלא נברא העולם ואתה הוא משנברא העולם, כולם בחכ' עשית שחכ' נחשבת כעשי' גשמי' לגבי', אבל ענין אחד הוא אותיות א' ח' ד', ח' הוא מורה על ז' רקיעים (ולמעלה הו\"ע ז' מדות העליונות) וארץ, וד' מורה על ד' רוחות העולם שבזה נכללים כללות שמים וארץ, את השמים כל צבא השמים את הארץ כל צבא הארץ, וא' מורה על א\"ס אלופו ש\"ע, שענין זה מיחיד אין יכולים לידע, שיחיד קאי על א\"ס שקדוש ומובדל מן העולם, וזה שנתהוה עולמות יכולים לדמות שהם דבר נפרד, ואף שנתהוה בריאה יש מאין מ\"מ כיון שנתהוה יש יכולים לדמות שהוא דבר נפרד, אבל אחד מורה אף שהם ח' ד' מ\"מ הם טפל ובטל לא'. וזהו שאי' ברמב\"ם הוא שהנביא אומר והוי' אלקי' אמת הוא אמת ואין לאחר אמת כאמיתתו, שכל העולמות שנבראו ממנו הם טפל ובטל לא\"ס אלופו ש\"ע. וזהו מעלת אחד, לכן אנו אומרים אחד ולא יחיד. וכן מצינו לע\"ל כתי' והי' ביום ההוא יהי' הוי' אחד ושמו אחד ופריך בגמ' אטו האידנא לאו אחד הוא ומתרץ שם כמה תירוצים לא כמו שאני נכתב אני נקרא שעיקר גילוי דאחד יהי' לע\"ל דוקא, משמע שבחי' אחד הוא מד' גבוה<sup data-n=\"1227\">1</sup>.\n<b>והנה</b> למעלה מהו\"ע דאחד הו\"ע ז' מדות העליונות והז' מדות בטלים לא' והא\"ס נמשך בז' מדות שלעוצם רוממותו של א' אינו יכול לימשך למטה אלא ע\"י ז\"מ. וזהו שאנו אומרים השקיפה ממעון קדשך מן השמים<sup data-n=\"1228\">2</sup> וברך את עמך ישראל<sup data-n=\"1229\">3</sup>,",[["1227","1","<b>מד' גבוה</b>: מדריגה גבוה."],["1228","2","<b>הללוי' הללו את הוי' מן השמים</b>: הנחה מד\"ה זה הנדפס לעיל ע' קסה. מאמר זה הוא מכת\"י מעתיק מס' 1185. הנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע נד' לעיל ע' רסז.\nהמ\"מ למאמר זה ראה לעיל שם ע' קסה ואילך וע' רסז ואילך.\nבמפתח שבתחילת הכת\"י (1185) נרשם התאריך על מאמר זה ”במדבר תרל\"ט\". אך ניכר שזהו טעות המעתיק או שנאמר עוה\"פ בפ' במדבר. וראה עוד ע\"ד התאריך לעיל ע' רסז במ\"מ."],["1229","3","<b>ובק\"ש</b>: וברכות קריאת שמע (ועד\"ז מובא לקמן)."]]],[2000460426,"הבט משמים וראה, ומהו דוקא ע\"י שמים. אך הענין הוא שמים הו\"ע מדת אש ומים, אש הו\"ע גבורה העלאה מלמטלמ\"ע, מים הו\"ע חסד המשכה מלמעלמ\"ט, כמים שיורדין ממקום גבוה אל מקום נמוך, ויש מדה שמחבר חו\"ג והוא ענין ת\"ת, ושמים ג\"כ נטל הקב\"ה אש ומים וערבן זה בזה שהו\"ע מדות, ולפיכך בתי' שמים יש אותיות מים כולו ומאש יש רק אות השי\"ן והוא מפני שבמדות רובו חסדים כמ\"ש זכר חסדו, ומפני זה אנו מבקשים הבט משמים כדי שיוכל להיות ואוהב את יעקב ואת עשו שנאתי, כי אהבה פנימי' החסד, ושנאה הו\"ע גבורה, וע\"י שנמשך ע\"י מדות ובמדות הוא רובו חסדים לכך יוכל להיות ואוהב את יעקב. וזהו דוקא ע\"י מדות, שאם לא יומשך ע\"י מדות אזי שכינתא בגלותא סליק לעילא ולעילא פי' לעילא הוא בחי' יחיד שגבוה מסובב וממלא ושם כחשיכה כאורה, אם צדקת מה תתן לו אם רבו פשעיך מה תעשה לו, שיוכל לימשך למקום שאינו ראוי, לכן אנו מבקשים הבט משמים שיומשך ע\"י מדות ויוכל להיות ואוהב את יעקב. וזהו\"ע שאנו אומרים אחד שע\"י שהז' מדות הם טפל ובטל לא' עי\"ז נמשך הא' דוקא בח' ד' שהו\"ע מדות, כי לעוצם רוממות של א' יוכל לימשך למקום שאינו ראוי.\n<b>וזהו\"ע</b> מ\"ש לך הוי' הגדולה והגבורה גו' כי כל בשמים ובארץ, הנה לך וכל הם אותיות שוים רק לך הוא העלאה וכל הוא המשכה, ולך וכל הם בגימט' נו\"ן, וזהו\"ע שארז\"ל חמשים שערי בינה נבראו בעולם שמדות נמשכים מבינה, הגם שעיקר משכן של מדות הם בלב מ\"מ נמשכים מבינה כי אנו רואים שמה שאדם מבין שטוב הדבר לפניו הוא אוהב וכן כל המדות, ומהו ענין שער, שער הוא הטי' בשכל האיך להיות המדה, ומהו\"ע חמשים שז\"מ כל אחד כלול מז' הרי מ\"ט, ושער החמשים הוא עצם הבינה, וכשצריך לימשך מבינה למדות הוא דוקא ע\"י שער, כך כשנכלל ממדות בלאו מכל אינון מדות איהו כלל נכלל ג\"כ ע\"י שער. וזהו לך הוי' הגדולה ואף שגדולה הוא מדה גבוה שזהו\"ע מע\"ב מ\"מ נכללים בלך שזהו מדות בלאו מכאמ\"כ<sup data-n=\"1230\">4</sup>.\n<b>וזהו\"ע</b> כגוונא דאינון מתייחדין לעילא, אינון קאי על מדות, מתייחדין לעילא פי' לעילא הוא בינה שנכללים המדות בבינה, ולא בבינה לחוד אלא בהתגלות עתיק שבבינה שזהו מדות נכללין בלאו מכאמ\"כ. וזהו\"ע מה שאמרו השבטים כשם שאין בלבך אלא אחד כך אין בלבנו אלא אחד, שהאבות הם ענין שמים שהוא מדות, שיצחק ויעקב בגימט' שמים, יצחק הו\"ע גבורה העלאה ממטלמ\"ע, אברהם הו\"ע חסד המשכה מלמעלמ\"ט, ויעקב הוא כלול משניהם שזהו\"ע מדות, וזהו שאמרו כשם שאין בלבך אלא אחד שמדות נכללין באחד שהו\"ע לאו מכל אמ\"כ, ועי\"ז שהמדות נכללין בלאו מכא\"מ הנה עי\"ז אח\"כ נמשך מלאו מכאמ\"כ במדות. וזהו\"ע מ\"ש כי כל בשמים ובארץ מהו פי' כל הוא ע\"ד שכתי' אמרו אליו כל תשא עון ופי' המגיד ז\"ל<sup data-n=\"1231\">5</sup>",[["1230","4","<b>מכאמ\"כ</b>: מכל אלין (או: אינון) מדות כלל. (ועד\"ז מובא לקמן בכ\"מ)."],["1231","5","<b>ופי' המגיד ז\"ל</b>: ראה בהנסמן לעיל ע' קסט."]]],[2000460427,"כל הוא מקיף כללי, הגם שסוכ\"ע הוא ג\"כ מקיף מ\"מ ה\"ז מקיף פרטי, אבל כל הוא מקיף כללי ששם הוא תשא עון, וע\"י שמדות נכללין בלאו מכא\"מ עי\"ז כי כל בשמים ובארץ נמשך מכל שהוא לאו מכל אמ\"כ לשמים וארץ, שהו\"ע מדות.\n<b>וזהו</b> מ\"ש מי עלה שמים וירד פי' הזהר ששמים עולה במי, וענין מי הוא ע\"ד מ\"ש מי יתן והי' לבבם זה ליראה אותי כל הימים ואי' בגמ' ע\"ז הכל בידי שמים חוץ מיראת שמים ופריך בגמ' הלא דוד שאל ליראה את שמך וגם אנו בתפלתינו אומרים ג\"כ לאהבה וליראה את שמך. והענין הוא כי פי' הכל בידי שמים שכל השפעות שבעולם הם ע\"י שמים מדות, חוץ מיראת שמים שאינו ע\"י שמים מדות כ\"א ממדרי' גבוה יותר ששם קיימא לשאלה ע\"ד מי יתן מציון, מי יתן טמא מטהור, מי ברא אלה, אלה קאי על ו\"ק, ופ\"ו בגיט' אלה, וזה נמשך ממי, ומשם נמשך ג\"כ יר\"ש ולא ע\"י מדות, שאילו הי' נמשך ע\"י מדות לא הי' שייך בחירה שהידיעה הי' מכריח את הבחירה, אבל כשנמשך ממי, שייך בחירה כי שם הוא ד\"ע שהידיעה אינו מכריח את הבחירה. וזהו הפי' מי עלה שמים ששמים שהו\"ע מדות עולה במי, ואח\"כ וירד שנמשך ממי למדות, שהוא לא מכא\"מ למדות. ועתה יובן מ\"ש היושבי בשמים ולכאורה היו\"ד של היושבי הוא מיותר הול\"ל היושב. והענין הוא כי הנה יו\"ד הו\"ע המשכה שנמשך מלמכא\"מ בשמים שהוא מדות. וזהו ג\"כ הענין שהשבטים אמרו כשם שאין בלבך אלא אחד כך אין בלבינו אלא אחד, פי' כשם שאין בלבך אלא אחד שמדות נכללים באחד בלאמכא\"מ כך אין בלבינו אלא אחד שנמשך אח\"כ מלכא\"מ למדות, ע\"ד השבטים שהי' י\"ב בקר דבריאה מרכבתא דבריאה. וזהו ג\"כ הפי' כגוונא דאינון מתייחדין לעילא באחד אוף הכי איהי אתייחדת לתתא ברזא דאחד, כגוונא דאינון מתייחדין לעילא פי' שאינון שהוא מדות נכללין בלעילא בלמכא\"מ אוף הכי איהי אתייחדת לתתא שאח\"כ נמשך מלאו מכא\"מ למדות.\n<b>וזהו</b> ג\"כ הפי' של המזמור הללויה גו' מן השמים שע\"י שמדות נכללים בלאו מכא\"מ עי\"ז אח\"כ נמשך מלאו מכא\"מ לכל העולמות, הללו את ה' מן השמים זהו אצי', הללוהו במרומים הנה במרומים קאי על בריאה, כי מה שאנו רואים שמים אינו עצם השמים כי עצם השמים אינם יכולים לראות כי מהארץ לרקיע מהלך ת\"ק שנה וכמ\"ש כי גבהו שמים מהארץ, אלא מה שאנו רואים אינו רק זהרוריות השמים שנק' בש' מרום, וכן בריאה לגבי אצי'. הללוהו כל מלאכיו קאי על מלאכים דיצי', שיש שני מיני מלאכים יש אלף אלפים ישמשוני' וריבו רבבן קדמוהי יקומון, אלף אלפים ישמשוני' קאי על מלאכים דבריאה שע\"י אינו יכול להיות השפעה למטה"],[2000460428,"וריבו רבבן קדמוהי יקומון קאי על מלאכים דיצי'<sup data-n=\"1232\">6</sup> שע\"י נמשך עיקר השפעה אל הארץ. וזהו מ\"ש יוצר אור ובורא חושך, פי' בורא קאי על מלאכים דבריאה, חושך אינו יכול להיות גילוי על הארץ ע\"י, אבל יוצר מלאכים דיצי' אור יכול להיות ע\"י גילוי למטה. הללוהו כל צבאיו קאי על מלאכים דעשי' כי צבאיו הוא מל' עושין רצונו, פי' עושין רצונו שהעיקר רצון של הקב\"ה נעשה ע\"י מלאכים דעשי', וזהו המשכה מלמעלמ\"ט. ואח\"כ קחשיב ההתכללות שממטלמ\"ע שמש וירח זהו ההתכללות עשי' ביצי' ששמש וירח זהו ז\"א ומל', וז\"א מקננא ביצי' ומל' מקננא בעשי'. וכוכבי אור זהו התכללות יצי' בברי' שכוכבים הם ברקיע תמינאה שהיא בינה ואימא עילאה מקננא בכורסייא שהיא בריאה. שמי השמים זהו ההתכללות בריאה באצי'. והמים אשר מעל השמים זהו ההתכללות אצי' בא\"ס עצמיות המאציל.\n<b>והדר</b> קאמר יהללו את ש' הוי' כי הוא צוה ונבראו משמע שבריאת העולמות הי' ע\"י ש' הוי'. ולכאורה קשה הלא כתי' בראשית ברא אלקים משמע שהבריאה הי' ע\"י ש' אלקים. והענין הוא כי שם כתי' ברא שמתלבש כח הפועל בנפעל הי' ע\"י ש' אלקים, אבל עיקר הבריאה הי' ע\"י ש' הוי', שם כתי' ונבראו בדרך מאליו וממילא ע\"ד מי שאמר והי' העולם, מי שאמר לשמן וידליק הוא יאמר לחומץ וידליק ששם הוא שינוי הטבע.\n<b>ואח\"כ</b> קאמר הודו על ארץ ושמים, קחשיב ארץ והדר שמים ולכאורה צ\"ל הלא בכל המזמור חשיב שמים קודם לארץ ולמה קדם כאן ארץ לשמים, והיינו כי פי' הודו הוא ע\"ד שאי' בגמ' שאמרו המלאכים להקב\"ה תנה הודך על השמים והשיב להם כלום יצה\"ר יש ביניכם אלא נתן התורה על הארץ דוקא, ושמים מקבל מהארץ, ע\"ד מ\"ש היושבת בגנים חברים מקשיבים לקולך, היושבת בגנים קאי על נשמות שיושבים בג\"ע ולומדים תורה, חברים קאי על מלאכים מקשיבים לקולך לקול התורה, שהמלאכים מקבלים מן הארץ לכן חשיב ארץ קודם לשמים.\n<b>ואח\"כ</b> קאמר וירם קרן גו' לבנ\"י עם קרובו, וצ\"ל מהו פי' של לבנ\"י עם קרובו. והענין הוא דהנה פעם כתי' יראו את הוי' קדושיו ופעם כתי' ייראו מהוי' כל הארץ, אך לא קשה מידי, שם כתי' מהוי' היינו רחוק מש' הוי' כתי' כל הארץ, אבל יראו את הוי' טפל ובטל לש' הוי' זהו דוקא קדושיו, ומי הם קדושיו המקיימים תומ\"צ. וזהו פי' הפסוק לבנ\"י עם קרובו שקרוב ובטל לש' הוי'. וע\"י מה הם באים לזה המד' זהו ע\"י וירם קרן, ומהו\"ע הקרן, הנה קרן הוא ע\"ד מה שאי' בזהר על המשנה ובא לו לקרן דרומית פי' הזהר ובא לקרן בקדמיתא, כשצריכין לבוא למד'<sup data-n=\"1233\">7</sup> דרומית שהיא אהבה כמ\"ש באברהם הלוך ונסוע הנגבה ואברהם הי' מרכבה למדת האהבה וכשצריכין לבוא לידי אהבה צריכין לבוא תחילה לבחי' קרן.",[["1232","6","<b>אלף אלפי' ישמשוני'. . מלאכים דבריאה. . וריבו רבבן קדמוהי יקומון. . מלאכים דיצי'</b>: לעיל בהמאמר (ע' קע) הוא בהיפוך: אלף אלפים ישמשוני' הוא בחי' המלאכים דיצי' שהם שלוחים, אבל כתר ריבוי רבבן קדמוהי יקומון הם אינם שלוחים כי הם בעולם הבריאה שהם למעלה מבחי' השפעה."],["1233","7","<b>המד'. . למד'</b>: המדריגה. . למדריגה (ועד\"ז לקמן בכ\"מ)."]]],[2000460429,"<b>ומהו</b> פי' של קרן, קרן יש בו ג' פי', א' יש לפרש ע\"ד קרן זוית, ומהו\"ע קרן זוית, הוא שמחבר שני דפנות מזרחית דרומית, ומהו הקרן בעצמו, הקרן אינו מהות בעצם כי מה שנמשך למזרח הוא מזרח ומה שנמשך לדרום הוא דרום, אלא פי' קרן הו\"ע ביטול. ועוד י\"ל קרן הוא ע\"ד שאי' רמה קרני דוד שנמשח בקרן, ובדניאל אי' קרן חזית, שהו\"ע מל', ומהו\"ע של מל', מל' ג\"כ אינו מהות בפ\"ע רק התחברות המלך והעם, כי המלך הוא בפ\"ע והעם בפ\"ע והמלכות מחבר המלך והעם, והיינו ע\"י היראה והביטול מהמלך, ולמעלה מל' הוא ממכ\"ע, ולמטה מל' הוא קבעומ\"ש, נמצא שקרן הו\"ע ביטול, ומהו\"ע ביטול הוא דוקא יראה, כי אהבה הוא יש מי שאוהב, אבל יראה אינו שייך לומר יש מי שירא כיון שהוא ירא האיך שייך לומר יש מי שירא, זהו פי' קרן. וירם קרן הוא רוממות הקרן דהנה כתי' יראו את הוי' קדושיו כי אין מחסור ליריאיו, שיש מדריגה שנק' אין שלמעלה מחכ' כמ\"ש והחכ' מאין תמצא שחכ' נמשך מאין, נמצא שאין הוא מדריגה גבוה מחכ', וע\"י מה באים לזה צריך להיות קודם יראה שהו\"ע ביטול שע\"י את הוי' נעשה קרוב ובטל לש' הוי', וזהו קבעומ\"ש, ואח\"כ קדושיו מקיימים תומ\"צ ואח\"כ כי אין מחסור מדרי' אין שלמעלה מחכ' וזהו פי' של רוממות הקרן. ועתה נוכל להבין פי' הג' של קרן הוא ע\"ד כי קרן עור פני משה, והיינו ג\"כ כי משה הי' בחי' מ\"ה ונחנו מ\"ה דהיינו בחי' חכ', וזהו פי' כי קרן עור פני משה שבא למדריגת אין שלמעלה מחכ' וזהו רוממות הקרן.\n<b>ועתה</b> יובן מ\"ש ויעמידם לעד לעולם, דהנה כל השירים שבמזמור הזה הם ממלאכים שזה אינו רק חידוש הישינות וכמ\"ש ובטובו מחדש בכי\"ת מע\"ב, שזה אינו רק חידוש הישינות, שקודם בריאת העולמות הי' כי חפץ חסד הוא אבל אחר שנברא העולם צ\"ל אתעדל\"ת העלאת מ\"ן, וזהו השיר של המלאכים כמו שאי' במשנה כל בעלי השיר יוצאין בשיר, הגם שכתי' ובטובו מחדש בכ\"י תמיד מע\"ב מ\"מ הרי כ\"ז אינו רק חידוש הישינות, ועפ\"י קבלה נק' זיווג חיצוני' דחו\"ב וזווגייהו תדיר לצורך קיום העולמות, כי חו\"ב נק' אין ויש, בינה נק' יש כמ\"ש להנחיל אוהבי יש, חכ' נק' אין כמ\"ש והחכ' מאין תמצא, וזווגייהו תדיר שאל\"כ הי' חוזר העולם לתוהו ובוהו, וזהו חידוש הישינות, ואף שאנו רואים שבשנה זו שפע רב ובשנה זו מעט שפע וכמו שבע שני רעב שבע שני שבע, מ\"מ הרי כ\"ז חידוש הישינות, אבל כדי שיומשך אור חדש זהו דוקא בבנ\"י ע\"י וירם קרן תחילה יראה שזהו\"ע קבעומ\"ש ואח\"כ קדושיו שמקיימים תומ\"צ שעי\"ז נעשים את הוי' טפל ובטל לש' הוי' עי\"ז ממשיכים אור חדש מבחי' אין שלמעלה מסדר השתל'."],[2000460430,"<h3>הוספה א </h3><h3>אמר ריב\"ל כשעלה משה למרום</h3>\n<b></b><b>[לד\"ה ואל משה אמר עלה]</b>\n<b>בס\"ד. </b>\n<b>אמר</b> ריב\"ל כשעלה משה<sup data-n=\"1234\">1</sup> למרום אמרו המלאכים מה אנוש כי תזכרנו אשר תנה הודך על השמים, אמר להם משה כלום יצה\"ר יש ביניכם שאתם מבקשים את התו' והודו לו, וזהו מ\"ש אח\"כ מה אדיר שמך בכל הארץ כו'. והנה לכאורה אינו מובן זה שהרי כשביקשו את התורה מסתמא לא בקשו כמו שהיא נמשכה למטה רק שבקשו את התורה כמו שהיא למעלה, וא\"כ מה זו תשובה ע\"ז כלום יצה\"ר יש ביניכם שהרי תורה זו שייך גם בלי יצה\"ר, וכמו שמצינו דקא מיפלגי במתיבתא דרקיע<sup data-n=\"1235\">2</sup> אם בהרת קדמה לשיער לבן כו', הרי שלומדים את התורה גם נשמות בלי גופים ולומדים אותה באופן אחר ברוחניות וא\"כ המלאכים בקשו את התורה באופן זה, וא\"כ מה זו תשובה ע\"ז כלום יצה\"ר יש כו'.\n<b>אך</b> הנה מתחלה י\"ל קצת מ\"ש וראיתי אני שיש יתרון לחכמה מן הסכלות כיתרון האור מתוך החושך כו', ובזהר הקשה ע\"ז מה ששלמה משבח א\"ע ואמר ראיתי אני, ששלמה לפי שהי' ויחכם מכל האדם הוא ראה שיש יתרון לחכמה מן הסכלות, וכי שאר בני נשא דלא ידעי חכמתא דשלמה לא ידעין זה שיש יתרון לחכ' כו', ומה משבח א\"ע בזה שא' וראיתי אני דייקא כו'.",[["1234","1","<b>אריב\"ל כשעלה משה</b>: מאמר זה מכ\"ק אדמו\"ר מהר\"ש הוא (כנראה) מהדו\"ק מד\"ה ואל משה אמר עלה אל ה' תרל\"ט, נדפס כאן מכת\"י 1028 פו, א ואילך [כת\"י זה מלוקט ממאמרי כ\"ק אדמו\"ר מהר\"ש מהשנים תרכ\"ו-תרל\"ט, חלקם בגוכי\"ק וחלקם בכת\"י מעתיק בתוס' הגהות בגוכי\"ק]. המאמר דתרל\"ט לא נמצא בבוך גוכי\"ק של ס' תרל\"ט, ונמצא רק הנחת כ\"ק אדמו\"ר מוהרש\"ב מהתחלת המאמר ונדפס לעיל ע' רו, וכאן נמצא המאמר בשלימותו.\nהמאמר מיוסד והגהות על ד\"ה זה בס' מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' קיח ואילך [וראה גם שם ע' קכה ואילך. רנג ואילך]. והוא מיוסד על ביאור מאמר הזהר ד\"ה ר\"ח פתח כו' וראיתי אני בס' מאמרי אדה\"ז תקס\"ז ע' צח ואילך. ונו\"א שם ע' קב ואילך. ונו\"א בס' מאמרי אדה\"ז הנחות הר\"פ ע' לה ואילך. [מתחיל: ואיש כי ימרט]. ונמצא בתוס' הגהות וכו' בביאוה\"ז להצ\"צ ח\"ב ע' תתנה ואילך. תתעב ואילך. [וראה שם ס\"ע תתעג ואילך: וע\"ד הדרוש — נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610248\" data-slug=\"or-hatorah-hb\" data-id=\"8316610248\">אוה\"ת ויקרא ע' רנח</a> ואילך. רעד ואילך. רעט ואילך]. תתצא ואילך. וראה גם שם ע' תתעז ואילך. תתפא ואילך. תתפו ואילך. מאמרי אדהצ\"צ תרי\"ד ע' י-יא.\nונמצא בתוס' הגהות וכו' בד\"ה וראיתי אני בסה\"מ תרס\"ב ע' שנ ואילך. ד\"ה לדוד ה' אורי בסה\"מ תרפ\"ה ע' שלג ואילך. ד\"ה עוטה אור בסה\"מ תרצ\"ט ע' 209 ואילך. ד\"ה לדוד ה' אורי וד\"ה אשרי העם יודעי תרועה בסה\"מ תש\"ח ע' 279 ואילך בתוס' הערות וציונים מכ\"ק אדמו\"ר זי\"ע [חלקם נדפסו לקמן באותיות בולטות]."],["1235","2","<b>וכמו שמצינו דקא מיפלגי במתיבתא דרקיע</b>: ראה לעיל ד\"ה והמשכילים יזהירו."]]],[2000460431,"<b>אך</b> הענין הוא דהנה כתיב וישב שלמה על כסא ה', ופי' במד\"ר פ' בא פט\"ו היינו שכמו שכסא ה' שורה מסוף העולם עד סופו כך שלמה הי' שליט מסוף העולם עד סופו כו'. ועוי\"ל ששלמה עשה הכסא שלו בדוגמא לכסא הוי', דהנה כתיב בכסא שלמה שש מעלות לכסא, וזהו כגוונא דלעילא, וכמו שיש ששה רקיעים ורקיע השביעי שבו השכינה שורה וכמ\"ש סלו לרוכב בערבות בי\"ה שמו שבערבות דייקא שהוא רקיע השביעי שם השכינה שורה<sup data-n=\"1236\">3</sup>, וכך שלמה עשה את הכסא בדוגמא של מעלה, וכמ\"ש בזהר שית יומין לעילא שביעאה עלייהו שית יומין לתתא שביעאה עלייהו, שיתא דרגין לכורסי' כו' דכתיב וישב שלמה על כסא הוי', והיינו שעשה שלמה את הכסא שלו בדוגמא לכסא הוי' כו'. והנה מ\"ש בזהר שית יומין לעילא ושית יומין לתתא, זהו ג\"כ ענין שית תיבין דיחו\"ע שמע ישראל כו' ושית תיבין דיחו\"ת ברוך שם<sup data-n=\"1237\">4</sup> כו', וזהו מ\"ש ששה משמותם<sup data-n=\"1238\">5</sup> על האבן האחת וששה משמותם על האבן השנית כו'. והנה בשית יומין לעילא ובשית יומין דלתתא בשניהם שביעאה עלייהו, שיש ב' בחי' שבת וכמ\"ש את שבתותי תשמרו שיש ב' בחי' שבת<sup data-n=\"1239\">6</sup>, וזהו ג\"כ מה שאמרו בירושלמי אלמלא שמרו ישראל שתי שבתות כהלכתן מיד היו נגאלין, והיינו שיש בשבת גופא ב' בחי' שבת, שבת עילאה ושבת תתאה כו', וזהו מ\"ש ביום השביעי נתעלה וישב על כסא כבודו, שלכאורה מה שייך זה לכסא כבודו, אך לפי הנ\"ל יובן היטב והיינו לפי ששבת הוא בחי' כסא עצמו שלמעלה משית דרגין שהוא בחי' שביעאה עלייהו כנ\"ל.\n<b>והנה</b> י\"ל מהו ענין שית יומין לעילא ושית יומין לתתא כו'. וי\"ל מתחלה ענין שית יומין לתתא כו', והענין הוא דהנה כתי' כי אמרתי עולם חסד יבנה<sup data-n=\"1240\">7</sup>, והיינו כשצריך שיתהווה העולם שהוא בחי' גבול, כמו מהארץ לרקיע מהלך ת\"ק שנה וכן אפי' עולמות עליונים הם ג\"כ בחי' גבול ואפי' געה\"ע שבכלל הוא מג\"ח הוא בבחי' גבול כי השגה הוא בחי' גבול כו', וכדי שיתהווה העולם שהוא בחי' בע\"ג מבחי' חסד עליון שהוא בלי גבול כו', וכמ\"ש חסדי ה' כי לא תמנו כו', הוצרך החסד שיבנה בבחי' בנין דהיינו שיתלבש החסד בבחי' אותיות הדיבור כו', וכמ\"ש בס\"י שתי אבנים בונות שתי בתים כו'. וזהו מ\"ש גדול הוי' ומהולל מאד בעיר אלקינו<sup data-n=\"1241\">8</sup>",[["1236","3","<b>שבערבות. . שהוא רקיע השביעי שם השכינה שורה</b>: להעיר מביאורי הצ\"צ על התניא (ס' קיצורים והערות) ע' פד, צא. — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם."],["1237","4","<b>שית תיבין דיחו\"ע שמע ישראל. . דיחו\"ת ברוך שם</b>: זח\"א יב, א. ועוד. וראה שער היחוד והאמונה (פ\"ז). ובכ\"ד. — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם."],["1238","5","<b>וזהו מ\"ש ששה משמותם</b>: ראה ד\"ה ולקחת את שתי ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550058\" data-slug=\"torat-chaim\" data-id=\"2300550058\">תורת חיים שמות</a> [בהוצאת תשס\"ג ח\"ב שמה, ג ואילך). — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם. — וראה סה\"מ תרל\"ג ח\"א ע' קנז ואילך [ובהנסמן בהמ\"מ שם]."],["1239","6","<b>וכמ\"ש את שבתותי תשמרו. . ב' בחי' שבת</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a> ואילך."],["1240","7","<b>דהנה כתי' כי אמרתי עולם חסד יבנה</b>: ראה סה\"מ תרל\"ג ח\"ב ע' תקמ-מא. וש\"נ. תרל\"ד ע' נד."],["1241","8","<b>וזהו מ\"ש גדול הוי'. . בעיר אלקינו</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a> ואילך. סה\"מ תרכ\"ז ע' שסה. וש\"נ. תטז. וש\"נ."]]],[2000460432,"וארז\"ל אימתי הוא גדול<sup data-n=\"1242\">9</sup> כשהוא בעיר אלקינו דהנה פי' גדול הוא בחי' התפשטות גדולתו עד אין קץ בבחי' ריבוי עולמות מה שנתהווה עולמות עד אין קץ, ובכל עולם פרטים רבים וכל א' יש לו שורש למעלה וכמשארז\"ל אין לך עשב מלמטה שאין לו מזל מלמעלה כו', וכן כתיב אלף אלפים ישמשוני' וריבוי רבבן קדמוהי יקומון כו', שהוא בבחי' ריבוי מאד וזהו בחי' גדול ע\"ש התפשטות גדולתו בעולמות כו'. והנה ע\"ז ארז\"ל אימתי נק' גדול דהיינו שיתהווה בחי' גדולה זו שיהי' בחי' ריבוי עולמות זהו דייקא כשהוא בעיר אלקינו דהיינו כשנתלבש בבחי' דיבור עליון דייקא אז יכול להיות מקור לעולמות, דהנה אותיות הוא מלשון אתא שהוא בחי' תרגום<sup data-n=\"1243\">10</sup>, תרגום הוא אחוריים של לה\"ק<sup data-n=\"1244\">11</sup> שהוא בחי' חיצוני' כו', דהיינו הארה בעלמא בלבד מאיר בבחי' אותיות ממדות שבלב, וכמו שאנו רואים שלא כל עצמיות המדות מתלבש באותיות הדיבור רק הארה מהמדות בלבד כו', וע\"כ אנו רואים שאם הוא בהתפעלות המדה אינו יכול לדבר כלל כמו כשהוא בכעס גדול אינו יכול לדבר, רק אח\"כ כשנשקט הכעס ואינו מאיר רק הארה אז יכול לדבר כו'. וזהו אימתי הוא גדול כשהוא בעיר אלקינו כו' דהיינו בבחי' צירופי אותיות הדיבור שאז נתצמצם החסד כו', אז יכול להיות התפשטות גדולתו בבחי' ריבוי העולמות. וזהו שארז\"ל במקום שאתה מוצא גדולתו<sup data-n=\"1245\">12</sup> שם אתה מוצא ענוותנותו, דהיינו שגדולה זו היא בבחי' ענוה וירידה והשפלה כו'. וזהו שכל העולמות נתהוו ע\"י עש\"מ וכשארז\"ל בעש\"מ נברא העולם דהיינו רק מבחי' מאמר בלבד ואפי' אדם שהוא בחי' גבוה מאד כי אדם יש לו חכ' אעפי\"כ נתהווה רק מבחי' מאמר נעשה אדם כו' שהוא בחי' אותיות לבד כו'. וזהו ענין שית יומין לתתא, דהיינו כשהשית יומין עילאין שהוא בחי' מדות מתלבשין בבחי' דיבור העליון אזי נק' שית יומין לתתא כו', לפי שנתלבש בבחי' דיבור בחי' אותיות כו'.\n<b>והנה</b> שית יומין לעילא היינו המדות עצמן כמו שהם למעלה מהתלבשות בבחי' דיבור כו', רק כמו שהם מאירים בבחי' אותיות המח', שהם מאירין שם בבחי' גילוי יותר, כי המח' מתאחדת עם עצם הנפש משא\"כ הדיבור נעשה בחי' נפרד, ואף",[["1242","9","<b>וארז\"ל אימתי הוא גדול</b>: ראה זח\"ב רלה, א. זח\"ג ה, א. ז\"ח פ' תשא בתחילתה. פ' חוקת ד\"ה רחש לבי. — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם."],["1243","10","<b>אתא שהוא בחי' תרגום</b>: כ\"ה בכ\"מ בדא\"ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381102\" data-slug=\"likkutei-torah\" data-id=\"4001381102\">לקו\"ת ברכה צג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381104\" data-slug=\"likkutei-torah\" data-id=\"4001381104\">צד, ב</a>: ואתה מרבבות קדש ואתא הוא לשון בא רק שהוא בלשון תרגום שהוא בחי' אחוריים כו'. ועוד. וראה סה\"מ עטר\"ת ע' רב: וצ\"ע הרי ואתא הוא גם בלה\"ק כמו ואתה מרבבות קודש, אמר שומר אתא בוקר."],["1244","11","<b>תרגום הוא אחוריים של לה\"ק</b>: שער המצות פ' ואתחנן. טעמי המצות להרח\"ו שם. ועוד. — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם."],["1245","12","<b>וזהו שארז\"ל במקום שאתה מוצא גדולתו</b>: כן הוא בכ\"מ בדא\"ח, והוא ממגילה לא, א — ע\"פ הגירסא בילקוט שמעוני תהלים רמז תשצ\"ד. פסיקתא זוטרתי עקב י, יז. פיה\"מ להרמב\"ם אבות פ\"ד מ\"ד. פחד יצחק בערכו. בחיי עקב י, יח. עבודת הקודש ח\"ג פי\"ב. של\"ה פ' קרח ופ' עקב. רוקח בהקדמה. נוסח ויתן לך (במקום שאומרים זה בויתן לך). שדה צופים על מגילה. ועוד. — ובאיי הים שם מבאר שדוקא גירסא זו מדוייקת. — ואין צורך למה שנדחק בנודע ביהודה מהד\"ת או\"ח ס\"כ. — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם ע' 228 וע' 283."]]],[2000460433,"שאין לך דבר שחוץ ממנו מ\"מ דברה תורה כלשון בנ\"א ועי\"ז נראים לעינינו ליש ודבר נפרד כו', משא\"כ המח' היא מתאחדת וע\"כ שם הם בתכלית הביטול, לפי ששם מאיר אלקות בבחי' גילוי. וזהו שם הגדולה לאה ושם הקטנה רחל, לאה היא בחי' עלמא דאתכסי' הוא בחי' ה' גדולה, וזהו שלאה ילדה ששה בנים שהוא בחי' גילוי מדות עליונות לך הוי' הגדולה והגבורה כו', ושם הקטנה רחל היא בחי' דיבור שנק' קטנה לפי שנעשה מקור לעלמא דאתגלי'<sup data-n=\"1246\">13</sup> שהם בחי' נפרד כו'. וזהו ענין שית תיבין דיחו\"ע שהם בתכלית הביטול. וזהו מ\"ש יקוו המים אל מקום אחד, מים הוא בחי' עלמא דאתכסי'<sup data-n=\"1247\">14</sup> כי כל מה שיש ביבשה יש בים כו', רק שהם בטלים שם בתכלית הביטול, וזהו אל מקום אחד, והיינו כי אף שיש שם ג\"כ ו\"ק כי אחד הוא בחי' ז' רקיעים וארץ וד' רוחות העולם, מ\"מ שם הם בתכלית הביטול בחי' אחד, וזהו יקוו המים שהוא בחי' עלמא דאתכסי' אל מקום אחד שהוא בחי' ביטול. משא\"כ ועד הוא בחילופי אתוון דאחד שאינו מאיר שם הביטול כמו בעלמא דאתכסי' שהוא בחי' הקטנה רחל שהוא בחי' דיבור כו'.\n<b>והנה</b> מ\"ש שביעאה עלייהו, הענין הוא דהיינו אף שנתהוו העולמות בבחי' יש ודבר נפרד מ\"מ המכוון הוא שיהי' בחי' ביטול היש, וזהו שאחר ברוך שם אומרים ואהבת את הוי' אלקיך כו' שאחר זה נעשה בחי' ביטול היש]<sup data-n=\"1248\">15</sup>. והנה בחי' ביטול זה נמשך מבחי' התבוננות איך שהעולמות הם רק מבחי' זיו והארה בעלמא ואינם תופסים מקום כלל וכולא קמי' כל\"ח, עי\"ז נעשה ואהבת בכל לבבך בשני יצריך בבחי' ביטול היש לאין. וזהו בחי' שביעאה עלייהו דהיינו על בחי' שית יומין שהוא בחי' שית דרגין לכורסי' שהוא בחי' הו\"ק דבריאה, ושביעאה עלייהו היינו בחי' והים עליהם מלמעלה שהוא בחי' מל' כו'.\n<b>והנה</b> כמו\"כ בבחי' שית יומין דלעילא ג\"כ שביעאה עילאה עלייהו, והענין הוא דהנה אף שהמדות עליונות הם בבחי' א\"ס מ\"מ כתיב לך הוי' הגדולה כו' שהם בתכלית הביטול<sup data-n=\"1249\">16</sup> שאינם תופסים מקום כלל לגבי עצמותו וכמ\"ש לאו מכל אינון מדות איהו כלל, כי אפי' בחכ' כתי' כולם בחכ' עשית שנחשבת כעשי' גשמי' לפניו, ולכן בכדי להיות אנת הוא חכים דהיינו המשכת אוא\"ס בחכ' הנה החכ' ממש מאין",[["1246","13","<b>וזהו שם הגדולה לאה. . עלמא דאתכסיא. . רחל. . מקור לעלמא דאתגלי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370106\" data-slug=\"torah-or\" data-id=\"3901370106\">תו\"א ויצא כב, ד</a> ואילך."],["1247","14","<b>וזהו מ\"ש יקוו המים. . מים. . עלמא דאתכסי'</b>: ראה בארוכה אוה\"ת בראשית (כרך ז) תתשנה, ב ואילך. סה\"מ תרכ\"ז ע' א ואילך. וש\"נ."],["1248","15","<b>והנה מ\"ש שביעאה עלייהו. . ביטול היש]</b>: ג' שורות אלו חסרים בכת\"י המעתיק בכת\"י 1038, אך נמצאי' בהעתקות אחרות של המאמר, וכנראה הוא השמטת המעתיק."],["1249","16","<b>שהמדות עליונות. . כתיב לך הוי' הגדולה. . בתכלית הביטול</b>: ראה לעיל ד\"ה הללוי' גו' במרומים. וש\"נ."]]],[2000460434,"תמצא, ולכן היא בבחי' ענוותנותו שהיא ירידה גדולה לפניו כמ\"ש מזה בת\"א פ' וירא בד\"ה פתח אלי' וע\"ז ארז\"ל במקום גדולתו<sup data-n=\"e24\">*</sup> שם אתה מוצא ענוותנותו. ועפ\"ז יובן ענין שביעאה עילאה עלייהו בחי' בינה שבה התגלות ע\"ק בחי' לאו מכל אינון מדות איהו ולכן השית יומין עילאין הם בבחי' לך ה' הגדולה שבחי' גדולה זו הוא בבחי' לך בטל וטפל כו'<sup data-n=\"1250\">17</sup>. וזהו מ\"ש וישבות ביום השביעי מכל מלאכתו אשר עשה ואח\"כ כתי' כי בו שבת מכל מלאכתו אשר ברא, והיינו כי יש ב' בחי' שבת, מכל מלאכתו אשר עשה היא בחי' השביתה מבחי' יומין תתאין כי עשי' היא בחי' אחרונה וכמ\"ש אף עשיתיו, ואח\"כ אמר כי בו שבת מכל מלאכתו אשר ברא היא בחי' השביתה מבחי' יומין עלאין.\n<b>וזהו</b> מ\"ש וישב שלמה על כסא ה' כי יש בחי' כסא ה' שהוא ג\"כ בדוגמא זו. דהנה איתא במדרש במג\"א ע\"פ כשבת המלך שש מעלות לכסא זהו ענין ששה סדרי משנה. והענין הוא דהנה ארז\"ל מתניתין מלכתא והיינו כמו מלך שגוזר<sup data-n=\"1251\">18</sup> ואומר ומשפיל ומרומם כו', וכ\"ז הוא עפ\"י חכמתו שחייבה לו שלזה צריך להשפיל ולזה לרומם, וכך מתניתין מלכתא משפיל ומרומם שזה כשר וזה פסול, טמא וטהור, חייב וזכאי, שהוא עפ\"י חכמת התורה שמחייב כך. וזהו מ\"ש ויהי בישורון מלך שנק' מלך ישראל דוקא, וכן כתי' כה אמר ה' מלך ישראל וגואלו, ולכאורה אינו מובן למה נק' מלך ישראל דוקא, דהנה עיקר מלוכה הוא בחי' ביטול מה שכולם בטלים לרצונו, ולכאורה המלאכים הם בטלים יותר ויותר, אף שהנשמות הם למעלה מבחי' מלאכים מ\"מ ירדו למטה בגוף ונה\"ב ואין בהם כ\"כ הביטול כמו במלאכים שאין להם גופים<sup data-n=\"1252\">19</sup> וא\"כ למה לא נק' מלך המלאכים. אך לפי שעיקר הנהגת המלוכה הוא ע\"פ חכ' שהוא ע\"פ חכמת התורה, והנה התורה ניתנה למטה דייקא לישראל, וע\"כ נק' מלך ישראל כו'. וזהו שית דרגין לכורסי' שהוא בחי' ששה סדרי משנה. והנה הכורסיא עצמה הוא בחי' תושב\"כ שהוא בחי' שביעאה עלייהו, וזהו שבתושב\"כ יש חמשה חומשי תורה שהוא כנגד ה' עילאה שהוא בחי' בינה, והשית דרגין הוא בחי' ויו של שם הוי' שהוא מחבר ה' עילאה עם ה' תתאה שהם ב' בחי' שביעאה עלייהו.",[["1250","17","<b>ולכן בכדי להיות אנת הוא חכים. . בטל וטפל כו'</b>: כ\"ז נוסף בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש. ובכת\"י המעתיק כתוב כאן: וזהו מ\"ש והחכ' מאין תמצא שהחכ' נחשבת כאין לפניו, ועל בחי' גדולה זו נא' ג\"כ במקום שאתה מוצא גדולתו שם אתה מוצא ענוותנותו כו', וזהו שביעאה עלייהו דהיינו בחי' בינה שהוא למע' מבחי' המדות עליונות כו'."],["1251","18","<b>ארז\"ל מתניתין מלכתא. . כמו מלך שגוזר</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381292\" data-slug=\"likkutei-torah\" data-id=\"4001381292\">לקו\"ת שה\"ש מא, א</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370222\" data-slug=\"torah-or\" data-id=\"3901370222\">תו\"א שמות מט, ב</a>-<a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">ג. בשלח סד, ב</a>. ועוד."],["1252","19","<b>במלאכים שאין להם גופים</b>: ראה עד\"ז רמב\"ם הל' יסוה\"ת פ\"ב ה\"ג: ברואים צורה בלא גולם כלל והם המלאכים, שהמלאכים אינם גוף וגוי'. וכ\"כ במו\"נ ח\"א פמ\"ט: המלאכים אינם בעלי גוף אלא הם שכלים נבדלים מחומר. אבל ראה לעיל ד\"ה אז ישיר: המלאכי' יש להם ג\"כ גופים רק שהגופים שלהם הוא מאש ורוח בלבד. ועד\"ז לעיל ד\"ה עבדו את ה' בשמחה ובכ\"מ בדא\"ח. וראה בהמובא ע\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091431\" data-slug=\"likkutei-sichot\" data-id=\"1300091431\">לקו\"ש ח\"ט ע' 405</a> [בהערה]."],["e24","*","<b>כמ\"ש מזה בת\"א פ' וירא. . וע\"ז ארז\"ל במקום גדולתו</b>: בשולי הגליון נרשם בגוכי\"ק: שלא כמו שסוברים העולם ע' בת\"א ד\"ה יפה שעה א' בפ' חיי שרה. וע' בפ' וירא בד\"ה פתח אלי' בענין במקום גדולתו כו' י\"ל שזהו לב' בחי' שית יומין דלתתא ודלעילא."]]],[2000460435,"<b>והנה</b> מ\"ש וישב שלמה על כסא הוי' בחי' ישיבה, הענין הוא דהנה ארז\"ל מלך עומד ואגוסטוס יושב<sup data-n=\"1253\">20</sup>, והענין הוא דהנה החילוק שבין עמידה לישיבה<sup data-n=\"1254\">21</sup> היינו כי עמידה הוא בחי' עראי משא\"כ ישיבה הוא בחי' קבע<sup data-n=\"1255\">22</sup>, וזהו החילוק שבין משכן למקדש דהנה במשכן כתי' ואהי' מתהלך באוהל ובמשכן שהוא בחי' דירת עראי, משא\"כ מקדש הוא בחי' קבע<sup data-n=\"1256\">23</sup> שאין בו שינוי כלל, לפי שהוא המשכה מבחי' אני הוי' לא שניתי כו' שאין בו שינוים כלל. וזשארז\"ל כל הקובע מקום לתפלתו (ורב אלפס גורס לתורתו) אויביו נופלים לפניו, וכן אמרו עשה תורתך קבע<sup data-n=\"1257\">24</sup> ומלאכתך עראי דהיינו שעיקר הרצון והפנימי' שלו יהי' בתורה ותפלה, ואין הפי' קבע היינו שילמוד הרבה, אלא אף שאינו יכול ללמוד אלא מעט מ\"מ כיון שזהו עיקר הרצון שלו נק' קבע, לפי שאין בו שינוי כלל, ועי\"ז נמשך מלמעלה ג\"כ בחי' קבע שהוא המשכה מבחי' אני הוי' לא שניתי כו'. וזהו מ\"ש וישב הוי' מלך לעולם שהוא בחי' ישיבה בחי' קבע, ועי\"ז נעשה הגילוי למטה ג\"כ. וזהו מ\"ש ביום השביעי נתעלה וישב על כסא כבודו, דלכאורה אינו מובן מה שייך שבת לבחי' כסא, אך לפי הנ\"ל יובן היטב לפי ששבת הוא בחי' שביעאה שהוא בחי' כסא כו' כי הכסא הוא בחי' שביעאה, וזהו וישב על כסא כבודו בחי' ישיבה כו', וישב הוי' מלך לעולם בבחי' קבע הנ\"ל.\n<b>אך</b> עדיין אינו מובן למה שייך זה לשלמה דייקא מ\"ש וישב שלמה על כסא הוי'. והענין הוא דהנה שלמה הי' דור ט\"ו לאברהם אבינו, דהנה ישראל מונין ללבנה, והנה אנו רואים שעיקר מילוי הלבנה בעיגול שלם הוא בט\"ו דייקא שאז נתמלא כל חסרונה, וכך שלמה הי' דור ט\"ו לא\"א, דהנה באברהם כתי' מי העיר ממזרח צדק יקראהו לרגלו שאז התחיל להאיר, ואח\"כ בימי שלמה נתמלא כל החסרון, לפי שהי' דור ט\"ו. וענין ט\"ו דייקא הענין הוא דהנה ט\"ו הוא בחי' י\"ה, והנה י\"ה הוא בחי' חו\"ב שהם תרדל\"מ, וע\"כ כשישב שלמה על כסא ה' שהוא בחי' שביעאה עלייהו שהוא בחי' בינה ממילא נמשכה ג\"כ בחי' חכ' לפי שהם תרדל\"מ, וזהו הי' רק בכח שלמה דייקא לפי שהוא דור ט\"ו. וזהו ענין ט\"ו שבחים שבישתבח,",[["1253","20","<b>ארז\"ל מלך עומד ואגוסטוס יושב</b>: ראה בהנסמן ע\"ז בסה\"מ תרכ\"ט ע' קמד-ה."],["1254","21","<b>החילוק שבין עמידה לישיבה</b>: ראה בארוכה אוה\"ת חנוכה (כרך ז') תתתרנז, א ואילך. בהעלותך ע' שנט. סה\"מ תרכ\"ט ע' קנא-ב. וש\"נ. תרנ\"ד ע' קסב ואילך. המשך תער\"ב ח\"א ע' תשא. ח\"ג ע' א'רצא ואילך. ד\"ה ואתה ברחמיך תשי\"ז ותשל\"ט. ד\"ה באתי לגני וד\"ה היושבת בגנים תשל\"ט [סה\"מ באתי לגני ח\"ב ע' קסג. קסח ואילך. קעה]."],["1255","22","<b>ישיבה הוא בחי' קבע</b>: מו\"נ ח\"א פי\"א. ועייג\"כ בהוספות לס' דרך אמונה (ס' החקירה) להצ\"צ [קלו, ב — קלז, א]. — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם."],["1256","23","<b>החילוק שבין משכן למקדש. . דירת עראי. . קבע</b>: בהבא לקמן ראה אוה\"ת ויגש שנ, ב. נ\"ך ס\"ע לה-ו. סה\"מ תרכ\"ט ס\"ע כה-ו."],["1257","24","<b>וזשארז\"ל כל הקובע מקום לתפילתו. . עשה תורתך קבע</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670198\" data-slug=\"or-hatorah-hb\" data-id=\"8158670198\">אוה\"ת</a> ויגש שם שנ, א-ב. נ\"ך ע' לה ואילך. סה\"מ תרכ\"ט שם ע' כז ואילך."]]],[2000460436,"והיינו שכדי שיהי' בחי' ישתבח שמך דהיינו בחי' תוקף ושבח בשמך, ע' בלק\"ת בד\"ה כי תצא<sup data-n=\"1258\">25</sup> הא' ססי' ב', וזהו לעד שיהי' בבחי' נצחי' בחי' קבע, זהו ע\"י ט\"ו שבחים שבישתבח עי\"ז ממשיכים מבחי' י\"ה כו', (וזהו<sup data-n=\"e25\">*</sup> מ\"ש אח\"כ מלך יחיד שיהי' בחי' מלך יחיד דהיינו שיהי' מאיר בבחי' מלך מבחי' יחיד שהוא בחי' אני הוי' לא שניתי כו'). וזהו ג\"כ ט\"ו תיבין דיברכך<sup data-n=\"1259\">26</sup>, דהנה ברכת כהנים הוא ג\"כ ברכה והמשכה לבחי' מל' וכמ\"ש כה תברכו כו', שהוא ברכה לבחי' כה דייקא זהו ע\"י ט\"ו תיבין כו', שהוא המשכת בחי' י\"ה. וזהו מ\"ש וישב שלמה על כסא הוי' לפי ששלמה דייקא לפי שהי' דור ט\"ו הי' יכול להמשיך מבחי' י\"ה שיהי' בחי' וישב הוי' מלך לעולם שיהי' בחי' קבע מבחי' אני הוי' לא שניתי כו'.\n<b>והנה</b> איתא בזהר פ' תולדות דקל\"ה א' ת\"ח אתא שלמה ובעי למיקם על מלוי דאורייתא ועל דקדוקי אורייתא ולא יכיל, אמר אמרתי אחכמה והיא רחוקה ממני, שלא הי' יכול להשיג בחי' פנימיות התורה עד\"מ טעם מצות פרה אדומה וכדומה וא\"כ לכאו' צ\"ל איך אמר וראיתי אני שיש יתרון לחכמה כו' הלא לא הי' יכול להשיג בבחי' הפנימיות כו' ובמה ידע יתרון החכמה היא בחי' חכמת התורה. אך הענין הוא דהנה כתיב עוטה אור כשלמה, שהתורה היא ממוצע בין אוא\"ס לעולמות<sup data-n=\"1260\">27</sup>, דהנה כדי שיתהוו העולמות שהם בע\"ג מאא\"ס הבלתי בע\"ג בתכלית שא\"א להיות שני הפכים יותר מזה, ע\"כ הוצרך להיות ממוצע והתורה היא ממוצע וכמ\"ש ואהי' אצלו אמון אומנא, דאסתכל באורייתא וברא עלמא. והנה כל ממוצע צריך שיהי' כלול מב' בחי' דהיינו מבחי' אא\"ס הבלתי בע\"ג וגם שיהי' מקור לעולמות שהם בע\"ג, וזהו בחי' חכ', כי יש ב' בחי' חכ' ח\"ע וח\"ת, בח\"ע שורה אוא\"ס וכמ\"ש הוי' בחכ', וח\"ת הוא הנעשה מקור לעולמות, בחי' ל\"ב פעמים אלקים שבמע\"ב, ודרך כלל אצי' הוא ממוצע בין אא\"ס לעולמות הנבראים, וזהו שבאצי' יש שני בחי' איהו וחיוהי חד איהו וגרמוהי חד שהם נעשים מקור לעולמות כו', וזהו עוטה אור כשלמה, אור הוא בחי' אא\"ס השורה בתורה שהוא בחי' פנימי' התורה שהוא בחי' א\"ס ממש, ושלמה הוא בחי' לבוש של התורה שהיא בחי' תורה הנגלית<sup data-n=\"1261\">28</sup> שהוא מה שנעשה מקור לעולמות כו'. וזהו שאמר וראיתי אני דהיינו שראה איך שהיא רחוקה ולא יוכל לבוא בהשגה",[["1258","25","<b>ישתבח שמך. . תוקף ושבח בשמך ע' בלק\"ת בד\"ה כי תצא</b>: פ' תצא לה, רע\"א."],["1259","26","<b>וזהו ענין ט\"ו שבחים שבישתבח. . ט\"ו תיבין דיברכך</b>: בכ\"ז ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450586\" data-slug=\"or-hatorah-hb\" data-id=\"8316450586\">אוה\"ת תבוא ע' תתרנו</a>. תתרסו. אוה\"ת סידור ס\"ע קט-י. וש\"נ. ס\"ע קי ואילך. סה\"מ תרנ\"ח ס\"ע ריד ואילך."],["1260","27","<b>שהתורה היא ממוצע בין אוא\"ס לעולמות</b>: ראה סה\"מ תרכ\"ט ע' קמו. וש\"נ. תרל\"א ע' קנד. ובארוכה המשך תער\"ב ח\"א ע' שכד ואילך. ועוד."],["1261","28","<b>וזהו עוטה אור כשלמה. . פנימי' התורה. . תורה הנגלית</b>: ראה בכ\"ז ד\"ה עוטה אור ת\"ש [סה\"מ הש\"ת ע' 67 ואילך]. שיחת י\"ב תמוז תש\"ח [סה\"מ תש\"ח ע' 251. סה\"ש תרצ\"ט ע' 342]. — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם."],["e25","*","<b>(וזהו מ\"ש אח\"כ מלך יחיד. . שניתי כו')</b>: תיבות אלו נרשמו בכת\"י המעתיק, וכ\"ק אדמו\"ר מהר\"ש הקיפם בין חצע\"ג, והעיר ע\"ז: צ\"ע שפי' מלך יחיד היינו כמו שמל' דאצי' נעשה יחיד בבריאה עתיק דבריאה."]]],[2000460437,"כלל כי לא ידע אנוש ערכה, אך זה ראה ג\"כ דאעפ\"י שאינו בא בהשגה כלל מ\"מ ישנו בהעלם גם בתורה הנגלית ואפילו כל רזין דאורייתא דלא יכול לאדבקא בהון ישנם ג\"כ בתורה, וגם השמים החדשים והארץ החדשה כו' ישנם בתורה הנגלית, אלא שאיננו מושג לנו כו'. וזהו וראיתי אני שיש יתרון לחכמה מן הסכלות דהיינו לחכמת התורה לפי שכל בחי' רזין דאורייתא ישנם בה כו'. והנה שלמה דייקא אמר וראיתי אני, והיינו לפי ששלמה הוא אותיות שלמה שהוא בחי' לבוש של התורה ע\"כ הוא ראה זה שהכל ישנו בתורה משא\"כ אחר כו', ומ\"ש שיש יתרון לחכמה מן הסכלות אינו הפי' סכלות גמור אלא החכמה של עה\"ד טו\"ר נק' סכלות כו', וזהו שאמר וראיתי אני שיש יתרון לחכמה מן הסכלות כיתרון האור מתוך החשך.\n<b>והנה</b> מ\"ש כיתרון האור מן החשך דייקא, הענין הוא דהנה כתי' ויבדל אלקים בין האור ובין החושך ופי' במדרש אור זו מעשיהם של צדיקים ע\"ש כי נר מצוה ותורה אור וחשך הוא מעשיהם של רשעים שנק' חושך כי במחשך מעשיהם כו', וזהו שא' כיתרון האור מן החושך דהיינו כמו שיש יתרון למעשיהם של צדיקים על מעשה הרשעים שאין להם ערך כלל, כך יש יתרון לחכ' מן הסכלות כו'<sup data-n=\"e26\">*</sup>.\n<b>ועוי\"ל</b> פי' כיתרון האור מתוך החושך דהנה ארז\"ל מ\"ט עיזי מסגי ברישא והדר אימרי כברייתו של עולם ברישא חשוכא והדר נהורא<sup data-n=\"1262\">29</sup>, והיינו שבכל דבר החושך קודם, כי קליפה קדמה לפרי, וכמו שאנו רואים שמתחלה נגדל הקש והתבן ואח\"כ נגדל הפרי כו', וכן באגוז מתחלה נגדל הקליפה ואח\"כ הפרי כו', וכן בכל דבר שהפרי בא אח\"כ, וזהו מ\"ש במרכבת יחזקאל ג\"כ מתחלה והנה רוח סערה וענן גדול ואש מתלקחת ונוגה לו סביב ואח\"כ כתיב ומתוכה כעין החשמל כו', והנה כמו\"כ באור וחושך החושך קדם.\n<b>והענין</b> הוא דהנה ידוע שיש ב' בחי' בהנהגת העולם, בחי' טבע ולמעלה מהטבע<sup data-n=\"1263\">30</sup>, כי טבע הוא פי' טובעו בים סוף, וכן קידושין לטיבועין ניתנו, דהיינו שהקידושין אינן נגבין כו', וכך טבע הוא שהחיות אלקי מוסתר ונעלם אף שהוא",[["1262","29","<b>ארז\"ל מ\"ט עיזי מסגי ברישא. . ברישא חשוכא והדר נהורא</b>: בהבא לקמן ראה בארוכה סה\"מ תרכ\"ט ס\"ע קיז ואילך. וש\"נ."],["1263","30","<b>ידוע שיש ב' בחי'. . טבע ולמעלה מהטבע</b>: ראה בארוכה לקמן ח\"ב ד\"ה מזמור לתודה. וש\"נ."],["e26","*","_<b>מן הסכלות כו'</b>: בגוכי\"ק נרשם כאן בשולי הגליון:\nנשא תר\"ל מן וראיתי עד כאן השלמה למאמר חביבין ישראל כו' כלי חמדה שבו נבה\"ע דשבת פ' במדבר עחה\"ש)."]]],[2000460438,"מחדש בטובו בכ\"י מע\"ב, אך מ\"מ הוא על אופן א' וכמ\"ש עוד כל ימי הארץ זרע וקציר כו', והגם שעתה ג\"כ יש בחי' אותות ומופתים, אך מ\"מ אינם נראי' לעינינו וכמ\"ש אותותינו לא ראינו כו' דהיינו שאנו אין רואים את האותות אבל מ\"מ ישנם כו', וזהו מ\"ש לעושה נפלאות גדולות לבדו אין בעל הנס מכיר בניסו רק הקב\"ה לבד, ולא יש לנו שום התגלות הנסים ונפלאות שעשה לנו בכל יום לפי שעתה החיות אלקי מוסתר ונעלם וכמ\"ש אכן אתה אל מסתתר כו'. וזהו שנק' חשך שהוא בחי' העלם והסתר. והנה אור הוא בחי' התגלות הנסים ונפלאות למעלה מן הטבע, וכמו שהי' בשעת קרי\"ס, וזהו מ\"ש שם ויהי הענן והחשך ויאר את הלילה שהחשך גופא האיר לפי שהי' התגלות גילוי אא\"ס למעלה כו' וכמ\"ש הפך ים ליבשה, וזהו שנק' אור כו'. וזהו מ\"ש לדוד ה' אורי וישעי, וארז\"ל אורי בים וישעי בים, אורי בים ע\"ש ויאר את הלילה, וישעי בים ע\"ש מ\"ש התיצבו וראו את ישועת ה' כו', והיינו לפי שבים הי' התגלות אלקות למעלה מן הטבע נק' בחי' אורי. והנה ע\"י תומ\"צ ממשיכי' שיהי' בחי' גילוי אור כי אורי וישעי בגי' תרי\"ג, ואורי הוא בחי' פנימי' וישעי הוא בחי' מקיף<sup data-n=\"1264\">31</sup>, ובמצות יש ב' בחי' דהיינו מצות שהם למעלה ממשיכי' אור פנימי ויש מצות שממשיכי' בחי' מקיפי'. וזהו מ\"ש וראיתי אני שיש יתרון לחכ' מן הסכלות כיתרון האור מן החושך, והיינו לפי שני הפי' הנ\"ל שיתרון האור הוא על החשך וכך יתרון החכ' הוא על הסכלות.\n<b>ועוי\"ל</b> יתרון האור מן החשך היינו מן החשך דוקא נמשך יתרון באור וכמו שאנו רואי' ביום ולילה שיתרון היום הוא מן הלילה דוקא שאם הי' יום לבד לא הי' יכול להתקיים העולם כי בכמה דברים נצרך הלילה ליום כי בלילה צריך לנוח ולא איברי לילה אלא לשינתא כו', נמצא שיש יתרון ליום מן הלילה דוקא. וזהו שברייתו ש\"ע ברישא חשוכא והדר נהורא דוקא, ולמה הי' כך והיינו לפי שע\"י בירור החשך דוקא עי\"ז נעשה יתרון האור כו', לפי ששרש החשך הוא קדם לאור לפי שנמשך מבחי' עולם התהו שקדם לתיקון רק שנפל בשבירה וע\"י בירור החשך עי\"ז נעשה יתרון האור כו'. וזהו שבעין יש לבן ושחור והראי' מלובש בשחור שבעין דוקא ולא בלבן, והיינו לפי שיתרון האור הוא מן החשך דוקא כשהחשך נתברר. וזהו מ\"ש יצרנהו כאישון עינו דהיינו כהשחור שבעין כו', לפי שע\"י בירור החשך בבחי' אתכפי' ואתהפכא מחשוכא לנהורא כו' עי\"ז נעשה יתרון האור. וכך יתרון החכ' היא מן הסכלות דוקא שהוא בחי' חכ' של עה\"ד טו\"ר, וע\"י בירור הסכלות שהוא עה\"ד טו\"ר עי\"ז דוקא נעשה יתרון החכ' כו' שיהי' המשכת גילוי פנימיות התורה שבו מלובש אא\"ס ממש.",[["1264","31","<b>ואורי הוא בחי' פנימי וישעי. . מקיף</b>: לקו\"ת פ' ראה ביאור לד\"ה וכל בניך רפ\"ג (לא, ג). — הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח שם."]]],[2000460439,"<b>וזהו</b> שהשיב להם משה על שאלתם תנה הודך על השמים, כלום יצה\"ר יש ביניכם אף שבקשו את התורה ברוחניות כמו שהיא למעלה שהיא שייכה אף בלי יצה\"ר כו', אך יתרון האור שבתורה זהו נמשך דוקא ע\"י יצה\"ר שהוא חשך וע\"י שמבררים אותו עי\"ז דוקא נעשה יתרון בחכ' כו' שלזה דוקא ירדה התורה למטה וע\"כ אמר להם כלום יצה\"ר יש ביניכם, כי עיקר המכוון מנתינת התורה הוא כדי שעי\"ז יהי' נמשך יתרון האור בתורה, וכמו שארז\"ל כל הלומד תורה לשמה שהפי' הוא לשם התורה<sup data-n=\"1265\">32</sup> דהיינו להמשיך אא\"ס בתורה, וזה א\"א כ\"א ע\"י יצה\"ר דוקא שעי\"ז דוקא נמשך יתרון האור כו', וע\"כ הודו לו ואמרו מה אדיר שמך בכל הארץ דוקא כנ\"ל.",[["1265","32","<b>תורה לשמה. . לשם התורה</b>: ראה בארוכה סה\"מ תרכ\"ט ס\"ע קמו ואילך. [ובהנסמן שם בתחילת המאמר]. תרל\"א ע' קנד-ה."]]],[2000460440,"<h3>הוספה ב </h3><h3>יהודה בן תימא כו' עז כנמר</h3>\n<b></b><b>[לד\"ה יהודא בן תימא<sup data-n=\"1266\">1</sup> תרל\"ט]</b>\n<b>בס\"ד. </b>\n<b>יהודא</b> בן תימא אומר הוי עז כנמר וקל כנשר רץ כצבי וגבור כארי לעשות רצון אביך שבשמים. וצ\"ל שהרי נאמר עז פנים לגיהנם, ומהו המעלה של עז כנמר. אך הענין הוא דכמו שיש בלעו\"ז עז פנים, כמ\"כ יש בקדושה ג\"כ בחי' עז פנים, וזהו עז כנמר, והיינו שזהו\"ע גדרים וסייגים שגזרו רבנן, שזהו\"ע התגברות כדי שלא יבאו ח\"ו לידי איסור דאורייתא. והנה עיקר הגזירות הי' בחורבן בית שני<sup data-n=\"1267\">2</sup>, וצ\"ל למה לא גזרו מלכתחילה, ולמה בחורבן דוקא גזרו הגזירות.\n<b>אך</b> הענין הוא דהנה כתי' עד שיפוח היום ונסו הצללים סוב ודמה לך דודי לצבי או לעופר האיילים על הרי בתר, עד שיפוח היום קאי על זמן הגלות, והנה אז בגלות ודמה לך לצבי כו'. והענין הוא דהנה ארז\"ל גלו לבבל שכינה עמהם גלו לאדום שכינה עמהם וכמ\"ש ושמתי כסאי בעילם, ואף שבחו\"ל אינו מאיר השראת השכינה, אך היינו כדי ליינקא ממנה אבל כדי לאגנא עלייהו שכינה עמהם וכמ\"ש בזהר. וזהו בשושן הבירה אשר בעילם המדינה, שושן הוא קאי על בחי' שכינה, וכמ\"ש כשושנה בין החוחים, שבגלות נק' כשושנה בין החוחים. אך מ\"מ גם בגלות יש בה מדריגות, שפעם נא' והעיר שושן נבוכה, ופעם נאמר והעיר שושן צהלה ושמחה, דהיינו כשנמשך בה המשכה מלמעלה אז היא צהלה ושמחה, וזהו דמה לך דודי לצבי שגם בגלות נמשך המשכה מלמעלה, ואדרבה שהמשכה זו היא מלמעלה",[["1266","1","<b>יהודא בן תימא</b>: הוא הנחה ממאמר כ\"ק אדמו\"ר הצ\"צ (ונמצא בכת\"י 1063 שכה, א ואילך), ונדפס כאן לראשונה בקשר עם ד\"ה יהודא בן תימא מש\"פ תצוה תרל\"ט המיוסד על מאמר זה, המאמר דתרל\"ט לא נרשם בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש בס' תרל\"ט, ולע\"ע נמצא רק קיצור מתוכן המאמר כפי שנרשם ע\"י כ\"ק אדמו\"ר מוהרש\"ב הנדפס לעיל ע' רכד ואילך, ולשלימות הענין הדפסנו כאן מאמר זה בו נמצא תוכן המאמר בשלימות.\nהמאמר מיוסד על ד\"ה להבין למה לעתיד יתבטלו כל הנביאים וכתובים בהוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370517\" data-slug=\"torah-or\" data-id=\"3901370517\">תו\"א מג\"א קטז, סע\"א</a> ואילך. ובשינויים בס' מאמרי אדה\"ז תקס\"ח ח\"א ס\"ע פט ואילך. שם ח\"ב ס\"ע תרצב ואילך. ובתוס' הגהות ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770402\" data-slug=\"or-hatorah-hb\" data-id=\"8316770402\">אוה\"ת</a> מג\"א (הוצאת תש\"נ) ע' רל ואילך. רנד ואילך. וקיצורים והגהות שם ע' רכז-ח. רמו ואילך. רנ-נא. רנב ואילך. רס ואילך. תוכן המאמר נמצא בשינויים בד\"ה ביום השני הקריב בסה\"מ תרכ\"ז ע' רה ואילך.\nלכמה מעניני המאמר ראה גם ד\"ה היושבת בגנים גו' ברח דודי: בס' מאמרי אדה\"ז תק\"ע ע' נד ואילך. אוה\"ת שה\"ש (כרך ב) ע' תשע ואילך. תשעט ואילך. תשפב ואילך. שם (כרך ג) ס\"ע א'טז ואילך. המשך מים רבים תרל\"ו פקל\"ב-ד (ס\"ע קמא ואילך). סה\"מ תרס\"ה ע' רלב. הוספות להמשך תרס\"ו (הוצאת תנש\"א) ע' תקצז ואילך. סה\"מ מלוקט ח\"ב ע' רכט ואילך. תשי\"ז ע' 77 ואילך. תשל\"ח ע' קסג ואילך."],["1267","2","<b>גדרים וסייגים שגזרו רבנן. . עיקר הגזירות הי' בחורבן בית שני</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380661\" data-slug=\"likkutei-torah\" data-id=\"4001380661\">לקו\"ת מטות פד, סע\"ד</a> ואילך. סה\"מ תרל\"ב ח\"א ע' פה. תרל\"ד ע' קמב-ג."]]],[2000460441,"יותר, וזהו מ\"ש שושן עמק איומה, והיינו שאף ששושן היא בעמק דהיינו שהיא בגלות אעפי\"כ היא איומה שנמשך בה המשכה מבחי' איום ונורא כו'. וזהו דמה לך דודי לצבי.\n<b>והענין</b> הוא דהנה יש למעלה כמה בחי' מרכבות, דהנה יש מרכבה של סוסים וכמ\"ש כי תרכב על סוסיך מרכבותיך ישועה שבמ\"ת הי' התגלות וירידת אלקות ע\"י מרכבה של סוסים<sup data-n=\"1268\">3</sup>, דהנה כדי שיומשך בחי' תומ\"צ למטה בגשמיות, רמ\"ח פיקודין רמ\"ח אברים דמלכא ושס\"ה ל\"ת שס\"ה גידין שהוא ענין בחי' כמראה אדם וכמ\"ש ועל הכסא דמות כמראה אדם, וכדי שיומשך מבחי' כמראה אדם למטה זהו ע\"י מרכבה של סוסים, כי סוסים הם בחי' אותיות שהוא בחי' אותיות התורה שהם מורידים וממשיכים בחי' גילוי אלקות למטה, לפי שהסוס הוא מרכבה לבחי' אדם, והיינו שהם ממשיכין המשכה מבחי' כמראה אדם למטה. והגם שיש למעלה בחי' מרכבה של חיות ואופנים, אך זהו למעלה לבד שע\"י נמשך רק למעלה בחי' גילוי אלקות, אבל כדי שיומשך למטה זהו דוקא ע\"י מרכבה של סוסים, כי סוס הוא בגי' ב\"פ ס\"ג שהוא המשכה מבחי' שם ס\"ג שהוא בחי' כי גאה גאה ע\"כ יכול להוריד ולהמשיך למטה ג\"כ, כי לגבי בחי' זו מעלה ומטה שוין כו'. ויש ג\"כ מרכבה של כרוב וכשארז\"ל בלילי' מאי קא עביד קוב\"ה רוכב על כרוב קל שלו ושט בח\"י אלף עולמות כו'. אך הנה מה שהסוסים ממשיכים ירידת אלקות למטה זהו על הר סיני, וכמ\"ש כי תרכב על סוסיך שזה הי' בזמן מ\"ת שהי' על ה\"ס שהר סיני היא בחי' ביטול וכמ\"ש והר סיני עשן, עולם שנה נפש שהעולם הוא בטל. אבל כדי שיומשך למטה בגלות בחי' המשכת אלקות זהו אינו יכול להיות ע\"י הסוס. וכדי שיומשך בגלות בחי' המשכת אלקות לאגנא עלייהו זהו ע\"י דמה לך דודי לצבי, כי צבי הוא קל ברגליו שרץ במהרה מהר לעמק ומעמק להר בלי עכוב כלל מה שאין זה בכח הסוס כלל. וזהו דמה לך דודי לצבי, שע\"י בחי' צבי יכול לימשך אפי' בגלות ג\"כ. וזהו ודמה לך לצבי, דהנה אדם הוא בחי' אדמה לעליון שהוא רק בחי' דמות לבד, אבל הצבי ממשיך מבחי' לך שהוא למעלה מבחי' אדם, דהיינו מבחי' כי לא אדם הוא שהוא בחי' עליון ממש. וזהו שעל הצבי לא יוכל לרכב עליו אדם, לפי שהוא מרכבה למעלה מבחי' אדם, כי אדם הוא רק אדמה לעליון, ולזה מצד בחי' זו הסוס הוא רק מרכבה לבחי' אדם, אבל הצבי הוא מרכבה לבחי' כי לא אדם הוא, ולזה מצד בחי' זו יוכל להיות נמשך אפי' בגלות ג\"כ המשכת אלקות שזהו ענין השראת השכינה כדי לאגנא עלייהו כו'. וזהו ודמה לך דודי לצבי או לעופר האילים על הרי בתר, הרי בתר הם טורי דפרודא<sup data-n=\"1269\">4</sup>, שאפי' בבחי' טורי דפרודא נמשך ג\"כ בחי' ירידת והמשכת אלקות, וזהו מ\"ש ואף גם זאת בהיותם בארץ אויביהם לא מאסתים",[["1268","3","<b>וכמ\"ש כי תרכב על סוסיך. . שבמ\"ת הי'. . מרכבה של סוסים</b>: בהבא לקמן ראה [נוסף להנסמן לעיל בתחילת המאמר] <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381174\" data-slug=\"likkutei-torah\" data-id=\"4001381174\">לקו\"ת שה\"ש יא, סע\"ב</a> ואילך. וראה גם סה\"מ תרל\"ד ע' שנג. וע' שנט."],["1269","4","<b>הרי בתר הם טורי דפרודא</b>: ראה בכ\"ז לקו\"ת דרושים לשבת שובה סה, ג."]]],[2000460442,"ולא געלתים לכלתם, לכלתם כתי' ששכינה עמהם<sup data-n=\"1270\">5</sup> ואדרבה שבגלות נמשך ממקום עליון יותר.\n<b>והנה</b> כדי שיומשך בחי' דמה לך דודי לצבי כו' שהיא בחי' שלמעלה מהשתלשלות, זהו מה שא' יהודא בן תימא הוי עז כנמר, דהוא ע\"י גזירות וסייגים של דברי סופרים, כי ערבים עלי דברי סופרים יותר מיינה של תורה, כי תורה אורייתא מח\"ע נפקת שהיא בחי' כמראה אדם, אבל ע\"י ד\"ס ממשיכים מלמעלה מבחי' כמראה אדם, ולכך ערבים עלי ד\"ס. ולזה עיקר הגזירות תיקנו בחורבן ב\"ש, י\"ח דבר שגזרו ב\"ש וב\"ה, והיינו לפי שבגלות צריך שיהי' נמשך מבחי' דמה לך דודי לצבי, ולכך כדי להמשיך בחי' זו זהו ע\"י עז כנמר כו' רץ כצבי שזהו ענין התגברות בקדושה גזירות וסייגים כו'. וזהו עז כנמר שזהו ע\"ד מ\"ש כי עם קשה עורף הוא וסלחת, שקשה עורף הוא למעליותא<sup data-n=\"1271\">6</sup> ולכך וסלחת, והיינו שקשה עורף הוא בחי' ביטול הרצון שלמעלה משכל וטו\"ד כלל, וכמו עד\"מ עקשות שמתעקש אעפ\"י שמבין בשכלו שהוא כנגד השכל, אעפ\"כ הוא מתעקש בלתי שום שכל לפי שכך הוא רוצה שהוא בחי' רצון שלמעלה מן השכל, וכך יש בחי' זו בקדושה בחי' קשה עורף ביטול הרצון שלמעלה מן השכל שזהו ענין עז כנמר כו', ועי\"ז נמשך מלמעלה ג\"כ בחי' המשכה שלמעלה מבחי' אדם שיכול להיות נמשך אפי' כמו שהם בגלות כו', וזהו מ\"ש בשאול ויהונתן מנשרים קלו ומאריות גברו והיינו לעשות רצון קונם כו'.\n<b>וזהו</b> מ\"ש אתה גבור לעולם אד' מחי' מתים אתה, והענין הוא דהנה ארז\"ל לא גלו ישראל אלא כדי להוסיף עליהם גרים. ולכאורה אינו מובן שהרי אנו רואים שאין בינינו גרים כלל, אך הענין הוא דהנה גרים קאי על ניצוצות דקדושה<sup data-n=\"1272\">7</sup> שנפלו בשבירת הכלים מבחי' ז' מלכין קדמאין דתהו שנפלו בשבירה שנא' וימלוך וימת כו', ולא גלו ישראל אלא כדי להוסיף עליהם גרים דהיינו כדי לברר אותן הנצוצות ולהעלותן לקדושה. וזהו מחי' מתים אתה שמחי' אותן מתים דהיינו אותן ניצוצות שנפלו למטה. וזהו מחי' בגי' ס\"ג לפי ששרש השבירה הי' בשם ס\"ג וצריך להעלותן לשם ס\"ג. וזהו מחי' מתים כו' והיינו ע\"י שאדם אוכל מאכל ומברך עליו תחילה וסוף עי\"ז הוא מברר אותן הניצוצות שנפלו שם. אך הנה כדי שיוכל לברר אותן נמשך זה הכח מלמעלה. וזהו אתה גבור לעולם אד' שהוא ענין שם אגל\"א<sup data-n=\"1273\">8</sup>, שנותן כח לברר ולהעלות את הניצוצין להיות בחי' מחי' מתים. וזהו רב להושיע,",[["1270","5","<b>וזהו מ\"ש ואף גם זאת. . לכלתם כתי' ששכינה עמהם</b>: ראה בכ\"ז אוה\"ת מג\"א שם ע' רלא."],["1271","6","<b>כי עם קשה עורף הוא וסלחת שקשה עורף הוא למעליותא</b>: נסמן לעיל ע' ריא."],["1272","7","<b>ארז\"ל לא גלו ישראל. . להוסיף עליהם גרים. . ניצוצות דקדושה</b>: ראה הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370524\" data-slug=\"torah-or\" data-id=\"3901370524\">תו\"א מג\"א שם קיז, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370022\" data-slug=\"torah-or\" data-id=\"3901370022\">תו\"א בראשית ו, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370048\" data-slug=\"torah-or\" data-id=\"3901370048\">לך לך יא, סע\"א</a>-ב. לקו\"ת ואתחנן ט, ד. תו\"ח חיי\"ש קכא, סע\"ב ואילך. קכה, ד. ביאוה\"ז לאדהאמ\"צ קלו, א ואילך. לעיל ד\"ה ראה ריח בני. ובכ\"מ."],["1273","8","<b>וזהו אתה גבור לעולם אד'. . שם אגל\"א</b>: ראה [נוסף לתו\"א מג\"א שם] סידור עם דא\"ח קנח, ב ואילך. וראה גם שם קנו, ד. שם בהוספות שטו, א-ב. אוה\"ת ויחי שסד, א."]]],[2000460443,"דהנה כל רב מבבל וכל רבי מא\"י, והיינו שבא\"י מאיר בחי' יו\"ד שהוא בחי' חכ'<sup data-n=\"1274\">9</sup> בחי' ביטול, משא\"כ בבבל אינו מאיר בחי' יו\"ד, וזהו רב בחי' ריבוי ופירוד, אך ע\"י עז כנמר וגבור כארי עי\"ז נעשה רב להושיע שאפילו בבחי' ריבוי ופירוד נמשך בחי' ישועה כו', שזהו ענין דמה לך דודי לצבי כו'.\n<b>והנה</b> כתי' ברח דודי ודמה לך לצבי או לעופר האילים על הרי בשמים, והיינו שפסוק דמה לך דודי לצבי על הרי בתר מורה על בחי' המשכה שמלמעלה למטה שנמשך בבחי' טורי דפרודא כו', ופסוק זה דמה לך כו' על הרי בשמים הוא בבחי' העלאה ממטה למעלה, והיינו שהעלאה שבגלות שהוא ג\"כ ע\"י בחי' צבי הוא ג\"כ בבחי' הרי בשמים שהוא בחי' למעלה מהשתלשלות. דהנה בשמים הוא בחי' ריח, והנה ריח הוא למעלה מבחי' טעם, כי טעם הוא כמו בלחם וכה\"ג הוא שמחבר הנשמה עם הגוף, שזהו ענין בחי' כמראה אדם שהוא ענין התחברות אורות וכלים, שזהו ע\"י התורה שנק' לחם וכמ\"ש לכו לחמו בלחמי, וכן קרבנות נק' לחם וכמ\"ש את קרבני לחמי לאשי, אבל ריח הוא דבר שהנשמה נהנית ממנו ולא הגוף שהוא למעלה מהתחברות אורות וכלים, וזהו על הרי בשמים שהעלי' שע\"י זמן הגלות הוא בבחי' ריח שלמעלה מבחי' כמראה אדם, וזהו שנא' במשיח והריחו ביראת ה'<sup data-n=\"1275\">10</sup>.\n<b>והנה</b> בזה יובן ענין אחשורש שלכאורה אינו מובן איך נשאת אסתר שהיא בחי' מל' דקדושה לאחשורש שהוא בחי' קליפה. אך הענין הוא דכמו שיש אחשורש בלעו\"ז יש אחשורש בקדושה, והיינו שאחשורש הוא ענין אחש ורש, אחש הוא מלשון חושה לעזרתי בעתה אחישנה, חשן המשפט, והיינו שאחשורש קאי על המשכה שנמשך בגלות, והנה בגלות נמשך המשכה שלמעלה מסדר השתלשלות וכנ\"ל בפי' דמה לך דודי לצבי כו'. וזהו ענין אחש ורש אחש, היינו שההמשכה נמשך במהירות וכמו שהצבי רץ במהרה מאד והיינו לפי שהוא המשכה שלמעלה מסדר השתלשלות. ולכן המשכה זו נמשך אפי' בבחי' רש שהוא ענין גלות וכמ\"ש ענבימו ענבי רוש שהוא בחי' עניות אשכלות מרירות למו אעפי\"כ נמשך המשכה זו כו'. וגם י\"ל שרי\"ש הוא בחי' דלי דלות<sup data-n=\"1276\">11</sup> כי דלי\"ת מורה ג\"כ על בחי' עניות, אבל רי\"ש הוא בחי' עוני יותר שהוא דלי דלות, וכמו שמצינו בקרבן עולה ויורד שיש בו דלות ודלי דלות, וזהו ההפרש בין דלות לריש כי דלי\"ת יש בו יו\"ד מלאחריו<sup data-n=\"1277\">12</sup>,",[["1274","9","<b>כל רב מבבל וכל רבי מא\"י. . בחי' יו\"ד. . חכ'</b>: בכ\"ז ראה גם סה\"מ תרל\"ג ח\"ב ע' תכז. וש\"נ."],["1275","10","<b>ריח הוא דבר שהנשמה נהנית ממנו. . וזהו שנא' במשיח והריחו ביראת ה'</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ב ח\"א ע' סב ואילך. אמ\"ב ח\"ג (הוצאת תשמ\"ה) קכו, ב ואילך. מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' קכח ואילך. וש\"נ."],["1276","11","<b>רש. . וכמ\"ש ענבימו ענבי רוש שהוא בחי' עניות. . וגם י\"ל שרי\"ש הוא בחי' דלי דלות</b>: ראה (ב' הפי' באו\"א) בהוספות לתו\"א מג\"א שם קח, א. לעיל בהנחת כ\"ק אדמו\"ר מוהרש\"ב."],["1277","12","<b>וזהו ההפרש בין דלות לרי\"ש. . יו\"ד מלאחוריו</b>: ראה בכ\"ז בארוכה אוה\"ת לך לך פח, א. תרומה ס\"ע א'תקיג ואילך. סה\"מ תרל\"ג ח\"א ע' קנב ואילך. תרנ\"ח ע' ריא ואילך. תרפ\"ג ע' קעח ואילך. תרצ\"ט ע' 128 ואילך. ה'שי\"ת ע' 119 ואילך. ועוד."]]],[2000460444,"משא\"כ רי\"ש אין בו יו\"ד הוא בחי' דלי דלות. ואפ\"ל שיו\"ד שיש בדלות זהו ע\"ד מ\"ש העשיר לא ירבה ממחצית השקל והדל לא ימעיט, והנה מחצית השקל הוא בחי' יו\"ד, וכמ\"ש בזהר אבנא למשקל בה דא יו\"ד<sup data-n=\"1278\">13</sup>, וכתי' והדל לא ימעיט, שאפי' בדל יש ג\"כ בחי' יו\"ד, משא\"כ רי\"ש אין בו יו\"ד כלל שהוא בחי' דלי דלות כו'. והענין הוא דהנה כתי' ונהר יחרב ויבש<sup data-n=\"1279\">14</sup>, וארז\"ל יחרב בב\"ר ויבש בב\"ש, ונהר יחרב קאי על בחי' ונהר יוצא מעדן, ובחורבן ב\"ר יחרב ובב\"ש יבש. וההפרש הוא היינו שבב\"ר אעפ\"י שנחרב מ\"מ יש בו מעט מים, וכמ\"ש בנח והנה חרבו המים מעל הארץ ואח\"כ נא' יבשה הארץ, ופירש\"י שם חרבה שלא נתיבשו לגמרי ואח\"כ יבשה הארץ שנתיבשה לגמרי כו', וזהו מ\"ש על נהר כבר דהיינו שכבר הי' בו מים, ומ\"מ גם עתה יש בו מעט מים. אך כ\"ז הי' ב[חורבן] ב\"ר, ולזה הי' שם נבואה יחזקאל חגי זכרי' מלאכי, משא\"כ בב\"ש נא' ויבש שנתייבש הנהר לגמרי, וזהו ענין רי\"ש בחי' דלי דלות. אך בחי' אחש ורש שבחי' אחש שהוא בחי' דמה לך דודי לצבי נמשך גם בבחי' רי\"ש כנ\"ל. וזהו שאסתר נישאת לאחשורש, לפי שאסתר שהוא בחי' הסתר אסתיר פני דהיינו ירידת השכינה בגלות מקבל מבחי' זו מאחשורש כנ\"ל.\n<b>אך</b> לפי\"ז שאחשורש הוא בחי' עליונה מאד בקדושה, א\"כ י\"ל מה שנא' אחר הדברים האלה גדל כו' את המן כו'. אך הענין הוא דהנה איתא ברבות שהראו לאברהם בברית בין הבתרים את כל הגליות שיגלו ישראל, ולכך נק' בין הבתרים ע\"ש הרי בתר שהראו לו את בחי' הגליות כו'. ופי' שם ברבות אימה זו מצרים, חשיכה זו בבל, גדולה זו מדי ע\"ש גדל המלך כו'. וצ\"ל איך מרומז גלות מדי בשם גדולה. אך הענין הוא דהנה עשו נק' בנה הגדול, והיינו לפי שעשו הוא מקבל מבחי' גדול, דהנה ידוע שקליפה קדמה לפרי וכמו קש ותבן שנגדלים מתחלה ואח\"כ נגמר הפרי, והיינו לפי ששרש הקליפה הוא מבחי' עולם התהו שקדם לתיקון, רק שנפלו בשבירה. וזהו שנק' עשו בנה הגדול שמקבל מבחי' גדול דהיינו מבחי' עולם התהו שהוא בחי' גדל חסד, ולכך נמשך להם השפעה שלא לפ\"ע, לפי שהם מקבלים מבחי' גדל חסד ששם כחשיכה כאורה שוין. משא\"כ יעקב נק' בנה הקטן מי יקום יעקב כי קטן הוא, לפי שיעקב מקבל מבחי' עולם התיקון שהוא הכל עפ\"י צמצום ורצון של תומ\"צ שנתצמצם הרצון כו'. וזהו שגלות מדי נק' בשם גדולה, לפי שהם מקבלים מבחי' גדול בחי' וגדל חסד כו'. אך הנה בחי' גדולה זו מה שמקבלים מבחי' וגדל חסד זהו לרעתם, ויש ברבות משל לזה, משל לבעה\"ב א' שהי' לו חמורה וסייחא וחזירתא, לחמורה וסייחא נתן להם מאכל במדה, ולחזירתא נתן שלא במדה, אמרה סייחא לחמורה וכי לאו שוטה בעה\"ב שאנו שעושין מלאכה נותן לנו במדה, ולחזירתא שאינה עושה כלום נותן שלא במדה, אמרה חמורה לסייחא מה שהוא נותן",[["1278","13","<b>מחצית השקל הוא בחי' יו\"ד וכמ\"ש בזהר. . דא יו\"ד</b>: נת' בארוכה במאמרי אדה\"ז תקס\"ג ח\"ע ע' קצא ואילך. ריא ואילך. ביאוה\"ז להצ\"צ ח\"א ע' ערה ואילך. וש\"נ. ח\"ב ע' תתכט ואילך. ד\"ה פקודא ליתן מחצה\"ש תשכ\"ג. וש\"נ."],["1279","14","<b>והענין הוא דהנה כתי' ונהר יחרב ויבש</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380362\" data-slug=\"likkutei-torah\" data-id=\"4001380362\">לקו\"ת במדבר יג, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640130\" data-slug=\"or-hatorah-hb\" data-id=\"8316640130\">אוה\"ת ואתחנן ע' תכז</a>. שה\"ש (כרך א) ע' קל. סה\"מ תרכ\"ט ע' רצה."]]],[2000460445,"לה שלא במדה זהו לרעתה למחר יבא כלנדס והוא נוחר אותה. וכך עד\"מ יובן בנמשל שנש\"י נק' חמור ע\"ש יששכר חמור גרם, והיינו שאנו מקבלים עול מלכותו כשור לעול וכחמור למשא, ועשו נק' בשם חזיר וכמ\"ש יכרסמנה חזיר מיער. והנה נש\"י מקבלים במדה שהם מקבלים עפ\"י חכ' שהוא בבחי' מדה, וכמ\"ש ארוכה מארץ מדה, אבל אעפי\"כ יש בה בחי' מדה, וחזירתא מקבל שלא במדה שהם מקבלים ההשפעה שלא לפי\"ע כלל, אך זהו לרעתם, כי עי\"ז נתמלא סאתם מהרה ויכלו במהרה כו'.\n<b>וזהו</b> שגדל המלך אחשורש את המן כדי שיהי' מפלתו במהרה. וזהו שמפסוק אחר הדברים האלה עד מפלת המן יש ע' פסוקים, וכן עד מפלת נחש יש ג\"כ ע' פסוקים, ואיתא ע\"ז הטעם לפי שנחש והמן נידונו ע\"פ סנהדרי גדולה שהם ע'. ולכך נקראו סנהדרי גדולה, והיינו לפי שהם דנין את הגדולה, עד כמה יומשך הגדולה, וכשנתמלא סאתם אז הם נחתכים מהגדולה כו'. וזהו שגדל אחשורש את המן כדי למהר מפלתו. וזהו שנא' אחר הדברים האלה, דהיינו אחר מעשה בגתן ותרש שזה הי' הרפואה למכה, וכשברא את הרפואה אז אח\"כ גדל אותו כדי למהר מפלתו כו'.\n<b>ועוד</b> י\"ל שלכך גדל אותו כדי שיבואו למס\"נ, שעי\"ז שגדל המלך את המן עי\"ז היו בכל השנה במס\"נ. וזהו ומה ראו על ככה ומה הגיע עליהם, שאפי' בבחי' ככה שהוא בחי' כה כדמותנו וכמו שא' כל הנביאים נתנבאו בכה, וככה מורה על בחי' הסתר יותר, ואעפי\"כ הגיע להם בחי' מ\"ה כו', והיינו לפי שהיו במס\"נ כו'. וזהו וקבל היהודים אשר החלו לעשות, שבזמן מ\"ת הי' רק התחלה, והיינו לפי שבמ\"ת לא הי' הגילוי רק מבחי' כמראה אדם, אבל ע\"י מס\"נ שהי' להם אז נמשך המשכה שלמעלה מבחי' כמראה אדם שהוא בחי' דמה לך דודי לצבי כו'. וזהו רץ כצבי וגבור כארי לעשות רצון אביך שבשמים שעי\"ז נמשך מבחי' דומה דודי לצבי כנ\"ל."],[2000460446,"<h3>הוספה ג </h3><h3>לד\"ה והמשכילים יזהירו - ומעתה נחזור</h3>\n<b></b><b>[לד\"ה והמשכילים יזהירו]</b>\n<b>ומעתה</b> נחזור לעניננו<sup data-n=\"1280\">1</sup> להבין ענין לימוד זה דבהרת איך שייך למעלה בג\"ע. אך הנה מתחלה צ\"ל מה דאיתא בע\"ח שמ\"ח ושמ\"ט פ\"ג שקליפת נוגה דאצי' היא טו\"ר חציה טוב וחציה כלפי חוץ רע. דלכאורה אין זה מובן כלל איך שייך כלל לומר קליפת נוגה דאצילות הלא נודע פי' אצי' שהוא בחי' אלקות כמבואר במ\"א שהוא מלשון ויאצל מן הרוח<sup data-n=\"1281\">2</sup> דגבי משה. וא\"כ איך שייך לומר קליפות דאצי'. ומכ\"ש ענין חציה רע. [והנה לפ\"ד שאר המקובלים לא יקשה כלל, כי אומרים שלנגד ד' עולמות אבי\"ע יש לעומ\"ז ד' קליפות ג\"ק הטמאות לגמרי הם כנגד בי\"ע, וק\"נ היא כנגד עולם האצי', ולא שק\"נ היא ג\"כ אצי' אלא שהיא כנגד אצי' אבל אינה אצי' כלל, רק שהיא לעו\"ז דאצי', וכמ\"ש בתניא שהקלי' נחלקים לב' בחי'<sup data-n=\"1282\">3</sup> הם גק\"ה וק\"נ, לכן לא יקשה עליהם כלל איך שייך לומר ק\"נ דאצי' שלפי פי' אין ר\"ל שהיא אצי' רק שהיא נגד האצי' כנ\"ל, אך לפי' מ\"ש בע\"ח ל' ק\"נ דאצי' צ\"ל איך שייך קלי' באצי' כו']. עוד צ\"ל מה דאיתא בזהר ובע\"ח שער לאה ורחל פ\"ז. שסיבת הנגעים הוא מחמת הסתלקות אור אבא, וזהו דתרגום צרעת סגירותא שכאשר נעלם ונסגר אור אבא ואינו מאיר בז\"א אז נמשך ובא בחי' הנגע. ולכן נאמר והובא אל הכהן כי כהן שרשו מחכמה שתיקון הנגע הוא ע\"י שממשיכים בחי' אור אבא וזהו ע\"י הכהן (וע' בזח\"א בראשית ל\"א א' ע\"פ לעומת המסגרת. דא הוא אתר סגיר דלא פתיחא היינו חכ\"ע שנק' עדן עין לא ראתה, בר בשביל חד דקיק פי' בסה\"מ סי' קט\"ז דהיינו יסוד דאבא דאתיידע בגניזו לגביה דהיינו שמאיר בבינה ובזו\"נ, וכמ\"ש בע\"ח שמ\"ז פ\"ג בפי' כולם בחכמה עשית, כי באצילות אור א\"ס מתלבש בחכמה ועל ידו מאיר בכל האצי' כו'. אכן פי' סגירותא היינו שנסגר אור אבא לגמרי ואינו מאיר גם ע\"י שביל דקיק הנ\"ל, וע\"ד מש\"ש בע\"ח שהבריאה אינה מקבלת רק מהבינה לבד כו' ע\"ש, וכשנסגר אור אבא עד\"ז מבחי' ז\"א דאצי' מזה נמשך בחי' הנגע, ועיין במא\"א",[["1280","1","<b>ומעתה נחזור לעניננו</b>: הוא השלמת המאמר לד\"ה והמשכילים יזהירו שנדפס לעיל ע' קנח, ונדפס כאן מגוכי\"ק כ\"ק אדמו\"ר מהר\"ש כת\"י 1077 רעט, ב ואילך [הכולל הנחות כ\"ק אדמו\"ר מהר\"ש ממאמרי הצ\"צ] בהמשך לד\"ה והמשכילים יזהירו שם רעח, א ואילך. והוא הגהות לד\"ה קא מיפלגי במתיבתא דרקיע ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380173\" data-slug=\"likkutei-torah\" data-id=\"4001380173\">לקו\"ת תזריע</a> (פרקים ג-ד) כג, ב ואילך. [ד\"ה והמשכילים יזהירו דלעיל הוא מיוסד והגהות למאמר הלקו\"ת פרקים א-ב, וכאן נוספו עוד הגהות לפרקים ג-ד]. — חלקו הראשון ממאמר הלקו\"ת תזריע (עד פיסקא: ועפ\"ז יובן ג\"כ מש\"ל בשם הזהר) נמצא בשינויים בסה\"מ תרל\"ב ח\"ב ע' תנד ואילך."],["1281","2","<b>כמבואר במ\"א שהוא מלשון ויאצל מן הרוח</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370010\" data-slug=\"torah-or\" data-id=\"3901370010\">תו\"א בראשית ג, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370063\" data-slug=\"torah-or\" data-id=\"3901370063\">וירא יד, א</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' רצב ואילך. אוה\"ת ואתחנן ע' קפו ואילך. סה\"מ תרל\"ב ח\"א ע' מב. רד. ועוד."],["1282","3","<b>וכמ\"ש ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא</a> שהקלי' נחלקים לב' בחי'</b>: פרקים ו-ז."]]],[2000460447,"אות נו\"ן סעיף ז'. והתיקון לזה הוא ע\"י הכהן י\"ל ע\"ד מ\"ש בזח\"ב יתרו ס\"ז ב' שהכהן משמש וממשיך מבחי' קדש הקדשים שהם ג\"ר כח\"ב ובפ' עקב דף רע\"א סע\"א גבי ברוך אתה אתה כהן לעולם שבחי' הכהן הנק' אתה ממשיך מבחי' ברוך חכמה עילאה כו' ועיין עוד בפ' בלק דקצ\"ג ע\"ב). אבל כאשר נסגר ונעלם אור אבא שהוא בחי' חכמה עילאה אזי אע\"פ שיאיר אור הבינה בז\"א עכ\"ז יכול להיות התהוות הנגעים (כי בינה דינין מתערין מינה יען שהוא מקור ליש כו') וגם זה לכאורה תמוה איך יכול להיות שאע\"פ שיאיר אור הבינה אעפ\"כ יוכל להיות הנגע.\n<b>ונקדים</b> מ\"ש בע\"ח דשם אל בחסד ושם אלקים בגבורה ושם הוי' בתפארת<sup data-n=\"1283\">4</sup> והרי שם הוי' הוא ראשון וגדול מכל השמות ולמה תפארת שהוא שלישי בסדר המשכת המדות עליונות שסדרן חג\"ת הנה הוא נק' בשם עליון וגבוה מספירת חסד שהוא ראשון בהמדות. [וקושיא זו צ\"ל ג\"כ על המד\"ר פ' בחוקותי פל\"ו ע\"פ כה אמר ה' לבית יעקב אשר פדה את אברהם משל לא'<sup data-n=\"1284\">5</sup> שהי' נידון לפני השלטון יצא דינו לשרוף צפה השלטון באיצטרוגלין שלו שעתיד להוליד בת שנשאת למלך, אמר כדאי הוא להנצל בזכות בתו כך אברהם יצא דינו מלפני נמרוד לשרוף צפה הקב\"ה שעתיד יעקב לצאת ממנו אמר כדאי הוא להנצל בזכות יעקב, וז\"ש לבית יעקב אשר פדה את אברהם, אשר גם לפ\"ד המד\"ר זה צ\"ל ג\"כ קושי' הנ\"ל שיעקב הוא שלישי לאבות, והוא הי' הגדול שבהם שאברהם ניצול בזכותו דוקא].\n<b>ותירץ</b> ע\"ז המגיד זצוק\"ל<sup data-n=\"1285\">6</sup> כי הלא ידוע שענין שבה\"כ שהיה בעולם התהו הוא מחמת שהיה כל מדה בפני עצמה ולא היה התכללות המדות זה עם זה, וענין עולם התיקון הוא שנעשה התכללות המדות שזה צריך לזה חסד כלול עם גבורה וגבורה עם חסד, וע\"י מה נעשה ההתכללות שהרי התכללות זו הוא ענין חיבור ב' הפכים חו\"ג אש ומים, הנה זהו ע\"י הארת אור א\"ס המאיר בהן שעי\"ז הם בבחי' ביטול לאור א\"ס ב\"ה המאיר בהן ועי\"ז יוכלו להתחבר יחדיו. וזהו ענין עושה שלום במרומיו והיינו שלא תהיה כל מדה בתגבורת עד שלא תוכל להתחבר עם מדה שכנגדה כמו שהיה בעולם התהו כ\"א שתתכלל ג\"כ עם הפכה מחמת הביטול כו'. והנה עם היות כי מדות חו\"ג דאצי' מאיר בהן אור א\"ס ב\"ה כי איהו וגרמוהי חד אעפ\"כ נק' כל מדה בשם בפ\"ע, היינו זה בחי' חסד ולכן הוא שם אל כדכתיב חסד אל כל היום, וזה הוא בחי' גבורה ונק' שם אלקים, הרי מ\"מ הם ב' בחי' הפכיים,",[["1283","4","<b>ונקדים מ\"ש בע\"ח. . ושם הוי' בתפארת</b>: בהבא לקמן ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370042\" data-slug=\"torah-or\" data-id=\"3901370042\">תו\"א נח י, סע\"ב</a> ואילך. — הבא לקמן נמצא בשינויים בסה\"מ תר\"ם ח\"א ע' רלא ואילך."],["1284","5","<b>המד\"ר. . ע\"פ. . לבית יעקב אשר פדה את אברהם משל לא'</b>: נת' לקמן ח\"ב ד\"ה בהעלותך את הנרות פ\"ז. וש\"נ."],["1285","6","<b>ותירץ ע\"ז המגיד זצוק\"ל</b>: ראה גם (בשם הה\"מ) בס' מאמרי אדה\"ז אתהלך לאזניא ע' יב. תקס\"ב ח\"ב ע' תמ. תקס\"ג ח\"א ע' נב. ביאוה\"ז לאדהאמ\"צ ח, ג. וראה ס' פלח הרמון שמות ע' רסא. וראה אגה\"ק סי\"ב (קיז, א). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560401\" data-slug=\"or-hatorah-hb\" data-id=\"8316560401\">אוה\"ת בראשית (כרך ג) תרסז, א</a>. סה\"מ תרל\"ג ח\"ב ע' תקה. ס\"ע תקלד-ה. תר\"ם ח\"א שם ע' רלא. ועוד."]]],[2000460448,"והיינו משום דכאשר מאיר אור א\"ס ב\"ה בהמדות עליונות בבחי' גילוי רב אזי דוקא נעשה ההתכללות ויחוד המדות להיות לאחדים ממש. וזהו פי' הוי' אחד שהוא ענין להיות יחוד המדות ממש<sup data-n=\"1286\">7</sup> שלא יהיו ענפין מתפרדין, והיינו ע\"י המשכת אור א\"ס ב\"ה בהם דלאו מכל אינון מדות איהו כלל כי החי\"ת מורה על ז' רקיעים והארץ שהוא בחי' מעלה ומטה, והד' הוא ד' רוחות העולם מזרח מערב צפון ודרום והיינו בחי' ששה קצוות ששרשן מששה מדות עליונות, וע\"י גילוי אור א\"ס ב\"ה בהן שזהו ענין אל\"ף אלופו של עולם מתייחדי' באחד ממש. אמנם כאשר אין מאיר בהן א\"ס ב\"ה בגילוי רב רק כפי בחי' האור השייך להמדה ההיא בפרט אזי הן המדות חסד בחי' בפ\"ע וגבורה בפ\"ע. רק כאשר נצרך שיהיה התכללות אז מאיר בהן אור א\"ס בגילוי רב יותר מכפי מדתם ועי\"ז תוכלל המדה בהפכה להיות לאחדים ממש נמצא אור א\"ס ב\"ה אין מאיר בהם בתמידות (ר\"ל בגילוי רב) רק לפרקים בעת רצון כאשר נצרך שיתכללו זה בזה ביחוד גמור. [וע\"פ לשון המקובלים הראשונים (הוא העה\"ק) הוא כי יש במידות ב' בחי', כי אוא\"ס הוא שלימותא דכולא ואם אתה אומר שהוא בבחי' בבע\"ג ולא נמצא בו כח הגבול אתה מחסר שלימותו, והמדות דאצי' הם בבחי' גבול, וע\"ד המאמר שיעור קומה של יוצר בראשית רל\"ו אלפי' רבבות פרסאות, ואין הפי' פרסה מדת פרסה כ\"א פרסה היא מדריגה ועכ\"פ רל\"ו אלפי' כו' הם בבחי' מדה וגבול כו'. ונבראו מהמדות לפי שגם המדות הם שורש ומקור הגבול, וזהו מצד המדות כמו שנמשך מהם למטה, אבל מצד היות המדות בטלים לאוא\"ס הם בלי מהות ומדה כלל, והם בבע\"ג כו'].\n<b>והנה</b> יחוד והתכללות זו בין המדות חו\"ג הוא ע\"י התפארת שמדתו הוא שהוא ממוצע בין חו\"ג והוא בחי' התכללות ובו הוא שנמשך ומאיר ההארה מא\"ס ב\"ה בגילוי רב וכמשנ\"ת למעלה דת\"ת נק' קדוש ע\"ש שנמשך בו מבחי' כתר שהוא למעלה מסדר ההשתלשלות (וע' באג\"ה בד\"ה והיה מעשה הצדקה שלום<sup data-n=\"1287\">8</sup> ובזח\"ב תרומה קע\"ה ב' ע\"פ והבריח התיכון) וע\"י גילוי זה נעשה התכללות ההפכיים דהיינו שהוא המחבר חו\"ג וממשיך בהם גילוי זה. ונמצא א\"כ מאחר שכל בחי' ומהות מדת התפארת הוא ענין התכללות המדות ביחוד גמור ממש מוכרח שיהיה בו הארת אור א\"ס בתמידות מאחר שזהו מדת ת\"ת היינו ההתכללות (ועי' בהרמ\"ז פ' יתרו בדף ע\"ח והנה בכל תפארת יש כללות חו\"ג כאחד כו'), וההתכללות אין יכול להיות בלתי הארת אור א\"ס ולכן נק' תפארת בשם עליון וגבוה מכל המדות היינו שם הוי' מאחר שמוכרח שיהיה בו גילוי אור א\"ס בתמידות (ועמ\"ש בד\"ה החלצו<sup data-n=\"1288\">9</sup>) משא\"כ בחו\"ג שאין בהם הארת אור א\"ס עד\"ז שבת\"ת רק בעת שנמשך היחוד שזהו ענין אמליכתיה למעלה ולמטה ולד' רוחות שאזי נעשה התכללות המדות שיתכללו זב\"ז ביחוד גמור ולא בתמידות כנ\"ל:",[["1286","7","<b>וזהו פי' הוי' אחד. . יחוד המדות ממש</b>: ראה בכ\"ז לעיל ד\"ה הללוי' גו' במרומים. וש\"נ."],["1287","8","<b>באג\"ה בד\"ה והי' מעשה הצדקה שלום</b>: אגה\"ק סי' יב (קיז, א)."],["1288","9","<b>ועמ\"ש בד\"ה החלצו)</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380669\" data-slug=\"likkutei-torah\" data-id=\"4001380669\">לקו\"ת מטות פו, ד</a>."]]],[2000460449,"<b>והנה</b> עפ\"ז יובן ענין ק\"נ דאצילות שנק' בשם קליפה הגם שהיא בבחי' אצילות ומאחר שהיא בבחי' אצילות הרי עכצ\"ל שהיא מקבלת הארת אלקות ואעפ\"כ נק' בשם ק\"נ. והענין כי בחי' התכללות שיש בע\"ס דאצילות שמאיר הארת אור א\"ס ועי\"ז הם מתכללים זע\"ז כנ\"ל זו הבחינה אינה כלל בנוגה דאצילות. אלא שהמדות שבק\"נ דאצי' הם ענפין מתפרדין שהחסד אינו מתכלל עם הגבורה ואינן מתייחדין כלל זה עם זה. וכנודע שהפסולת משבה\"כ דעולם התהו נפל בק\"נ וראשיתם ק\"נ דאצילות, והרי בעולם התהו לא היה בחי' התכללות וכ\"ש אחר שבה\"כ כו'. ולכן אין אור א\"ס נמשך ומתלבש בהן כלל ע\"ד התלבשותו באצי' דקדושה מחמת שאינן כלי לגילוי אור א\"ס שאינו שורה אלא במקום הביטול ובמקום ההתכללות כו' רק שהוא מאיר עליהם בבחי' מקיף לבד וכמ\"ש במ\"א ע\"פ ראה ריח בני<sup data-n=\"1289\">10</sup> כו', וע\"כ נקראו קליפות שהקליפה היא שאין לה טעם ולחלוחית כו' כמו בהפרי (וי\"ל כי שם מ\"ה נק' שקיו דאילנא בחי' לחלוחית והמשכת אור א\"ס שעי\"ז נעשה התכללות אמיתי' להיות לאחדים עד\"מ טבע המים לדבק שחלקי הקמח נעשים גוש אחד ע\"י המים. וגילוי זה היינו ע\"י שמתחלה הם בבחי' תיקון ע\"ד רך כקנה כו' שעי\"ז אח\"כ קוב\"ה שרי באתר שלים והוא גילוי שם מ\"ה מלגיו דאיהו אורח אצילות ואיהו שקיו דאילנא כו', משא\"כ בק\"נ דאצי' שהוא מבחי' עולם התוהו מבחי' שבה\"כ שאין בהם ההתכללות כלל וגם הביטול הוא בבחי' יש כנודע מענין ראו מ\"ה שעושה יש ודבר מהביטול שלו<sup data-n=\"1290\">11</sup> כו'. ע\"כ אין נמשך בהם כלל בחי' שם מ\"ה מלגיו ולכן נק' קליפות שאין בהם לחלוחית מבחי' שקיו דאילנא כו') ומק\"נ דאצי' נמשך אח\"כ בבי\"ע בחי' יש ממש וצבא השמים כו'.\n<b>ובזה</b> יובן ג\"כ מה דאיתא שק\"נ חצי' טוב וחצי' רע. והענין כנודע שהתהוות הרע הוא מחמת שבה\"כ שהי' בעולם התהו, והשבירה הי' מחמת שהיו ענפין מתפרדין ומזה נתהווה אח\"כ בהשתלשלות בחי' הרע. והנה משבה\"כ דעולם התהו נפלו בנוגה דאצילות, ולכן אף שמקבלת מאצילות וע\"כ חציה דכלפי פנים הוא טוב, אך מחמת שגם בחציה זו אין בה בחי' ההתכללות כלל וממילא אין מאיר בה גילוי אור א\"ס בבחינת פנימי כנ\"ל לכן יכול להיות שחציה כלפי חוץ רע (וכמו שמעולם התהו נתהוו הקליפות כו'. ובזה יובן מארז\"ל ברבות ס\"פ נשא ס\"פ י\"ד ע\"פ ולא קם נביא עוד בישראל כמשה, בישראל לא קם אבל באו\"ה קם כו' זה בלעם בן בעור כו', והנה נבואת משה היה מאצילות, וא\"כ איך באו\"ה קם נביא כמשה. אלא הענין שנבואת בלעם היה מק\"נ דאצילות כו').",[["1289","10","<b>וכמ\"ש במ\"א ע\"פ ראה ריח בני</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370095\" data-slug=\"torah-or\" data-id=\"3901370095\">תו\"א תולדות כ, ג</a>-ד. לעיל ד\"ה ראה ריח בני. וש\"נ."],["1290","11","<b>כנודע מענין ראו מ\"ה שעושה יש ודבר מהביטול שלו</b>: ראה כתר שם טוב (הוצאת קה\"ת) סל\"א. סשט\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380260\" data-slug=\"likkutei-torah\" data-id=\"4001380260\">לקו\"ת בהר מג, א</a>. [ובהנסמן בהמ\"מ לשם]. ביאוה\"ז לאדהאמ\"צ נז, ד. ועוד."]]],[2000460450,"<b>]לענין</b> ק\"נ דאצי', ע' בהגהות על דרוש זה דבהרת (משנת תרט\"ו) מהרקנטי<sup data-n=\"1291\">12</sup> שסובר שגם כלי' דאצי' הם נבראים, ואעפי\"כ נק' אצי'<sup data-n=\"1292\">13</sup>, וכמו שיש נשמות דאצי' ואע\"פ שאינו מאיר בהם הארת הקו, מ\"מ נק' נשמות דאצי', וכמו זקנים דמשה שנא' עלי' ויאצל מן הרוח לשון אצי', עד\"ז יובן שאפ\"ל ק\"נ דאצי' כו'].\n<b>ועפ\"ז</b> יובן ג\"כ מש\"ל בשם הזהר וע\"ח שבהסתלקות אור אבא מז\"א הוא סיבת התהוות הנגע. והענין כי התלבשות אור א\"ס הוא בחכמה דוקא כמ\"ש בסש\"ב פרק ל\"ה בהג\"ה, ולכן כדי שיהי' התכללות גמור בז\"א הוא ע\"י גילוי אור אבא (והגם שהוא ע\"י תפארת היינו כמ\"ש בפע\"ח גבי קדוש דיוצר דפי' שת\"ת הנק' וי\"ו עולה ומקבל הארה מחכמה עילאה הנק' קדש ועי\"ז נק' קדוש. ועמ\"ש מזה בביאור ע\"פ ונקדשתי בתוך בנ\"י<sup data-n=\"1293\">14</sup> בפ' אמור. והגם דלעיל אמרנו דקדוש נק' הת\"ת ע\"ש שמקבל מבחי' כתר היינו כי אור הכתר מאיר באצי' ע\"י חכמה עילאה כמ\"ש בע\"ח דאור א\"ס מתלבש באצי' בחכמה לבדו כו'), ולכן כאשר מאיר אור אבא שבו מלובש אור א\"ס ב\"ה ועי\"ז נעשה ההתכללות ויחוד ע\"ס דאצי' אזי עי\"ז לא תוכל קליפת נוגה דאצי' להיות לה יניקה מבחי' עור אדם העליון דהיינו בחי' ז\"א, לפי שבה אין מאיר שום הארת אור א\"ס שיתכללו יחד כי שרש נוגה הוא משבה\"כ מעולם התהו שאין בה התכללות. אמנם בהסתלקות אור אבא מז\"א ואזי לא יש בחי' התכללות במדות דאצילות וכנ\"ל שעיקר ההתכללות הוא ע\"י הארת אור א\"ס שמאיר ע\"י החכמה. ואזי מחמת שאין בה התכללות זו אזי יוכל להיות יניקה לק\"נ דאצי' מעור המל' או מז\"א. וזהו ענין הנגע שהוא מה שיונקים ק\"נ דאצילות יניקה מעור זו\"נ דאצילות. ולכן התיקון לזה הוא והובא אל הכהן שהוא המשכת אור אבא שהוא דוחה החיצונים והיינו שלא יהיה יניקת הקליפות רק משערות דנוק' ולא מהעור עצמו. והנה הנגע הוא בהרת לבנה ועד\"מ למטה באדם הוא ענין הסתלקות הדם מאותו מקום כי הדם הוא הנפש. ועמ\"ש בביאור בשעה שהקדימו<sup data-n=\"1294\">15</sup> נעשה ובד\"ה לסוסתי<sup data-n=\"1295\">16</sup>. וכך למעלה בחי' החכמה תחיה והוא בחי' אדם א' דם ובהסתלקות אור אבא הוא ענין הסתלקות בחי' והחכמה תחי' מאותו בחי' עור. וזהו ענין הבהרת. ועמ\"ש מזה ג\"כ סד\"ה ביום השמע\"צ<sup data-n=\"1296\">17</sup> שהבהרת הוא ענין שמעכב ההשפעה והמשכת החיות, וע' במא\"א אות ב' ס\"ח. ואח\"כ כשיש שער לבן יונקי' ק\"נ מהעור ע\"י השער לבן כו' ולכן צריך הסגר (ופי' וענין עור יובן ע\"ד שנת' למעלה בענין פי' קשר של תפילין למעלה שהוא מבחי' עור כו'. ועד\"ז יובן גם כאן פי' וענין יניקת ק\"נ דאצילות מעור",[["1291","12","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080350\" data-slug=\"or-hatorah-hb\" data-id=\"8160080350\">ע' בהגהות</a> על דרוש זה דבהרת (משנת תרט\"ו) מהרקנטי</b>: אוה\"ת ויקרא (כרך א) ע' שנ. שם (כרך ב) ע' תקל. הובא בסה\"מ תרל\"ב ח\"ב ע' תנו."],["1292","13","<b>מהרקנטי שסובר שגם כלי' דאצי' הם נבראים ואעפ\"כ נק' אצי'</b>: ראה גם אוה\"ת ענינים ע' רנח ואילך. [ובהנסמן שם בהמ\"מ בתחילת המאמר]."],["1293","14","<b>ועמ\"ש מזה בביאור ע\"פ ונקדשתי בתוך בנ\"י</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380219\" data-slug=\"likkutei-torah\" data-id=\"4001380219\">לקו\"ת אמור לג, סע\"ב</a> ואילך."],["1294","15","<b>ועמ\"ש בביאור בשעה שהקדימו</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380366\" data-slug=\"likkutei-torah\" data-id=\"4001380366\">לקו\"ת במדבר יד, ג</a>. ובארוכה סה\"מ תרכ\"ט ס\"ע רצ ואילך. וש\"נ."],["1295","16","<b>ובד\"ה לסוסתי</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381175\" data-slug=\"likkutei-torah\" data-id=\"4001381175\">לקו\"ת שה\"ש יא, רע\"ג</a>."],["1296","17","<b>ועמ\"ש. . סד\"ה ביום השמע\"צ</b>: לקו\"ת דרושים לשמע\"צ פו, א."]]],[2000460451,"דז\"א. ועיין בע\"ח בדרוש הנגעים שם ולכן תמורת ג' אורות אשר יוצאין ומתקנין את לאה ורחל כו' ואל תתמה בזה כי הנגע אינו טומאה בעצמה רק בחי' דינא קשיא כו' ע\"ש, והיינו שמהנגע נמשך אח\"כ יניקה לק\"נ דאצילות כו' וזהו הטומאה כשמטמאים הנגע ועיין בהרמ\"ז ס\"פ תזריע).\n<b>ובזה</b> יובן ענין אם שער לבן קודם לבהרת טהור, כי כך הוא הדבר שיש יניקה לק\"נ דאצי' משערות דנוק' כי מאחר שהקב\"ה ברא אותן ממילא מוכרח להיות להם יניקה והיינו מבחי' השפעה אחרונה דאצי', דהיינו בחי' שערות שהן גדילי' מהעור והשערות הוא בחי' היותר אחרונה ולמטה מטה מהעור שהרי מהעור יצא דם ע\"י נקב (וא\"כ מלובש בו עצמיות האור והחיות מבחי' ח\"ע המלובש בהדם ועיין בלק\"ת פ' וירא גבי ענין הדפק כו') משא\"כ השערות, ולכן מהשערות ניתן להם יניקה, וכיון ששער לבן קדמה לבהרת אין להם יניקה בהעור רק מהשערות ולכן הוא טהור. אבל אם בהרת קדמה לשער לבן היינו שיש יניקה לנוגה דאצי' מעור הנוק', כי תרגום צרעת סגירו, סגירו דנהורא שהן מוחין דאבא שלא נתגלו בזו\"נ. וזהו ענין הבהרת שהיא המעכבת סיבוב והילוך והתפשטות הנפש והחיות במקום זה. וברוחניות למעלה זהו ענין עיכוב ומניעת התגלות המוחין דאבא כו', וכן ענין כל הד' מראות נגעים. ולכן כשהבהרת קדמה לשער לבן אזי יונק ק\"נ דאצי' מעצמיות עור הנוק' ע\"י השער לבן כו' שהיניקה נק' ע\"ש שער לבן (כי זה לעומ\"ז עשה וכנודע מענין לבן ויעקב שיש לובן העליון בקדושה<sup data-n=\"1297\">18</sup> בגדי לבן ושער רישי' כעמר נקא. ולעומת זה ג\"כ לבן דקליפה כו' וכמ\"ש בפרדס ש\"ג פ\"ז וכמ\"ש ג\"כ במ\"א ע\"פ עד הגל כו'<sup data-n=\"1298\">19</sup>). והנה מק\"נ דאצי' נמשך אח\"כ גם בעשיי' ששם הם עומקי הקליפות. ולכן אם בהרת קודמת לשער לבן הוא טמא וצריך תיקון ע\"י הסגר כו'.\n<b>ספק</b> קוב\"ה אמר טהור, וכולהו מתיבתא דרקיע אמרי טמא. כי ע\"פ ההשגה של המתיבתא הרי כך הוא דין תורה דכל ספיקא דאורייתא לחומרא. אבל הקב\"ה אמר טהור היינו שכאן אין מטמא אא\"כ ודאי הבהרת קדמה אבל אם הוא ספק שאין נודע לנו אם הבהרת קדמה טהור הוא. אף שיוכל להיות שהבהרת קדמה מ\"מ כאן הוא גזה\"כ שכל שהוא ספק אצלנו ולא נודע לנו שהבהרת קדמה אינו טמא. והיינו או משום שכל שלא נודע שהבהרת קדמה אין נמשך להם יניקה יותר מהראוי או שלא יהיה מיניקה זו התעוררות דינים [והיינו כי ספק זה בידיעה תלי' מלתא, ואפ\"ל כי שבה\"כ הי' מן הדעת ולמטה, כי ימותו ולא בחכ' שבחכ' לא הי' שבה\"כ וגם בבינה לא הי' השבירה כ\"א מהדעת ולמטה, ולכן כל שלא נודע היינו שלא בא בבחי' דעת לא נמשך יניקה לקליפ' כו', לכן הספק שלא נודע אם הבהרת קדמה או השער לבן ספיקו טהור כו', ואינו דומה ספק זה דבהרת לספק איסור (שנמשך ג\"כ משבה\"כ) ע\"ד שארז\"ל אם אמרו בספק טומאה יאמרו בספק איסור כו', וגם כי ד'",[["1297","18","<b>וכנודע מענין לבן ויעקב שיש לובן העליון בקדושה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370107\" data-slug=\"torah-or\" data-id=\"3901370107\">תו\"א ויצא כג, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">כד, ב</a>."],["1298","19","<b>וכמ\"ש ג\"כ במ\"א ע\"פ עד הגל כו'</b>: סידור עם דא\"ח דש ג, ואילך."]]],[2000460452,"מראות נגעים רומזים לד' גליות כמשרז\"ל במד\"ר שאת זו בבל כו', וספק זה כבר נפשט לקולא כמשארז\"ל במד\"ר סוף איכה ע\"פ אם מאוס מאסתנו, אם מאיסה לית סבר אם קציפה אית סבר, וכבר נפסק שיש סבר יעו\"ש, לכן ספק זה דבהרת ספיקו טהור]. (ויש למצוא קצת טעם לזה בהא דבידיעה תליא מילתא בספק זה שבטומאת צרעת, והוא ע\"פ מ\"ש הרמ\"ז ס\"פ תזריע וז\"ל והבן ענין גדול שאין טומאת הצרעת ככל שאר טומאות שזו אין טומאתה נודעת ולא מטמאה עד שיבוא הכהן כנודע כו' עכ\"ל. וע\"ש הטעם ע\"פ הע\"ח. וא\"כ הרי אפי' בצרעת שהיא ראויה להיות ודאי טמא עכ\"ז גזה\"כ הוא שאינה מטמא עד שיבוא הכהן ויוודע טומאתה מהכהן כו', לכן שפיר י\"ל הטעם דספק זה טהור משום דכל שהוא ספק ולא נודע שהבהרת קדמה טהור), וכה\"ג הוא ענין ספק ממזר דארז\"ל ממזר ודאי לא יבא אבל ספק ממזר כשר מדאורייתא לבוא בקהל."],[2000460453,"<h3>הוספה ד </h3><h3>והמשכילים יזהירו - ביאור מהרה\"ח הרד\"צ חן ע\"ה</h3>\n<b></b><b>ביאור לד\"ה והמשכילים יזהירו<sup data-n=\"1299\">1</sup> תרל\"ט</b>\n<b></b><b>— מהרה\"ג הרה\"ח הרד\"צ ע\"ה חן — </b>\n<b>והמשכילים</b> יזהירו כזהר הרקיע ומצדיקי הרבים ככוכבים ואמרז\"ל זה הדן דין אמת לאמיתו וגבאי צדקה, וצ\"ל מה שייך הדן דין אמת לאמיתו וגבאי צדקה להמשכילים, ומהו יזהירו.\n<b>והנה</b> להבין ענין הרקיע צ\"ל ענין מתיבתא דרקיע דמצינו בגמ' קא מפלגי במתיבתא דרקיע בהרת כו', ספק הקב\"ה אומר טהור וכולהו מתיבתא דרקיע אמרי טמא, מאן נוכח רבה בר נחמני כו' טהור טהור ובמ\"א אי' שמצא זה בתורה<sup data-n=\"1300\">2</sup> לטהרו כו', והנה צ\"ל מאחר דהקב\"ה אומר טהור איך שייך דמתיבתא דרקיע יאמרו טמא, וגם מהו\"ע מאן נוכח רבה בר נחמני, הגם דמצינו שארז\"ל דאין משגיחין בבת קול היינו כשאומרים למעלה על למטה אין משגיחין, דתורה שלמטה הוא לברר ברורים ואם רצון ה' כך הי' מוצא זה בתורה הנגלית, אבל שישאלו למעלה איך פוסקין למטה זה לא מצינו כלל, דלמעלה אינו שייך ברורים דתורה שלמעלה נק' עה\"ח ושלמטה עה\"ד, וכ\"ז במקום בת קול אבל כשהקב\"ה אומר טהור אינו שייך כ\"ז ואיך אומרים טמא. והנה צ\"ל מה שמצינו שתנאים ואמוראים עשו מופתים שיוצאים מדרכי הטבע לגמרי וכמו רפב\"י א' גנאי כו' שזה הי' נס גבי משה וס' ריבוא ישראל קודם מ\"ת, ועוד אמרו זוטרי דבכו כו', שזה לא מצינו אפי' אחר מ\"ת רק גבי ג' נביאים גדולים אליהו אלישע יחזקאל ואצלם לא הי' זה בדרך נס, וצ\"ל דאחר מ\"ת לא הי' נס כלל ענין קרי\"ס ונסים של הנביאים הנ\"ל זה הי' ע\"י תושב\"כ לכן הי' זה נס, אבל בתושבע\"פ גם זה אינו נס.",[["1299","1","<b>והמשכילים יזהירו</b>: הוא ביאור לחלק מד\"ה והמשכילים יזהירו הנדפס לעיל ע' קנח ואילך. — ביאור זה הוא מהרה\"ג הרה\"ח ר' דוד צבי ע\"ה חן (המכונה בשם: רד\"צ) אבדק\"ק טשערניגאוו<sup data-n=\"e28\">*</sup>, מגדולי חסידי כ\"ק אדמו\"ר מהר\"ש ואדמו\"ר מוהרש\"ב.\nביאור זה נעתק ע\"י כ\"ק אדמו\"ר מוהרש\"ב בספר ההנחות שלו משנת תרל\"ט (גוכי\"ק מס. 1260 צח, ב ואילך). — ולע\"ע לא נתברר אם נרשם ע\"י הרד\"צ ונעתק ע\"י כ\"ק אדמו\"ר מוהרש\"ב, או שכ\"ק אדמו\"ר מוהרש\"ב רשם את הביאור ששמע מן הרד\"צ. ברשימה זו נרשם לקמן (בין חצאי עיגול): ”איני זוכר אם הוא כן\", ”איני זוכר בבירור\", ויל\"ע אם חצאי עיגול אלו נרשמו ע\"י כ\"ק אדמו\"ר מוהרש\"ב, או שהרד\"צ כשביאור את המאמר הסתפק בהמבואר בזה בדא\"ח."],["1300","2","<b>ובמ\"א אי' שמצא זה בתורה</b>: ראה נזיר סה, ב (הובא לעיל בהמאמר ע' קנט)."],["e28","*","<b>ראה אודותיו</b>: ספר השיחות תרצ\"א ע' 223. 238. תרצ\"ו-ת\"ש ע' 298. קייץ הש\"ת ע' 49. תש\"ב ע' 92. תש\"ג ע' 43. תש\"ו-תש\"י ע' 425. ?התמים\" חוב' ג' ע' כא [קכז א]. ועוד."]]],[2000460454,"<b>והנה</b> צ\"ל תחילה ענין הקב\"ה, ובזה נבין ענין מתיבתא ומה שהראו מופתים כו', ומזה נבין ענין והמשכילים יזהירו כו'. הנה קדוש הוא קדוש ומובדל דאני הוי' לא שניתי ולא כדמיון הנשמה שמתלבשת בגוף, הגם שעצם הנשמה אינה מתלבשת כ\"א הארה מכל הכחות, מ\"מ כשאין שם עצם אין הזיו מאיר ומאיזה מקרה ומאורע לגוף מתפעל עצם הנפש, אבל למעלה אינו כן דאינו שייך לומר כלל וכלל שאיזה דבר מלביש אותו, דאפי' מה שמהווה מאין ואפס המוחלט ליש אינו שייך לומר שהוא מלביש אותו, שהרי כל העולם הוא אין ואפס ואם נחלק אותו לכמה חלקים אינו שייך לומר שמלביש אותו.\n<b>וביאור</b> הענין דהנה אי' בגמ' מה הנשמה ממלא את הגוף אף הקב\"ה ממלא את העולם כו' עד מה הנפש יחידה בגוף אף הקב\"ה יחיד בעולם וכ\"ה בתיקונים, ומהו חידוש הבעש\"ט במשל חיות הנפש שמחי' את הגוף, ומשל זה הוא עיקר החסידות<sup data-n=\"1301\">3</sup> איך שהנפש מחי' את הגוף ומ\"מ לא כדמיון הנשמה המתלבשת בגוף. והענין דהנה צ\"ל מה שאנו רואין שהאדם חי, מי הוא החי אם הנשמה או הגוף, דהנה הנשמה קודם שמתלבשת בגוף היא בודאי חי והגוף לאחר הפרד הנפש ממנו ודאי אינו חי, אך בעת התלבשות הנפש בגוף מי הוא החי. והנה צ\"ל שהנפש הוא חי אלא שקודם התלבשותו בגוף הי' חי בלא גוף ואח\"כ הוא חי בהתלבשות בגוף, ולאחר הפרד הנפש מהגוף הוא מת, וצ\"ל שמסתלק ברגע א' ואינו שייך לומר שמסתלק מעט מעט שהרי ע\"פ דין הגוסס הוא כחי לכל דבר אלא שמסתלק ברגע א'. וכמו\"כ למעלה מ\"ש בתניא שאם הי' מסתלק ממנו הי' הכל אין ואפס<sup data-n=\"1302\">4</sup>, צ\"ל שהי' נסתלק ברגע אחד, ואם ביום א' מברה\"ע הי' מסתלק הי' חוזר הכל לאין ואפס, וכמו\"כ אם לא הי' מהווה הי' הכל אין ואפס וכתי' המחדש בטובו בכל יום כו' שתמיד מחי' ומהווה נבראים בע\"ג ואם לא הי' מחי' ומהווה הי' הכל אין ואפס, וא\"כ כל מציאות העולם הוא אין ואפס ואינו שייך כלל לומר שהוא יש, וכל מה שעין רואה אינו שייך לומר שהוא יש שבאמת הוא אין ואפס, ואם הי' נתנה רשות להעין לראות הי' רואה שהוא אין, אלא שהעין הוא גשמי לכן אינו רואה, ומאחר שכל מציאות העולם הוא אין ואפס אינו שייך לומר שהוא מלביש אותו, אלא שאפי' כח המהווה את העולמות הוא אינו מלובש בתוך העולמות שאינו שייך לומר הלבשה",[["1301","3","<b>חידוש הבעש\"ט במשל חיות הנפש שמחי' את הגוף ומשל זה הוא עיקר החסידות</b>: ראה עד\"ז פלח הרמון שמות ע' עח: וזהו דרך הבעש\"ט והמגיד שהמשיכו בחי' התגלות אוא\"ס בריבוי אופני גילויים מבחי' ומבשרי אחזה שהוא מחיות הנפש בגוף כו' משא\"כ המקובלים דברו בבחי' אור ומאור כו'. וראה גם מאמרי אדה\"ז כתובים ח\"א ע' צא-ב: יש פלוגתא בין הפילוסופים ובין המקובלים, הפילוסופים אומרים שהתהוות העולמות הוא בדרך עילה ועלול כו', אבל המקובלים אומרים שאין שייך לומר עילה ועלול כו' אך הם אומרים שהשתלשלות העולמות הוא בדרך אור וזיו כו', אבל הבעש\"ט והמגיד אומרים שאין שייך לומר בדרך אור וזיו כי א\"כ הוא מוכרח שהעולם הוא קדמון כו' אך השתלשלות העולמות הוא כמו שהנשמה ממלא את הגוף כך הקב\"ה כו'. עיי\"ש."],["1302","4","<b>מ\"ש בתניא שאם הי' מסתלק ממנו הי' הכל אין ואפס</b>: שעהיוה\"א פ\"א (עו, ב ואילך)."]]],[2000460455,"כלל. ובחי' קדוש ומובדל היינו שהוא קדוש ומובדל אפי' מהכח המהווה העולמות, דאמיתית עצמותו הוא קדוש ומובדל אפי' מבחי' זו ג\"כ, ומ\"מ הוא העיקר המחי' נבראים אלא שהוא בדרך מקיף וסובב, דענין סובב למטה הוא כמו אופן שהוא עגול, ובנפש בשכל הוא מה שא\"א להתלבש בכלי מוחו נשאר במקיף, וכמו\"כ בלב הנה אי' בתניא צדיקים גמורים האהבה נתמלאה בחלל הימני עד שנשפך בחלל השמאלי<sup data-n=\"1303\">5</sup>, ומה שייך לומר על אהבה שנשפך והרי א\"ז מים שאפשר להשפך, והפי' הוא שנשאר בדרך מקיף, אבל למעלה אינו כמו כל הנ\"ל שהסובב הוא עיקר המחי' אלא שהוא בהעלם, וזהו שאמר אני מלא והול\"ל אני ממלא או יאמר שהעולם מלא ממני, וכמו שאינו שייך לומר שהמים מלא בהכלי אלא שהכלי מלא ממים ומהו אומרו אני מלא. אלא הפי' שאני מלא בהעולם, אבל אצל העולם הוא בהעלם שאינם מקבלים בחי' זו שהוא קדוש ומובדל.\n<b>ועל</b> ל' קבלה יש ג' מדריגות שנק' קדוש דעת ת\"ת יסוד, שהוא קו האמצעי ובזה יש מלמטלמ\"ע ומלמעלמ\"ט, דעת הוא מלמטלמ\"ע והוא ההתקשרות לבחי' קדוש ומובדל דאני הוי' לא שניתי ומ\"מ יתקשר בבחי' זו, דהמשכה אינו שייך בבחי' זו כ\"א העלאה דכשהנשמה עולה למעלה מכל העולמות אז מתגלה אליו בחי' זו, דבדרך המשכה א\"א להיות בחי' זו אבל בדרך גילוי אפשר להיות, והחילוק בין גילוי להמשכה הוא עד\"מ כשא' מעמיק דעת באיזה השכלה ונופל לו ההשכלה זה המשכה, אבל כשהמוחין זכים וממילא נופל לו ההשכלה זהו גילוי, אבל בחי' ברוך אינו שייך להנשמה כלל שאינו גילוי רק כח ויכולת שיהי' גילוי, ות\"ת יסוד הוא המשכת הקדוש למטה. וברוך הוא בחי' ראש ומקור כל ברכה אין הפי' שממנו נמשך גילוי הברכה אלא שהוא כח ויכולת שיהי' ממנו ברכה, הגם דכתי' ברוך, ה\"ה כמו תיבת רחום או חנון אין פי' שמקבל רחמים אלא שמשפיע רחמים והול\"ל מרחם וכן מצינו שנק' מרחם מ\"מ אומר רחום, ובאמת מרחם מורה שאין עצמותו רחמים אלא שהוא מתרחם עליו לפי שעה, אבל רחום מורה שעצמותו רחם, וזהו שא' ברוך ופי' שהוא הכח והיכולת שיהי' ברכה. וברוך הב' הוא מ\"ש והמלך שלמה ברוך פי' שחכ' תתאה נתברך מח\"ע. והענין דהנה אמרז\"ל מלך שהשלום שלו, מלך הוא התחברות שמחבר ב' דברים<sup data-n=\"1304\">6</sup>, דהנה אנו רואין דמדות המל' אינו דומה לשום מדה כמו אהבה שמחבר האוהב עם הנאהב, וזה שייך כשמכירו שאם האוהב מכיר את הנאהב ויודע שיש לו מוחין ומדות אוהב אותו, ואם אינו מכירו אינו אוהב אותו, וכמו\"כ יראה מחבר הנורא עם הירא ודוקא כשמכירו, אבל מלוכה אף שאינו מכירו ה\"ה מלך עליו, ודוקא כשהוא מרחוק, דעל בנים אינו שייך מלוכה מפני שהוא עצמיות, ואפי' על שרים ג\"כ אינו שייך מלוכה כ\"א דוקא על מי שהוא מרוחק. וגם בכל הדברים אינו שייך הסכם",[["1303","5","<b>אי' ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא</a> צדיקים גמורים האהבה. . שנשפך בחלל השמאלי</b>: ראה פ\"ט (יד, א)."],["1304","6","<b>אמרז\"ל מלך שהשלום שלו מלך הוא התחברות שמחבר ב' דברים</b>: לעיל בהמאמר ע' קס: שארז\"ל מלך שהשלום שלו, פי' שלום שמחבר ב' הפכים. (עיי\"ש)."]]],[2000460456,"דאינו שייך להסכים על א' שהוא חכם ובאמת הוא שוטה, אבל על מלוכה שייך הסכם. וגם באב אינו שייך לבחור שרוצה שזה יהי' אביו, ולא האב אינו יכול לפטור א\"ע מהיות אב, וגם הבן אינו יכול לפטור א\"ע מהיות בן, אבל במלוכה שייך בחירה שכח זה יש בכל אדם, והוא מפני שאנו רואין שהנפש שמתלבש בגוף הוא פנימיות שמתלבש בדרך הלבשה, ושכל הוא שולט על הגוף, דהרי אפשר שעושה המצאה כמו חכם (איני זוכר אם הוא כן) והוא שהמוח הוא מושל ושולט על הגוף, ויש מקיף ששורה על לבושים דוקא, ויש מקיף שא\"א לשרות אפי' על לבושים ג\"כ כ\"א על זולתו דוקא ולכן מלוכה הוא דוקא על זולתו. והנה אנו רואין שמלוכה נוגע בעצמיות יותר מכל דבר דאמרז\"ל אבידתו ואבידת אביו אבידתו קודמת, ואב שמחל על כבודו כבודו מחול, ומלך שמחל על כבודו אין כבודו מחול, וכן על אב אינו מחויב למסור נפשו כ\"א בפרט א' כברא דרחים לי' לאבוהי ואימי' יתיר מגרמי' ונפשו ורוחו ונשמתו, ועל המלך מחויב למסור נפשו, וכן כשא' יאמר איזה שכל ובא חבירו וסותרו לא יהרגנו בשביל זה, אבל מלך אם יבוא א' ויפגע במלכות ה\"ה מורד במלכות ומחויב מיתה, וא\"כ אנו רואין שהוא עצמיות יותר מכולם. וכמו\"כ יובן למעלה במלכות דהבריאה הוא מצד כל יכול וזהו המקיף שמחבר עם נבראים נפרדים (איני זוכר בבירור) וא\"כ צ\"ל מהו\"ע שלום. הענין דהנה שלום הוא שיומשך הביטול דיחו\"ע, אך צ\"ל לזה הביטול היש דאל\"כ אין אני והוא יכולים לדור, דנתאווה הקב\"ה להיות לו דירה<sup data-n=\"1305\">7</sup> בתחתונים, דהנה במדריגה שהוא אין ואפס אינו שייך שם דירה כמו שאינו שייך לומר שהזיו דר בעולם דמאחר שהוא אין ואפס א\"כ אינו שייך דירה.\n<b>ועתה</b> יובן ענין מתיבתא דרקיע דהנה כתי' ועל ראשי החי' רקיע כעין הקרח הנורא, ידוע דיש מרכבתא תתאה ומרכבתא עילאה, מרכבתא תתאה הוא פני ארי' פני שור כו' ומרכבתא עילאה הוא האבות הם המרכבה, דהנה פני ארי' ופני שור הם מדות דבריאה, וראשי החיות היינו חב\"ד של המדות, ורקיע שעליהם הוא מ\"ש מבטן מי יצא הקרח שהרקיע שהוא הקרח הנורא יצא מבטן מי, מי הוא בינה שלצורך עצמו כביכול ולא של המדות, והוא עצמיות הבינה, והקרח שהוא הרקיע הוא הגילוי מבחי' בינה, וכמו\"כ יובן באצי'. אך הנה כאן יש עוד דבר חדש שלא כתי' חיות אלא חיה וצ\"ל שקאי על בחי' מל' שמחי' ומהווה נבראים דעולמות בי\"ע וכמ\"ש ואתה מחי' את כולם, דחיות הוא מה שהוא חי אבל מחי' היינו שמחי' זולתו וא\"כ ראשי החיה הוא בחי' ז\"א שהוא מקור למקור לחיות הנבראים, והרקיע הוא הגילוי דבינה העצמיות, [וכ\"ז במרכבתא תתאה דבי\"ע, אבל מרכ\"ע דאצי' יהי' חי' כתר כו']<sup data-n=\"1306\">8</sup>.",[["1305","7","<b>אינו שייך דירה</b>: בגוכי\"ק כ\"ק אדמו\"ר מוהרש\"ב נרשם כאן ”(חסר)\". וראה המשך הענין לעיל ר\"ע קס."],["1306","8","<b>הגילוי דבינה העצמיות. . כתר כו']</b>: ע\"כ נמצא בגוכי\"ק אדמו\"ר מוהרש\"ב. וראה המשך הענין לעיל ע קס פיסקא: ומעתה יובן ענין המתיבתא דרקיע, ואילך."]]],[2000460457,"<b></b><b>)הבנת המאמר מר' דוד צבי הירש בר' פרץ מטשעארניגאוו). </b>\n<b>הנה</b> יש בחי' קדוש<sup data-n=\"1307\">9</sup> שהוא קדוש ומובדל לגמרי, ויש בחי' קדוש שהוא קדוש ומובדל אך אינו לגמרי (אפ\"ל שר\"ל שבחי' הא' אינו מאיר אפי' בדרך מקיף, ובחי' הב' הוא שמאיר בדרך מקיף וכמ\"ש בפנים). והנה בברוך יש ג\"כ ב' מדריגות, א' ריש ומקור כל ברכה והיינו הכח והיכולת שיהי' ברכה, לא שהוא ברכה בגילוי רק כח ויכולת שיהי' ברכה. והב' והמלך שלמה ברוך שמקבל הברכה. הנה הקדוש הא' שהוא בחי' קדוש ומובדל לגמרי הברוך הוא כפי' הא' ריש ומקור כל ברכה, והקדוש שהוא קדוש ומובדל אך אינו לגמרי הברוך הוא והמלך שלמה ברוך [צ\"ע דבלקו\"ת מפרש שלום הוא ת\"ת וכאן מפרש שהוא מל']<sup data-n=\"1308\">10</sup>. ועל ב' בחי' קדוש א'<sup data-n=\"1309\">11</sup> שהוא דת\"י, דעת הוא התקשרות מלמטלמ\"ע שהוא בחי' קדוש ומובדל לגמרי וא\"א להיות בדרך המשכה רק בדרך העלאה, ות\"ת יסוד הוא המשכה מלמעלה למטה שהוא קדוש ומובדל אך אינו לגמרי ואפשר לימשך למטה בדרך מקיף.\n<b>וזהו</b> הפי' הא' דקב\"ה שבחי' קדוש ומובדל (הב') יומשך בדרך מקיף. הפי' הב' דקדוש ומובדל (הא') יומשך בפנימיות והוא ע\"י תורה. והפי' הג' הוא שיש בחי' קדוש ומובדל שמשם נמשך שיהי' דוקא למקום הראוי והוא מ\"ש ואוהב את יעקב ואת עשו שנאתי, וזהו שקדוש יומשך ע\"י ברוך שיומשך למקום הראוי דוקא.\n<b>ובענין</b> והמשכילים יזהירו כו' י\"ל כך, הנה אור הוא גילוי, והרקיע הוא מעלים על האור, וצ\"ל יזהירו כזהר הרקיע שהאור יאיר ברקיע. עוד י\"ל והמשכילים יזהירו כזהר הרקיע היינו שלא יהיו עננים המסתירים על הרקיע. עוי\"ל לברר ולזכך הרקיע גופא. וזהו שא' בפי' הא' שדן דין אמת לאמיתו, הוא אמיתי' של תורה [הגם דא' תפלה מ\"מ צ\"ל תורה ג\"כ] ממשיכים שהאור יאיר ברקיע. והפי' הב' שע\"י השכלה דתורה ממשיכים מאור שלמעלה מרקיע היינו שלא יהיו עננים המסתירים על הרקיע, הפי' הג' שלא יהי' דין מרומה היינו לברר ולזכך הרקיע גופא, וכמ\"ש [בזהר ע\"י] שמחבבן עי\"ז מזכך את הרקיע גופא, ע\"כ.\n\n<br>",[["1307","9","<b>הנה יש בחי' קדוש</b>: הוא ביאור כללי להמאמר ד\"ה והמשכילים יזהירו הנדפס לעיל ע' קנח ואילך, מאת הרה\"ג הרה\"ח הרד\"צ ע\"ה חן. ביאור זה נעתק ע\"י כ\"ק אדמו\"ר מוהרש\"ב בספר ההנחות שלו משנת תרל\"ט (גוכי\"ק מס' 1260). ובכותרת נרשם בגוכי\"ק אדמו\"ר מוהרש\"ב: ”הבנת המאמר מר' דוד צבי הירש ב\"ר פרץ מטשעארניגאוו\"."],["1308","10","צ\"ע דב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381172\" data-slug=\"likkutei-torah\" data-id=\"4001381172\">לקו\"ת</a> מפרש שלום הוא ת\"ת וכאן מפרש שהוא מל']. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380821\" data-slug=\"likkutei-torah\" data-id=\"4001380821\">לקו\"ת ואתחנן ח, א</a>. שה\"ש י, סע\"ד. וראה לקו\"ת שה\"ש שם שיש כמה בחי' שלום. [אודות הבחי' בשלום ראה גם לקו\"ת ראה כו, ב. אוה\"ת ויגש (כרך ו') תתשי, ב. משפטים ע' א'פא, ושם: שלום זהו ההמשכה פנימי' שנמשך מאא\"ס ב\"ה במדת מל'. ועד\"ז שם ע' א'פט]."],["1309","11","<b>ועל ב' בחי' קדוש א'</b>: אמר (או: איתא).\n<br>"]]],[2002180064,"<h3>מזמור לתודה כו' (א)</h3>\n<b></b><b>בס\"ד. (ש\"פ אמור, ט\"ל).</b>\n<b></b>ד\"ע ד\"ת ל' טבע מחלוקת בין המחקרים כו' ענין הנס\nאמור\n<b>מזמור</b> לתודה<sup data-n=\"1\">1</sup> הריעו לה' כל הארץ, הנה הריעו לה' כל הארץ ר\"ת הלכה<sup data-n=\"2\">2</sup>. וצ\"ל מה שייך ענין הלכה למזמור לתודה. אך הענין הוא, דהנה ארז\"ל (במד\"ר פ' צו פ\"ט) כל הקרבנות בטלים לע\"ל<sup data-n=\"3\">3</sup> חוץ מן התודה כו', וגם אמרו הלכות אינם בטלים לע\"ל לכן הם שייכים זל\"ז. ולכאורה צ\"ל הלא אנו אומרים בתפלת המוסף ושם נעשה לפניך את קרבנות חובותינו, א\"כ יהי' גם שארי קרבנות לע\"ל, ותירצו ע\"ז שקרבנות הצבור לא יבטלו רק קרבנות יחיד, וקרבן תודה הגם שהוא קרבן יחיד אעפ\"כ לא",[["1","1","<b>מזמור לתודה</b>: מאמר זה והמאמר שלאחריו ד\"ה ומעתה כו' הריעו לה' מיוסדים והגהות על ד\"ה זה להצ\"צ מי\"ט כסלו תרי\"ט, הנחה בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש בכת\"י 1077 כד, א ואילך [בכותרת: בס\"ד עם הגהות, כמ\"ש לפני רז\"ך, תרי\"ט]. חלק גדול מההגהות שנוספו כאן ע\"י כ\"ק אדמו\"ר מהר\"ש באים בין חצאי עיגול.\nמאמר הצ\"צ מיוסד על ד\"ה זה לאדה\"ז בסידור עם דא\"ח מד, סע\"א ואילך. ונו\"א בס' מאמרי אדה\"ז על מארז\"ל ס\"ע שנו ואילך. ובארוכה בפירוש המלות לאדהאמ\"צ צ, סע\"ד ואילך (פרקים קלח-קמח). ונמצא בארוכה ובתוס' הגהות ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650247\" data-slug=\"or-hatorah-hb\" data-id=\"8316650247\">אוה\"ת נ\"ך (כרך ב) ע' תתקעו</a> ואילך. וראה עוד הגהות וקיצורים ע\"ז שם ע' תתקעב. תתקעג ואילך. וביהל אור לתהלים ע' שע-עא. [וראה גם אוה\"ת סידור ע' סא-ב. וע' שפג].\nעניני המאמר נמצאים בשינויים והוספות וכו' בד\"ה זה בסה\"מ תרנ\"ח ע' לט ואילך. ד\"ה קטנתי בסה\"מ תרע\"ח ע' פו ואילך. ד\"ה פדה בשלום בסה\"מ תרח\"צ ע' קסב ואילך. ד\"ה נתת ליראיך בסה\"מ תשי\"ב ע' 257 ואילך. ד\"ה פתח אלי' וד\"ה ברוך שעשה נסים תשט\"ו (סה\"מ מלוקט ח\"ה ע' קו ואילך. וע' קטו ואילך). ד\"ה מזמור לתודה תשי\"ז. ד\"ה דעו כי הוי' בסה\"מ תשל\"א. תשל\"ט. [וראה גם סה\"מ תרצ\"ט ע' 117].\nראה גם לקמן מאמר זה בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["2","2","<b>ר\"ת הלכה</b>: במאמר הצ\"צ הנ\"ל נוסף כאן: ובילקוט בתלים ע\"פ הריעו לה' כל הארץ אימתי לע\"ל כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד, וצ\"ל מהו. וכ\"ק אדמו\"ר מהר\"ש העביר ע\"ז הקולמוס. וכתב ע\"ז בגוכי\"ק בצידי הגליון: מחקתי כי לא מצאתי בילקוט, ואולי הכוונה על מ\"ש בילקוט במקומו רמז תתנ\"ד יודו בי אומות העולם ואני מקבלם (והיינו אומות הכופרים בי ח\"ו) שנא' בי נשבעתי יצא מפי צדקה כו' כי לי תכרע כל ברך וגו' (ישעי' מ\"ה כ\"ג). שוב עיינתי ברש\"י ע\"פ בי נשבעתי הנ\"ל שפי' ואני אקבלם כענין שנא' אז אהפוך אל עמים שפה ברורה (צפני' ג' ט\"ו), וא\"כ ודאי הכוונה כן הוא. ע\"כ. וראה גם ילקוט שמעוני ע\"פ הריעו לאלקים כל הארץ (תהלים סו, א): שיר מזמור הריעו לאלקים כל הארץ, אימתי לעתיד, וכן הוא אומר כי אז אהפוך אל עמים שפה ברורה."],["3","3","<b>ארז\"ל . . כל הקרבנות בטלים לע\"ל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650243\" data-slug=\"or-hatorah-hb\" data-id=\"8316650243\">אוה\"ת נ\"ך שם ע' תתקעב</a>, תתקפו. יהל אור שם ע' שסט, שעב."]]],[2002180065,"יבטל. ולהבין זה הנה אמרו רז\"ל (ברכות דנ\"ד ע\"ב) ד' צריכים להודות<sup data-n=\"4\">4</sup> יורדי הים והולכי מדברות וחולה שנתרפא כו', ופי' רש\"י כשיצאו מהסכנה, והיינו ע\"ש הנס שאירע להם, ומספר ד' הם כנגד ד' אותיות דש' הוי'<sup data-n=\"5\">5</sup> וכנגד ד' גאולות וד' לשונות של גאולה והוצאתי כו'. ובסידור האריז\"ל פי' מזמור לתודה או\"א דיצי'.\n<b>והענין</b> הוא, דהנה כתיב כי אל דעות הוי', שיש ב' דעות דעת עליון ודעת תחתון, וע\"פ הקבלה ד\"ע הוא בחי' יסוד אבא וד\"ת יסוד ז\"א. וביאור הענין בל' החסידות הנה ד\"ע הוא איך דכולא קמי' כלא חשיב וכל בחי' הנבראים הם אין ואפס כו' וכלא חשיב ממש, והוא ית' הוא בחי' יש האמיתי כו', וד\"ת הוא שהבריאה היא יש מאין כו'. כי יש בחי' השתלשלו' עו\"ע כמו שכל ומדות מח' ודבור, שהמדות כלולים תחלה בשכל ואח\"כ נולד המדה, וכמו\"כ מח' ודבור שמחשב במח' איך לדבר, הרי המדות היו תחלה בהעלם בשכל ואח\"כ יצאו מהעלם אל הגילוי להיות למדה בפ\"ע (וזהו שארז\"ל בר\"ה דף ך\"א ע\"ב חמשים שערי בינה<sup data-n=\"6\">6</sup> נבראו בעולם, פי' בינה היא אם הבנים<sup data-n=\"7\">7</sup>, בנים הם המדות, ובינה היא אם המולדת המדות הנק' בנים שיוצאים ונולדים ע\"י מ\"ט שערי בינה, שענין מספר חמשים שע\"ב, זהו שהמדות הם ז' מדות וכ\"א כלולה מז', ה\"ה מ\"ט, ולכל פרטי הז' מדות שבכל מדה יש שער מהבינה, שזהו בחי' ההטי' שבשכל להיות לידת והתגלות המדה בלב. ועד\"מ כשרוצה באיזה דבר פרטי, זהו מפני כי כבר התבונן בשכלו שטוב לפניו כך לכן רוצה בזה, ואם לא הי' מבין תחלה שהדבר שרוצה בו טוב לפניו הוא לא הי' רוצה בה כלל וכלל, ונמצא כי לידת והתגלות המדה שבלב זהו מהשכל שהולידה, היינו שהשכל המציא לו שטוב לפניו כך. וזהו הנק' שער שכמו השער משמש לצאת דרך בו, כך מה שיוצא ומתגלה מהשכל להיות בבחי' מדה שבלב זהו הנק' שער כו', ולהיות כי המדות הם מ\"ט לכן הם מ\"ט שע\"ב, ושער הנו\"ן הוא עצם הבינה כו'. ונמצא מובן איך שהמדות היו תחלה בהעלם בהשכל היינו בבחי' השערים הנ\"ל, הוא בחי' הטיית השכל להיות רוצה בדבר זה ונק' מדה שבשכל, ויציאתם מהעלם אל הגילוי בלב הוא להיות מדה שבלב בפועל בפ\"ע כו'). ועד\"ז הו\"ע גילוי הדבור מן המח' (שכל דבריו שמדבר היו תחלה בבחי' המחשבה, כשחשב בעצמו שצריך לדבר ענין הדבר שמדבר בו, וגם בעת שמדבר מצמצם מחשבתו לחשוב בדבר שמדבר בכדי שיהי' דבורו כראוי וכסדר שצריך כו', וה\"ז בחי' השתלשלות עו\"ע כו'). אבל יש בחי' יש מאין הוא שמאין נתהוה ליש ודבר נפרד.",[["4","4","<b>הנה ארז\"ל . . ד' צריכים להודות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650247\" data-slug=\"or-hatorah-hb\" data-id=\"8316650247\">אוה\"ת נ\"ך שם ס\"ע תתקעו</a> ואילך. בהבא לקמן ראה גם ד\"ה מזמור לתודה בס' מאמרי אדהאמ\"צ נ\"ך ע' קנב ואילך."],["5","5","<b>ד' צריכים להודות . . כנגד ד' אותיות דש' הוי'</b>: ראה גם יהל אור לתהלים ע' תיט. סה\"מ תשמ\"ו (הוצאת תשס\"ב) ע' 219. תשמ\"ח (הוצאת תשס\"ב) ע' 427."],["6","6","<b>שארז\"ל חמשים שערי בינה</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380351\" data-slug=\"likkutei-torah\" data-id=\"4001380351\">לקו\"ת במדבר י, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380663\" data-slug=\"likkutei-torah\" data-id=\"4001380663\">מטות פה, ב</a>. ובארוכה סה\"מ תרנ\"ח שם ע' לט. תרע\"ח שם ע' פו-ז. ותרח\"צ שם ע' קסג ואילך. וראה גם פיה\"מ לאדהאמ\"צ צט, א. סה\"מ מלוקט ח\"ה ס\"ע עה ואילך. וש\"נ. לעיל ח\"א ד\"ה הללוי' גו' מן השמים."],["7","7","<b>בינה היא אם הבנים</b>: ראה גם לעיל ח\"א ד\"ה החודש הזה. וש\"נ."]]],[2002180066,"<b>ועד\"ז</b> יובן ענין הבריאה שנק' יש מאין שלא יתכן לומר שהעולם הגשמי הי' בהעלם תחלה ברוחניות כ\"א בבחי' יש מאין כו', (וכמ\"ש החוקרים ובראשם הר\"ס גאון ז\"ל שבריאת העולם יש מאין ז\"ע דבר מלא דבר<sup data-n=\"8\">8</sup>, שמלא דבר נתהוה להיות בחי' דבר, שא\"א שבחי' דבר זה שנתהוה הי' תחלה בבחי' הלא דבר בבחי' העלם, שמאחר שהוא לא דבר א\"א להיות בו בחי' דבר כו'. וכן מובן גם בלשון יש מאין, שפי' אין הוא מה שאינו מושג כלל, ופי' יש הוא דבר המושג ונראה לנו, וא\"כ אינו שייך כלל לומר שבחי' השגה זו הי' תחלה בהעלם בבחי' האין שאינו מושג, מאחר שהוא למעלה מהשגה, א\"א לומר שהי' בו בחי' ההשגה שהוא היש, שא\"כ למה נק' אין. וא\"כ קריאת שם אין שפירושו שאינו מושג שולל ממנו לגמרי בחי' ההשגה שהוא היש שנתהוה מבחי' האין שיהי' בו בהעלם, ע\"ד עילה ועלול שיש בהעילה בחי' העלול בהעלם, משא\"כ היש בבחי' האין אינו בו כלל גם בהעלם, אלא שבחפץ ורצון הבורא נתהוה מבחי' אין בבחי' בריאה, (שהוא בלשון הפסוק דבר חדש מה שלא הי' תחלה, כמ\"ש ואם בריאה יברא ה' שפי' רש\"י ורבותינו פירשו אם בריאה פה לארץ מוטב ואם לאו יברא ה', בסנהדרין דק\"י סע\"א, וע' בפי' הרמב\"ן ז\"ל בחומש פ' קרח<sup data-n=\"9\">9</sup> ט\"ז למ\"ד בשם הר\"א ז\"ל שלשון בריאה הוא על המצא יש מאין), להיות בחי' מציאת היש כמ\"ש כל אשר חפץ ה' עשה, וז\"ע ד\"ת שהבריאה היא יש מאין כו').\n<b>ובאמת</b> ב' הדיעות הם אמת, שד\"ת הוא מצד בחי' ש' אלקים שאלקים בגימט' הטבע (וד\"ע הוא מבחי' ש' הוי', שלמעלה מש' אלקים שהוא בחי' הנהגת הטבע. ומ\"מ שניהם הם אמת, שגם ההנהגה שע\"י שם אלקים הוא אמת, שב' בחי' אלו הם יחו\"ע ויחו\"ת, ש' הוי' בחי' יחו\"ע, וש' אלקים הוא בחי' יחו\"ת, ושניהם הם כחות אלקות, יחו\"ת בשם אלקים המצמצם ומפריד להיות עלמא דפרודא בחי' יש כו' בכדי שיוכל להיות ע\"י עבודה בחי' ביטול היש לאין. וזהו שבסוף עשרה מאמרות שלא נז' בהם רק ש' אלקים כמ\"ש במ\"א<sup data-n=\"10\">10</sup> נרמז בתורה תיבת אמת, כי ס\"ת ברא אלקים לעשות הם אמת<sup data-n=\"11\">11</sup>, לרמז שדיעה זו דד\"ת שנמשכת מש' אלקים הוא ג\"כ אמת, רק שבבחי' אמת יש כמה בחי' אמת, שיש בחי' שפת אמת, ויש בחי' אמת עצמו, ויש בחי' אמת לאמיתו<sup data-n=\"12\">12</sup>.",[["8","8","<b>וכמ\"ש . . הר\"ס גאון ז\"ל שבריאת העולם . . ז\"ע דבר מלא דבר</b>: כן הובא בכ\"מ בדא\"ח (ראה סה\"מ תרכ\"ט ע' קנז. תרל\"ב ח\"א ע' ערב. ח\"ב ע' שמט. ועוד). ובהמשך מים רבים תרל\"ו ע' לו מעיר ע\"ז כ\"ק אדמו\"ר: בס' האמונות והדעות מ\"א: דבר לא מדבר. וכ\"ה במו\"נ ח\"ב רפי\"ג. ואולי גם כאן צ\"ל כן."],["9","9","<b>בריאה . . בלשון הפסוק דבר חדש . . וע' בפי' הרמב\"ן . . פ' קרח</b>: ראה גם פי' הרמב\"ן עה\"ת עה\"פ בראשית ברא (הובא בכ\"מ בדא\"ח ראה סה\"מ תרס\"ב ע' שנז. תרפ\"ו ע' כט. תרפ\"ח ע' קסט. ועוד), וז\"ל: אין אצלינו בלה\"ק בהוצאת היש מאין אלא לשון ברא."],["10","10","<b>עשרה מאמרות שלא נז' בהם רק ש' אלקים כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381257\" data-slug=\"likkutei-torah\" data-id=\"4001381257\">לקו\"ת שה\"ש לב, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560089\" data-slug=\"or-hatorah-hb\" data-id=\"8316560089\">אוה\"ת בראשית (כרך ג) תקיא, א</a>. סה\"מ תרל\"ג ח\"א ע' קד. תרל\"ד ע' קה ואילך. וס\"ע עדר ואילך. תרמ\"ז ע' נח ואילך. תרפ\"ד ע' קפט ואילך."],["11","11","<b>ס\"ת ברא אלקים לעשות הם אמת</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560089\" data-slug=\"or-hatorah-hb\" data-id=\"8316560089\">אוה\"ת בראשית (כרך ג) תקיא, א</a>. אוה\"ת נ\"ך (כרך ב) שם ע' תתקעז. סה\"מ תרל\"ה ח\"ב ע' רצ. עטר\"ת ע' תה. הש\"ת ע' 80."],["12","12","<b>יש כמה בחי' אמת . . שפת אמת . . אמת עצמו . . אמת לאמיתו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג (יט, א</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380248\" data-slug=\"likkutei-torah\" data-id=\"4001380248\">לקו\"ת בהר מ, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450686\" data-slug=\"or-hatorah-hb\" data-id=\"8316450686\">אוה\"ת ראה ע' תרפו</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600595\" data-slug=\"or-hatorah-hb\" data-id=\"8316600595\">נ\"ך ע' תקצה</a>. סה\"מ תרכ\"ז ע' שצט. תרכ\"ט ס\"ע שיד ואילך. תרל\"ו ח\"ב ע' שיט-כ."]]],[2002180067,"<b>וכמ\"ש</b> במ\"א בפי' תתן אמת ליעקב, שהוא מדת הת\"ת, והקשו שלכאורה אינו מובן וכי מדת החסד ומדת הגבורה אינם אמת ח\"ו<sup data-n=\"13\">13</sup>, ולמה נאמר תתן אמת ליעקב דוקא. אך הענין דודאי מדות חו\"ג הם ג\"כ אמת רק שאינם אמת לאמיתו, לפי שלמדת החסד יש מנגד בחי' מדת הגבורה, וכן לגבורה מנגד מדת החסד, ומאחר שיש לכ\"א מהם מנגד שלפי המנגדו צריך להיות בהיפך, אין זה אמת לאמתו, אבל מדתו של יעקב שהוא בחי' ת\"ת ונק' אמת לאמתו, לפי שלבחי' הת\"ת שהיא מדה\"ר אין לה מנגד כלל, שהרי הת\"ת סובל ב' המדות דחו\"ג יחדיו<sup data-n=\"14\">14</sup>, והיינו גם אם מדת הגבורה מנגד להשפעת הטוב והחסד שנשפע ע\"פ החסד בלי דקדוק כ\"כ, מפני שממדת הגבורה נמשך הדין והדקדוק לדקדק שע\"פ שורת הדין אינו מגיע לו כלל בחי' השפעת הטוב והחסד, הנה מדת הרחמים מכריע ונותן מקום למדת הגבורה לומר הן אמת שע\"פ הדין אינו מגיע לו, מ\"מ נצרך לרחם עליו, ובזה שע\"י הרחמים שירחמו עליו יומשך לו הטוב והחסד, אינו מנגד כלל למדת הגבורה, וא\"כ הרי מדת הת\"ת אין לה מנגד כלל, לפי שנותנת מקום לשני הבחי' דחסד וגבורה ולכן נק' אמת לאמיתו. ובמ\"א נת' פי' תתן אמת ליעקב שהקשו הלא יעקב עצמו הוא מדת האמת<sup data-n=\"15\">15</sup>, שהי' מרכבה למדת הת\"ת שנק' אמת כמ\"ש ע\"פ ונתתם לי אות אמת דא וא\"ו, שהוא מדת הת\"ת, ומהו תתן אמת ליעקב, אלא שזהו בחי' אמת לאמיתו כמ\"ש מזה במ\"א, ויש בחי' שפת אמת, שהוא ג\"כ אמת, ושרש בחי' אמת ית' לקמן אי\"ה בענין תיקון ואמת שפנוי משערות, וכל בחי' אמת שרשו מעתיקא קדישא כמ\"ש בלק\"ת בביאור אלה מסעי דרוש השלישי<sup data-n=\"16\">16</sup>, ושם פ\"דה. והיוצא מזה שיש כמה בחי' אמת, וא\"כ מובן איך שב' הדיעות דיחו\"ע ויח\"ת שניהם הם אמת, שגם ההנהגה דש' אלקים בגימ' הטבע הוא ג\"כ אמת ושרשו מבחי' אלקים דבינה, שנק' אלקים חיים ומלך עולם כו').\n<b>והנה</b> לשון טבע<sup data-n=\"17\">17</sup> יש בו מחלוקת בין המחקרי' שבתשו' ח\"צ נת' שלשון טבע<sup data-n=\"18\">18</sup> הוא מחודש והוא רק מערך ג' מאות שנה, דבאמת אינו שייך לומר טבע כלל כי הלא כתי' המכסה שמים בעבים המכין לארץ מטר המצמיח הרים חציר, ואינו שייך",[["13","13","<b>וכמ\"ש במ\"א בפי' תתן אמת ליעקב . . והקשו . . וכי מדת החסד . . הגבורה אינם אמת ח\"ו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">לקו\"ת מטות פג, סע\"ג</a>-ד. וראה גם דרמ\"צ קפ, סע\"א ואילך."],["14","14","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370045\" data-slug=\"torah-or\" data-id=\"3901370045\">שהרי הת\"ת סובל ב</a>' המדות דחו\"ג יחדיו</b>: ראה תו\"א נח יא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' שעא-ב. וע' שעה ואילך. ביאוה\"ז להצ\"צ ח\"א ס\"ע שיג ואילך. סה\"מ תרכ\"ז ע' תקא. וש\"נ."],["15","15","<b>ובמ\"א נת' פי' תתן אמת ליעקב שהקשו הלא יעקב עצמו הוא מדת האמת</b>: ראה אגה\"ק סי' ו (קט, ב ואילך). וראה גם סה\"מ תרל\"ד ע' רסא. וע' שס."],["16","16","<b>בלק\"ת בביאור אלה מסעי דרוש השלישי</b>: פ' מסעי דף צג, ב ואילך."],["17","17","<b>והנה לשון טבע יש בו מחלוקת בין המחברים</b>: בהבא לקמן ראה אוה\"ת נ\"ך (כרך ב) שם ע' תתקעז. שה\"ש (כרך א) ס\"ע שיד-טו. יהל אור לתהלים ע' קנד. סה\"מ תשי\"א [לכ\"ק אדמו\"ר מהוריי\"צ] ע' 290 ואילך. [ובהנסמן בהע' הבאה]."],["18","18","<b>שבתשו' ח\"צ נת' שלשון טבע</b>: הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380806\" data-slug=\"likkutei-torah\" data-id=\"4001380806\">לקו\"ת פ' ראה כב, ג</a>. וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010008\" data-slug=\"or-hatorah-hb\" data-id=\"8159010008\">אוה\"ת בראשית (כרך ז) תתשסא, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640314\" data-slug=\"or-hatorah-hb\" data-id=\"8316640314\">נ\"ך שם ע' תתקעז</a>. א'קיא. אוה\"ת שה\"ש (כרך א) שם ס\"ע שיד. סה\"מ תרע\"ח שם ס\"ע פח ואילך. תרח\"צ שם ע' קסז ואילך. סה\"מ מלוקט ח\"ה ע' קח ואילך."]]],[2002180068,"לקרות מה שצומח מן הארץ בשם טבע כלל, כ\"א הכל הוא מאתו ית' שהוא הנותן ומכין לארץ מטר כו', ונקראים בשם נסים תכופים<sup data-n=\"19\">19</sup> כו'. ושארי חכמי המחקר אומרים של' טבע הוא מלשון שארז\"ל בסנהדרין ספ\"ד משנה ה' שאדם טובע כמה מטבעות בחותם א' וכולם דומים זל\"ז, אבל הקב\"ה טבע כל אדם בחותמו של אדם הראשון ואין א' מהם דומה לחבירו. ונמצא כי ענין טבע הוא ענין הנהגת העולם, שבחי' בריאת העולמות הוא מאין ליש, וההנהגה שמנהיג את העולם נק' בשם טבע כו'.\n<b>ובזה</b> יובן המד\"ר<sup data-n=\"20\">20</sup> פ' בראשית ע\"פ ויכל אלקים ביום השביעי, הלא בששת ימים ברא הקב\"ה את עולמו, ולכן שינו לתלמי המלך וכתבו ביום הששי, ולמה נא' ויכל כו' ביום השביעי, ובמד\"ר תירצו על קושי' זו משל למלך שעשה לו טבעת מה הי' חסירה חותם בא שבת בא חותם. הרי כי בריאת העולם נק' בשם טבעת. והענין הוא דהנה נת' בסידור בד\"ה השמים מספרים<sup data-n=\"21\">21</sup> כבוד פי' השמים הם בחי' שמים עילאין מספרים מנהרין ומנצצין בחי' כבוד אל דנהיר לכל עזקא ועזקא, והוא מזהר פ' תרומה דקל\"ו ע\"ב, פי' עזקא הוא טבעת, והיינו כי בריאת העולם הוא בחי' טבעת דהיינו בחי' עיגולים, כי יש בחי' עיגולים ויושר, עיגולים הוא בחי' העלם, וכמשל הרב<sup data-n=\"22\">22</sup> כשאומר לתלמידו איזה דבר שכל הנה קודם שיבין התלמיד שכל וסברת הרב היטב הנה השכל מקיף את שכל התלמיד ועדיין הוא אצלו בבחי' העלם, רק אח\"כ כשמבין ומשכיל היטב שכל וסברת הרב אז הוא בחי' יושר. ועד\"ז יובן ענין בריאת העולמות שהוא בחי' עיגולים שנבראו עולמות והיכלות שהם מעלימים ומסתירים, וכנודע שעולם הוא לשון העלם<sup data-n=\"23\">23</sup> כו', ושבת הוא החותם, ולכן אומרים בשבת השמים מספרים שבחי' שמים עילאין מנהרין ומנצצין בחי' כבוד אל דנהיר לכל עזקא ועזקא שהם המאירים את בחי' הטבעת. ולכן נאמר ויכל אלקים ביום השביעי, דהן אמת שבששת ימים ברא הקב\"ה את עולמו אבל עדיין הי' בחי' טבעת בלא חותם, בא שבת בא חותם שהוא בחי' המאיר את העולם שנק' בשם טבעת, ואעפ\"כ איננה נקראת מלאכה שלא נתחדש דבר בשבת רק שהאיר כו' שהוא רק שיצא לידי גילוי מה שהי' בהעלם תחלה כו', (והיינו גילוי ש' הוי', דכתי' בי' יהללו את ש' הוי' כי הוא ציוה ונבראו, ולכאורה הלא כתיב בראשית ברא אלקים, ובכל מע\"ב לא נז' רק ש' אלקים, שהבריאה הי' ע\"י ש' אלקים. אך הענין הוא דבש' אלקים נא' ברא בחי' כח הפועל בנפעל, בחי' ממכ\"ע, שע\"ז אמרו מה הנשמה",[["19","19","<b>טבע . . ונקראים בשם נסים תכופים</b>: ראה גם סה\"מ מלוקט ח\"א ע' תעה שמביא תורת הבעש\"ט (כש\"ט סקי\"ט וסרנ\"ו): דענין הנס הוא שנתחדש הדבר בפעם הראשונה, וכשבא עוה\"פ ה\"ז נקרא טבע — היינו שבאמת הכל נס. עיי\"ש."],["20","20","<b>ובזה יובן המד\"ר . . ע\"פ ויכל אלקים . . משל למלך . . הי' חסירה חותם</b>: בהבא לקמן בפיסקא זו ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560089\" data-slug=\"or-hatorah-hb\" data-id=\"8316560089\">אוה\"ת בראשית (כרך ג) תקיא, א</a>. שם (כרך ז) תתשס, ב ואילך. תשא ע' א'תתקנו-ז. סה\"מ תרל\"ה ח\"ב ע' רצ. עטר\"ת ע' תד ואילך. הש\"ת ע' 80 ואילך."],["21","21","<b>בסידור בד\"ה השמים מספרים</b>: סידור עם דא\"ח קעח, סע\"ב ואילך. ובארוכה בפירוש המלות לאדהאמ\"צ ה, סע\"ב ואילך."],["22","22","<b>כי יש בחי' עיגולים ויושר . . וכמשל הרב</b>: בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380462\" data-slug=\"likkutei-torah\" data-id=\"4001380462\">לקו\"ת שלח לז, ג</a>. [ובהנסמן בהמ\"מ שם]. מאמרי אדה\"ז תקס\"ב ח\"א ע' מו ואילך. אוה\"ת תרומה ע' א'תסו ואילך. א'תסט ואילך. סה\"מ תרס\"ה ע' קמט ואילך. ועוד."],["23","23","<b>וכנודע שעולם הוא לשון העלם</b>: ראה גם לעיל ח\"א סד\"ה אז ישיר. וש\"נ."]]],[2002180069,"ממלא את הגוף כך הקב\"ה ממלא את העולם (במדת\"ל ע\"פ ברכי נפשי), אבל בש' הוי' נא' ונבראו מאיליו וממילא בלא התלבשות, כמ\"ש בלק\"ת שה\"ש בד\"ה קול דודי<sup data-n=\"24\">24</sup> ובמ\"א בד\"ה הללוי' הללו כו' מן השמים<sup data-n=\"25\">25</sup>, וזהו בחי' סוכ\"ע. והגם שעיקר החיות הוא מבחי' סוכ\"ע, עכ\"ז הוא בלתי התלבשות. והנה סוכ\"ע אין פירושו שסובב ומקיף לבד<sup data-n=\"26\">26</sup> כ\"א שאני מלא, ולית אתר פנוי מיני', ומ\"מ נק' סוכ\"ע לפי שזהו בהעלם, שאינו מושג וכמאמר מי שאמר והי' העולם, מי הוא בחי' שאינו מושג כלל. וזהו בכל שי\"ב, ולכן בכל שי\"ב לא נזכר ש' הוי', רק אחר שבת נאמר ביום עשות הוי' אלקים ארץ ושמים, והיינו לפי שבשבת מאיר שם הוי' כמ\"ש שבת להוי' אלקיך, ולכן בשבת מתגלה ש' הוי' מה שהי' בכל שי\"ב בבחי' העלם בחי' סוכ\"ע כו', שאין זה דבר חדש כ\"א גילוי ההעלם) ואעפ\"כ נא' ביום השביעי מפני כי שבת דוקא הוא החותם כו'. והנה נת' שהחותם הוא בחי' ש' הוי', כי הטבעת הוא בחי' ש' אלקים בגימ' הטבע, וזהו שטבעת הוא ל' טבע, והחותם הוא מבחי' ש' הוי' שהוא בחי' ד\"ע וכמ\"ש וארא כו' ושמי הוי' לא נודעתי להם, ופי' רש\"י ז\"ל לא ניכרתי להם במדת אמיתות שלי (אשר לכאורה אינו מובן וכי ח\"ו שם אל שדי ושארי שמות שאינם נמחקים אינם אמת ח\"ו, אלא שיש כמה מדרגות בבחי' אמת כנ\"ל, וש' הוי' נק' מדת אמיתות שלי, שש' הוי' הוא בחי' מדת האמת שהוא בחי' ד\"ע שזהו בחי' אמת לאמתו כו').\n<b>והנה</b> ענין הנס הוא בחי' הגילוי מלמעלה מן הטבע, כי נס הוא בחי' רוממות<sup data-n=\"27\">27</sup> מלשון ושים אותו על נס (בפ' חקת ך\"א פסוק ח'), והיינו כי ענין הנס הוא היפוך הטבע, ואפי' אם הנס מלובש בדרך הטבע הוא ג\"כ מבחי' שלמעלה מן הטבע, והיינו שהוא מבחי' ש' הוי', ולכן ד' צריכין להודות נגד ד' אותיות דש' הוי' רק שהוא מלובש בטבע כו'.\n<b>ועפ\"ז</b> יובן מ\"ש בסידור האריז\"ל דמזמור לתודה הוא או\"א דאצי', כי הנה נודע שבינה נק' יש כמ\"ש להנחיל אוהבי יש והחכמה נק' אין<sup data-n=\"28\">28</sup> כמ\"ש והחכמה מאין תמצא (ולכאורה צ\"ל מהו הראי' שהחכמה נק' אין, הרי נאמר רק שמאין תמצא<sup data-n=\"29\">29</sup>, אבל יש לומר שהחכמה עצמה נק' יש, אלא שהראי' הוא ממ\"ש תמצא, שענין המציאה מוכרח לומר שזהו הדבר הזה עצמו, ועד\"מ ראובן שמצא דבר שנאבד אצל שמעון, שמוכרח לומר שהדבר הזה עצמו שנאבד אצל שמעון הוא הדבר שמצא ראובן, דאל\"כ אין זה מציאה כלל, ועד\"ז יובן כשאומר שהחכמה תמצא בדרך מציאה מאין דכתר, א\"כ הרי החכמה היא ג\"כ אין שאל\"כ אינו שייך לומר לשון מציאה ע\"ז). והנה או\"א זיווגייהו תדיר לצורך קיום העולמות שהם יש מאין כו' (והיינו שחו\"ב הם שרש בחי'",[["24","24","<b>בלק\"ת שה\"ש בד\"ה קול דודי</b>: דף יד, ג ואילך."],["25","25","<b>ובמ\"א בד\"ה הללוי' הללו כו' מן השמים</b>: נדפס לעיל. וראה בהנסמן שם."],["26","26","<b>סוכ\"ע אין פירושו שסובב ומקיף לבד</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח (סז, ב</a>). ובכ\"מ."],["27","27","<b>נס הוא בחי' רוממות</b>: ראה גם לקמן בסיום מאמר זה: נס הוא לשון הרמה. וראה פירוש המלות לאדהאמ\"צ שם פקל\"ט. אוה\"ת בשלח ע' תרסה. שה\"ש ע' כט."],["28","28","<b>נודע שבינה נק' יש . . והחכמה נק' אין</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380065\" data-slug=\"likkutei-torah\" data-id=\"4001380065\">לקו\"ת פקודי ו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380221\" data-slug=\"likkutei-torah\" data-id=\"4001380221\">אמור לג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380399\" data-slug=\"likkutei-torah\" data-id=\"4001380399\">נשא כב, ד</a>. לעיל ח\"א ע' קעב. שכ. ובכ\"מ."],["29","29","<b>מהו הראי' . . הרי נאמר רק שמאין תמצא</b>: ראה בכ\"ז המשך וככה תרל\"ז פמ\"ז (ס\"ע סט ואילך). סה\"מ תרנ\"ח ס\"ע יז-ח. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380054\" data-slug=\"likkutei-torah\" data-id=\"4001380054\">לקו\"ת פקודי ג, סע\"ג</a>-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380376\" data-slug=\"likkutei-torah\" data-id=\"4001380376\">ד. במדבר יז, א</a>. ועוד."]]],[2002180070,"אין ויש, שהבינה נק' יש, לפי שבינה היא בחי' השגה כנודע, וענין השגה הוא בחי' מציאות יש כנ\"ל, וא\"כ מובן שבבינה אינו מושג בחי' האין דחכמה, ע\"ד שהיש שלמטה אינו משיג האין המהוה אותו, רק שזיווגייהו תדיר שז\"ע זיווג חיצוני דחו\"ב, שהיש דבינה בטל תמיד לבחי' האין דחכמה, ע\"ד בחי' ד\"ת דיחו\"ת, שהוא בחי' ביטול היש דבינה לאין דחכ', והאין דחכמה מהוה תמיד בחי' היש דבינה. אבל בחכמה עצמה הוא בהיפוך לפי שהחכמה הוא בחי' יחו\"ע בחי' ד\"ע שלמעלה היש האמיתי, ולמטה הוא אין, והיינו כי יש ב' פירושים בפי' אין, הא' אין שאינו מושג, הב' אין הארה בעלמא<sup data-n=\"30\">30</sup>, ובבינה שהיא שרש היש שם מושג ע\"ד ד\"ת, שהיש הוא בחי' השגה דבינה הוא מאין דחכ' פי' אין שאינו מושג, וזיווגייהו תדיר בבחי' זו, שהיש בטל תמיד לבחי' אין דחכמה והאין דחכמה מהוה היש דבינה. אבל בחכמה עצמה כאשר עדיין אין החכמה שופע בבינה היא בהיפך ממש, שחכמה הוא דעת עליון, שהחכמה שנמצא מאין דכתר שניהם הם בחי' יש האמיתי, ובחי' הארת החכמה שנמשך לבוא לידי השגה בבינה הוא אין, היינו שהוא בחי' הארה בעלמא לבד מבחי' עצם החכמה, ולכן נק' אין, והארה זו היא כלא ממש חשיב נגד בחי' היש האמיתי דחכמה, וכ\"ש בחי' ההשגה שבבינה שנמשך מהארה זו, וזהו בחי' דעת עליון בחי' יחו\"ע כו', ובחי' זו א\"א לבוא בנבראים בהשגה גמורה, מאחר שזהו למעלה מבחי' ההשגה דבינה ג\"כ כו'). וענין הנס הוא שיהי' יחוד אבא ואימא דהיינו שגם בבחי' בינה שהוא בחי' יש כמ\"ש להנחיל אוהבי יש, יאיר בחי' החכ' שהוא בחי' אין כמ\"ש והחכ' מאין תמצא כו' (וזהו ע\"ד מ\"ש בס\"י הבן בחכמה שבחי' בינה נכללת ומתייחדת בחכמה, וע\"ד שילוב ש' אד' בש' הוי' שנת' במ\"א<sup data-n=\"31\">31</sup> כו', והיינו ששרש בחי' הטבע נכללת בלמעלה מן הטבע, ומשם נמשך הנס כו', וזהו נס לשון הרמה שבחי' שרש הטבע מתרומם להתנהג בבחי' שלמעלה מהטבע.\n<b>ומפני</b> כי ענין הנס הוא מבחי' חכ' שהוא בחי' דעת עליון כו', בחי' ש' הוי' בחי' אמת כמ\"ש ואמת הוי' לעולם שיאיר גם בעולם בחי' אמת הוי'<sup data-n=\"32\">32</sup> שהוא בחי' חכ' כמ\"ש הוי' בחכ' (וגם בת\"ת מאיר ש' הוי' כו', מפני שכמו שהחכ' נק' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה, כן גם הת\"ת נק' אמת כמ\"ש ונתתם לי אות אמת ופי' בזח\"ג ר\"פ ויקרא דא אות וא\"ו שהוא ת\"ת<sup data-n=\"33\">33</sup>, מדתו של יעקב, וכנ\"ל בפי' תתן אמת ליעקב), לכן נא' ע\"ז מזמור לתודה שהגם שא\"א להשיג בחי' ד\"ע איך דכולא קמי' כלא חשיב, עכ\"פ צ\"ל בבחי' הודאה שמודה כו', וזהו ענין מזמור לתודה כו'.",[["30","30","<b>ב' פירושים בפי' אין . . שאינו מושג . . הארה בעלמא</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי</a> בהוספות (הוצאת תש\"ס) ע' 51. [ובהנסמן שם]. סה\"מ תרכ\"ז ע' שסו. ד\"ה מטה עוזך שבהמשך והחרים בסה\"מ תרל\"א ח\"א ע' חצר ואילך. [ובהנסמן שם בתחילת המאמר]. לקמן ד\"ה תקעו בחודש פ\"ו."],["31","31","<b>וע\"ד שילוב ש' אד' בש' הוי' שנת' במ\"א</b>: ראה בארוכה לקו\"ת דרושים לשבת שובה סה, ד. ועוד."],["32","32","<b>כמ\"ש ואמת הוי' לעולם שיאיר גם בעולם בחי' אמת הוי'</b>: ראה בכ\"ז לקו\"ת דרושים לשמע\"צ פג, סע\"א ואילך."],["33","33","<b>ונתתם לי את אמת ופי' בזח\"ג . . דא אות וא\"ו שהוא ת\"ת</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ה ח\"א ע' שסח ואילך. ביאוה\"ז לאדהאמ\"צ סב, ד ואילך. ולהצ\"צ ח\"א ע' שיג ואילך."]]],[2002180071,"<h3>[מזמור לתודה] ומעתה כו' הריעו לה' כל הארץ כו' (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ בהר בחוקותי, ט\"ל).</b>\n<b></b>או\"א דא\"ח כו' דעו כי כו' דעת ג' פי'\nבהב\"ח\n<b>ומעתה</b> יובן ענין הריעו לה' כל הארץ<sup data-n=\"34\">1</sup> ר\"ת הלכה, כי הנה ארז\"ל במדרש תלים ע\"פ מזוקק שבעתים לא ניתנו ד\"ת חתוכים למשה אלא במ\"ט פנים טהור ומ\"ט פנים טמא, והיינו כי מה שחזיר הוא טמא אינו ניתן במ\"ט פנים כ\"א זהו דבר ברור שהחזיר הוא טמא, ועד\"ז שארי דברים האסורים והטמאים, כי הם מגקה\"ט שלמטה מק\"נ שא\"א שיתעלה כלל, אבל שארי דברים שהם מבחי' ק\"נ זהו ניתן במ\"ט פנים טהור ומ\"ט פנים טמא, וז\"ע המחלוקת שזה מטהר שיכולים להעלותו ע\"י בירורים, וזה מטמא שסובר שא\"א להעלותו.\n<b>והנה</b> אמרו הלכה כדברי המכריע<sup data-n=\"35\">2</sup>, פי' שהלכה נמשך ממקום גבוה מאד שהוא המכריע שנותן מקום גם למדת הגבורה ומכריע ההלכה שיהי' ההילוך כך, וזהו בחי' יעקב שהוא בחי' ת\"ת, וזהו והנורא אל עליון שוא\"ו דוהנורא, הוא מבחי' אל עליון כו' כמ\"ש במ\"א<sup data-n=\"36\">3</sup> (שהוא למעלה מהשתלשלות, שבת\"ת מאיר אוא\"ס יותר וכנ\"ל, והיינו שהוא\"ו יש בראשו יו\"ד שהוא בחי' חכ', והחכ' מאין שלמעלה מהשתלשלות תמצא בדרך מציאה כנ\"ל, שבחי' הארת יו\"ד דחכמה נמשך בוא\"ו שהוא ת\"ת קו האמצעי, שלכן מכריע ומחבר ב' המדות חו\"ג, ונותן מקום גם למדת הגבורה כנ\"ל, ומפני שמחבר חו\"ג נק' אמת, הארת הכתר כמ\"ש בלק\"ת פ' ואתחנן בביאור ראשון שע\"פ וידעת<sup data-n=\"37\">4</sup> היום דרוש הראשון פ\"א (גם י\"ל ע\"ד המשל ופחד עמו עושה שלום בין חו\"ג כו' והיינו מפני שבת\"ת מאיר בחי' הגבוה יותר מחו\"ג כנ\"ל). וזהו מ\"ש בדוד וה' עמו שארז\"ל הלכה כמותו בכל מקום פי' כי ענין ההלכה נמשך מבחי' וה' עמו שהוא בחי' הארת הקו שמאיר בכתר וחכ' ומשם מאיר למל' (ודוד הי' כלי לקבל בחי' זו לפי שהי' בבחי' ביטול ושפלות שקרא ע\"ע בשם עני ואביון, וכן",[["34","1","<b>ומעתה יובן ענין הריעו לה' כל הארץ</b>: מאמר זה הוא המשך להמאמר שלפנ\"ז ד\"ה מזמור לתודה. [בהמאמר כאן לא נרשם התחלת המאמר, וראה לקמן בחלק ההנחות שגם התחלת מאמר זה הי' עה\"פ ”מזמור לתודה הריעו לה' כל הארץ\"].\nלכללות המאמר ראה בהנסמן שם בתחילת המאמר. לחלקו הראשון של המאמר (עד פיסקא: ונמצא כי ענין הלכה) ראה גם מאמרי אדה\"ז הקצרים ע' שכז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460078\" data-slug=\"or-hatorah-hb\" data-id=\"8316460078\">אוה\"ת</a> בראשית לב, א. יתרו ע' תתצג ואילך. משפטים ס\"ע א'קח-ט. סה\"מ תרכ\"ז ע' שא ואילך. שיד ואילך. המשך תרס\"ו ע' תכב-תמ. סה\"מ עת\"ר ס\"ע קיז ואילך. עטר\"ת ע' תמט ואילך. תרפ\"ח ע' קכט ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151245\" data-slug=\"likkutei-sichot\" data-id=\"1300151245\">לקו\"ש חט\"ו ע' 233</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211110\" data-slug=\"likkutei-sichot\" data-id=\"1300211110\">חכ\"א ע' 110</a> ואילך.\nראה גם לקמן מאמר זה בהנחת כ\"ק אדמו\"ר מוהרש\"ב נ\"ע."],["35","2","<b>והנה אמרו הלכה כדברי המכריע</b>: בהבא לקמן ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211111\" data-slug=\"likkutei-sichot\" data-id=\"1300211111\">לקו\"ש חכ\"א ע' 111</a> ואילך. ובמקומות שנסמנו בהערה שלפנ\"ז. [וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211029\" data-slug=\"likkutei-sichot\" data-id=\"1300211029\">לקו\"ש שם הע' 29</a>: ולהעיר מהענין דהלכה כדברי המכריע ע\"ד הנגלה — ראה אנציקלופדי' תלמודית בערכו (ע' שמו ואילך. וש\"נ) פלוגתת הראשונים באיזה אופנים אומרים כלל זה]."],["36","3","<b>שוא\"ו דוהנורא הוא מבחי' אל עליון כו' כמ\"ש במ\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370045\" data-slug=\"torah-or\" data-id=\"3901370045\">תו\"א נח יא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370278\" data-slug=\"torah-or\" data-id=\"3901370278\">בשלח סב, א</a>. לקו\"ת ואתחנן ח, סע\"א. וראה גם מאמרי אדה\"ז ענינים ע' נח. [ובהנסמן בהמ\"מ לשם]."],["37","4","<b>בלק\"ת פ' ואתחנן בביאור ראשון שע\"פ וידעת</b>: דף ה, א-ב."]]],[2002180072,"אמר ע\"ע והייתי שפל בעיני (בש\"ב סי' וא\"ו פסוק ך\"ב) וכתיב מרום וקדוש (שי\"ל על הארת הקו שמאיר בכתר וחכמה) אשכון ואת דכא ושפל רוח (ישעי' נ\"ז ט\"ו), וכמארז\"ל (עירובין די\"ג ע\"ב) שיצתה ב\"ק ואמרה אלו ואלו דא\"ח, והלכה כב\"ה שאמרו שם הטעם מפני שנוחין ועלובים היו, שלכאו' צ\"ל הלכה כב\"ש דמחדדי טפי, אלא מפני שנוחין ועלובין היו שהיו בבחי' הביטול זכו לכוון ההלכה, שיהי' מאיר בהם מבחי' וה' עמו הלכה כמותו כו').\n<b>ולהבין</b> ההפרש בין ענין המחלוקת שאלו ואלו דברי אלקים חיים ובין ענין ההלכה, מאחר שאלו ואלו דא\"ח הרי מה ששניהם אומרים הוא אמת וא\"כ מהו ענין ההלכה, שלכאורה פי' וענין ההלכה היינו שהאמת הוא כמו זה דוקא, וא\"כ הוא איך הוא האמת ג\"כ כמ\"ד השני שהרי הם ג\"כ דברי אלקים חיים. אך הענין הוא שענין ההלכה נמשך מבחי' הארת פנים, והנה תיקון ואמת שהוא הארת פנים פנוי משערות<sup data-n=\"38\">5</sup>, והיינו שבבחי' פנים מאיר בלתי צמצום השערות כמו שאנו רואים שכאשר יחדש האדם איזה סברא חדשה מתמלא תענוג מיד וניכר בפנים כמשארז\"ל על ר' אבוה צהבו פניו של ר' אבוה מפני שמצא תוספתא חדתא, והיינו מפני כי בפנים מאיר הארת התענוג בלתי צמצום השערות וזהו ענין ההלכה כו'. אבל ענין אלו ואלו דברי אלקים חיים הגם כי זהו ג\"כ אמת, אך זהו ע\"י צמצום השערות, והיינו כי במ\"ט פנים יש ג\"כ שער כמו סברא זו (וכנ\"ל שענין השערים הוא בחי' ההטי' בשכל להיות מדה זו, שזהו מבחי' מ\"ט שע\"ב כו', שנק' אלקים חיים, וגם בי\"ג מדות שהתורה נדרשת בהם שהם כנגד י\"ג ת\"ד, יש לסברא זו מקור בשערות דתיקוני דיקנא, שהם ג\"כ אמת, ומ\"מ אינו דומה לבחי' תיקון ואמת שפנוי משערות, ובו מתגלה אור החכמה סתימאה, כמו שחכמת אדם תאיר פניו, פניו דוקא כמ\"ש בלק\"ת בביאור אלה מסעי השלישי<sup data-n=\"39\">6</sup> פ\"גד, ולכן הגם כי גם סברא זו היא דברי אלקים חיים) אבל עיקר האמת היינו ההלכה אינו כן, כ\"א כמ\"ד הב' שכיוון להלכה בחי' הארת פנים כו' שפנוי משערות. וז\"ע הליכות עולם לו בחי' אמת הוי' לעולם.\n<b>ונמצא</b> כי ענין הלכה הוא ג\"כ מבחי' חכמה, לכן נאמר מזמור לתודה הריעו לה' כל הארץ ששייך ענין ההלכות לתודה כי שניהם הם מבחי' חכ' כו' (ומהאי טעמא ג\"כ הלכות אינם בטלים לע\"ל כמ\"ש בירושלמי פ\"ק דמגילה להיותם מבחי' חכמה ומבחי' ח\"ס (וי\"ל גם מה שלא נפסק להלכה כן ג\"כ לא יבטלו להיותם ג\"כ מח\"ס<sup data-n=\"40\">7</sup> רק שהם דרך צמצום השערות), לכן גם לע\"ל דכתיב ואמר ביום ההוא הנה אלקינו זה שמבחי' הוא בחי' עלמין סתימין יהי' בחי' זה בחי' גילוי, עכ\"ז לא יבטלו",[["38","5","<b>תיקון ואמת שהוא הארת פנים פנוי משערות</b>: ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380707\" data-slug=\"likkutei-torah\" data-id=\"4001380707\">צה, ד</a>. סה\"מ מלוקט ח\"א ע' צא ואילך."],["39","6","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת</a> בביאור אלה מסעי השלישי</b>: פ' מסעי שם צג, א ואילך. וראה גם לקמן ע' תנו."],["40","7","<b>(וי\"ל גם מה שלא נפסק להלכה ג\"כ לא יבטלו .ֿ. ג\"כ מח\"ס</b>: ראה עד\"ז בארוכה בלקולוי\"צ אגרות קודש ע' רסג ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141025\" data-slug=\"likkutei-sichot\" data-id=\"1300141025\">לקו\"ש חי\"ד ע' 25</a> (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410107\" data-slug=\"likkutei-sichot\" data-id=\"1301410107\">הע' 43</a>). ח\"ל ע' 12. חל\"ג ע' 118 (ובהע' 38). ועוד."]]],[2002180073,"ההלכות, שהם מבחי' סתימא דכל סתימין כמ\"ש בת\"א בד\"ה יביאו לבוש מל' ובהביאור הראשון<sup data-n=\"41\">8</sup>. ואינם דומים לנביאים שהם נו\"ה שיבטלו לע\"ל, שג\"כ אין הפי' שיבטלו לגמרי, אלא שנגד הגילוי שיהי' לע\"ל מבחי' הוא לא יעלו בשם ע\"ד שרגא בטיהרא כו'. אבל הלכות לא יבטלו ששרשם גבוה יותר מבחי' הוא סתים והיינו בחי' סתימא דכל סתימין, וה\"ה כמו שתודה לא תבטל, שההודאה בבחי' אוא\"ס עצמותו ומהותו שזה יהי' גם לע\"ל כו', ולכן נאמר תודה והלכה בפסוק אחד שיש להם השתוות זל\"ז).\n<b>ובזה</b> יובן משארז\"ל במשנה ריש פ\"ה דמנחות כל המנחות באות מצה חוץ מחמץ שבתודה ושתי הלחם שהם באות חמץ (הנה סתם קרבנות נק' ג\"כ בשם מנחה<sup data-n=\"42\">9</sup>, כמ\"ש והבל הביא גם הוא מבכורות צאנו ומחלביהן, וכתי' וישע ה' אל הבל ואל מנחתו, הרי שהי' בכורות צאנו נק' בשם מנחה, והגם שקרבן מנחה הי' קרבן בפ\"ע שהם מנחת סלת ומחבת כו', אך כל התורה היא כלל ופרט, ושרש) ענין המנחה בכלל הוא בחי' העלאת מ\"ן, ולכן מנחה ר\"ת מ\"ן ח' ה'<sup data-n=\"43\">10</sup>, מ\"ן הוא בחי' העלאת מ\"ן, וח' הוא בחי' מזל השמיני ונוצר ובחי' חכ', ובחי' ה' הוא בחי' מל', והיינו להמשיך ע\"י העלאת מ\"ן מבחי' מזל השמיני ובחי' חכמה במל'. ובזה יובן ענין המנחה ששלח יעקב לעשו עזים מאתים שלא כסדר הקרבנות דעכשיו, והיינו כי לע\"ל אהפוך אל עמים שפה ברורה, והיינו ע\"י העלאת מ\"ן ובירורים דתיקון יהי' בירור דתהו, ולע\"ל יהי' הגילוי. ולכן הריעו לה' כל הארץ לע\"ל כי אז אהפוך אל עמים שפה ברורה כו', ויעקב נגד חלקו בירר אותו לפי שעה ולכן ארז\"ל שבאותה שעה נכמרו רחמיו כו' ונשקו בכל לבו, כמו שפי' רש\"י והוא מהמד\"ר במקומו, ולכן הקריב המנחה שלו באופן אחר עזים מאתים שלא כסדר הקרבנות דתיקון כ\"א לפי קרבנות דתהו שיעקב ידע ענינם, וזהו ענין המנחה בד\"כ.\n<b>ומעתה</b> יובן ענין החמץ שבמנחת תודה ושתי הלחם, דהנה ההפרש בין חמץ למצה הוא בין ח' לה'<sup data-n=\"44\">11</sup>, שהה\"א יש לו פתח קטן בין גגו ובין רגל השמאלי, והיינו כי פיה פתחה בחכמה כו', כי חמץ הוא בחי' הגבהה והתנשאות בחי' גבורות, ומזה יכול להיות יניקה לחיצונים כי מבחי' נה\"י (והיינו רגל השמאל שבחי\"ת) יכול להיות יניקה לחיצונים, ובדרך פרט מנה\"י גופא הנה יניקתם הוא מקו השמאל (והיינו בחי' ספי' הוד שבנה\"י שיכול להיות נמשך יניקה לחיצונים, כי ההוד לא נתקן עדיין, שהנצח נתקן ע\"י שאמר שמואל לשאול וגם נצח ישראל לא ישקר ולא ינחם,",[["41","8","<b>בת\"א בד\"ה יביאו לבוש מל' ובהביאור הראשון</b>: דף צ, ד. צב, א."],["42","9","<b>סתם קרבנות נק' ג\"כ בשם מנחה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">תו\"א וישלח כה, רע\"ג</a>. סה\"מ תרכ\"ז ע' מט."],["43","10","<b>ושרש) ענין המנחה . . ר\"ת מ\"ן ח' ה'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370120\" data-slug=\"torah-or\" data-id=\"3901370120\">תו\"א וישלח שם כה, ד</a>. סה\"מ תרכ\"ז שם ע' נב. ועוד."],["44","11","<b>ההפרש בין חמץ למצה הוא בין ח' לה'</b>: בהבא לקמן ראה גם סה\"מ תרל\"ג ח\"א ע' קנו-ז. ובארוכה בד\"ה מזמור לתודה בסידור עם דא\"ח שם מה, א ואילך [ובשאר דרושים שנסמנו לעיל ברד\"ה מזמור לתודה]."]]],[2002180074,"אבל ההוד נשאר לא ניתקן עדיין כנודע<sup data-n=\"45\">12</sup>, ולכן יכול להיות יניקה לחמץ הוא היצה\"ר כמ\"ש מכף מעול וחומץ). וזהו שחמץ שהוא בחי' גבורות א\"א להתעלות בקרבנות. וענין הפתח התחתון של החי\"ת הוא בחי' לפתח חטאת רובץ, ולכן בשמות השבטים לא נמצאו אותיות ח\"ט כו'. אבל מצה היא בחי' ביטול ושפלות, וז\"ע פתח קטן שהוא פיה פתחה בחכמה כו', ומצד בחי' החכ' לא נמצא יניקה כו' כי ימותו ולא בחכמה כו'. אבל התודה ושתי הלחם היו באות חמץ, והיינו מפני כי תודה הוא בחי' חכ' כנ\"ל, ושתי הלחם הם בחי' תושב\"כ ותושבע\"פ, שאורייתא מח\"ע נפקת לכן מצד שהם עצמם בחי' חכ' יכולים גם חמץ להקריב לפי שבחכ' לא הי' שבה\"כ כי ימותו ולא בחכ' כנ\"ל, ואף גם זאת הוא רק אכילה לכהנים ולא ע\"ג המזבח<sup data-n=\"46\">13</sup> ודוקא אכילה לכהנים כו'.\n<b>(ולהבין</b> ענין מעלת אכילת כהנים, הנה בענין הנדרים שהם בבינה נת' בד\"ה וידבר משה אל ראשי המטות<sup data-n=\"47\">14</sup>, שענין הנדר שדוחה גם ההיתר בשמאל דוחה, מפני שמשער בעצמו שלא יוכל להעלותו, לכן פורש א\"ע ממנו, משא\"כ החכם מתיר הנדר, והיינו מפני כי החכם הוא שמקבל מבחי' חכמה, ולכן הוא מתיר הדבר שמק\"נ שהדיח אותו בנדר שיתברר ויתעלה, כי בחכמה אתברירו ויוכל לברר ולהעלות ק\"נ. וזהו ההפרש בין אתכפי' ובין אתהפכא, שהנדר הוא ע\"ד אתכפיא, ות\"ח שמתיר הנדר זהו ע\"ד בחי' אתהפכא מחשכא לנהורא. ודוגמא לזה מצינו שארז\"ל ע\"ה אסור לאכול בשר<sup data-n=\"48\">15</sup>, והיינו מפני שהבשר שהוא מותרות שהרי יכול לחיות גם כשלא יאכל בשר, הנה תאות הבשר מורידו ומפיל אותו, היינו שמגשמו יותר, משא\"כ ת\"ח שמקבל מחכמה הנה מצינו שארז\"ל עד דלא אכילנא בישרא דתורא<sup data-n=\"49\">16</sup> לא צלילנא דעתאי, שהבשר הוסיף בו צלילות הדעת, והיא ג\"כ מטעם הנ\"ל",[["45","12","<b>שהנצח נתקן ע\"י שאמר . . וגם נצח ישראל . . אבל ההוד . . לא נתקן עדיין כנודע</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ה ח\"א ע' תיט ואילך. דרך מצותיך יב, א ואילך. ד\"ה זכור גו' עמלק בסה\"מ תרל\"א. וש\"נ."],["46","13","<b>ואף גם זאת הוא רק אכילה לכהנים ולא ע\"ג המזבח</b>: ראה אוה\"ת נ\"ך (כרך ב) שם ע' תתקפה: ומ\"מ לא הי' קרב ע\"ג המזבח כ\"א נתרם מהם תרומה לכהן, ועמ\"ש ע\"פ אך אל הפרוכת כו' דבעלי מומין חולקין ואוכלין אבל לא מקריבין, וכך עד\"ז ענין החמץ אפי' בשתי הלחם ובתודה נאכל הוא לכהנים אבל אינו קרב ע\"ג המזבח. ובשולי הגליון דמאמר האוה\"ת שם נרשם הגה\"ה בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש, וז\"ל: ולפי מ\"ש בלק\"ת פ' צו בד\"ה ואכלתם אכול ובהביאור מעלת אכילת כהנים שעי\"ז הוא אכילת אדם שלמעלה גם מארי' דאכיל קרבנין כמו שהי' בבית ראשון, לפי\"ז אולי י\"ל שחמץ שבתודה ושתי הלחם דוקא הכהנים יכולים לבררו ולהעלות, אבל לא באש שלמעלה דארי' דאכיל קרבנין, ואולי גם שבעלי מומין אוכלין אין סתירה לזה, שהגם שהוא בעל מום עכ\"ז הוא אדם שע\"י אכילתו מתעורר למעלה בחי' אכילת אדם שלמעלה מאכילת מזבח."],["47","14","<b>נת' בד\"ה וידבר . . ראשי המטות</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380651\" data-slug=\"likkutei-torah\" data-id=\"4001380651\">לקו\"ת מטות פב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380655\" data-slug=\"likkutei-torah\" data-id=\"4001380655\">פג, סע\"ב</a>. סה\"מ תר\"ל ע' רטז ואילך. וע' רכג ואילך. לקמן ד\"ה וידבר גו' המטות."],["48","15","<b>שארז\"ל ע\"ה אסור לאכול בשר</b>: ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380436\" data-slug=\"likkutei-torah\" data-id=\"4001380436\">לקו\"ת בהעלותך לא, ג</a> ואילך. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקנג ואילך. מאמרי אדהאמ\"צ במדבר ח\"ג ע' תתצד ואילך. תתקיד ואילך. סה\"מ תרל\"ב ח\"ב ע' תיג. וש\"נ. וע' תכ."],["49","16","<b>שארז\"ל עד דלא אכילנא בישרא דתורא</b>: הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז (יא, ב</a>)."]]],[2002180075,"שבחכמה אתברירו, וכשמברר הבשר כשאוכלו לש\"ש שז\"ע לשובע נפשו, הבשר מוסיף בו צלילות הדעת, מפני שהבשר שהוא מבחי' חי הוא בשרשו גבוה יותר מבחי' האדם שהוא מדבר, כמ\"ש מזה בלק\"ת פ' מטות בדרושי הנדרים, ושם בביאור ע\"פ וידבר כו' ראשי המטות<sup data-n=\"50\">17</sup> פ\"ב. וכן עד\"ז בענין הכבוד הנה ארז\"ל במשנה ך\"א פ\"ד דאבות, הקנאה והתאוה והכבוד מוציאין את האדם מן העולם, ובכהנים נהפוך הוא דכתיב ועשית בגדי קדש לאהרן אחיך לכבוד ולתפארת<sup data-n=\"51\">18</sup>, והיינו מפני שאהרן הוא בחי' חכמה, ואהרן אותיות נראה שהיא בחי' ראי' דחכ' בחי' כח מ\"ה ביטול, וכמו שא' משה ונחנו מה שאמר זה גם על אהרן, ופעם אמר ואהרן מה הוא, שהי' בבחי' מ\"ה לכן יכול לברר היש של הכבוד, וכמ\"ש כבוד חכמים ינחלו. ועד\"ז יובן בענין אכילת כהנים דוקא החמץ שבתודה, שלהיות הכהנים הם מקו הימין חח\"ן מימין שהם כה\"ג חכמה, סגן חסד, כהן הדיוט נצח<sup data-n=\"52\">19</sup>, הם דוקא יכולים לאכול החמץ שבתודה להיותם מבחי' חכ', לכן יכולים לברר ולהעלות גם היש של הק\"נ דחמץ ג\"כ כו'. וע' בלק\"ת פ' צו בד\"ה ואכלתם אכול<sup data-n=\"53\">20</sup> פ\"ב בענין אכילת אדם ואכילת מזבח שאכילה זהו מ\"ה המברר ב\"ן, ואכילת מזבח ז\"ע ארי' דאכיל קרבנין (בזח\"א דף וא\"ו ע\"ב) אך הוא בחיצוניות העולמות אשה ריח ניחוח בבי\"ע, אבל בחי' אדם דכליל כולא אינו אוכל אלא באכילת אדם התחתון, והיינו אכילת כהנים שנק' אכילת אדם, שכהנים אוכלים ובעלים מתכפרים. ולפ\"ז י\"ל שדוקא כהנים יכולים לברר החמץ שבמנחות, ומ\"מ דוקא ע\"ד אכילת כהנים יכול להתעלות גם היש דחמץ, אבל לא על המזבח כי כל שאור כו' לא תקטירו, וע' בבחיי פ' ויקרא עפ\"ז שהשאור והדבש הן הן היצה\"ר עצמו. והנה) כמו שבתודה ושתי הלחם הי' חמץ והיינו שגם חמץ יוכל להתעלות, עד\"ז הו\"ע נר חנוכה משמאל והיינו מצד כי נר חנוכה הוא גבוה מאד לכן יכול להתעלות גם שמאל<sup data-n=\"54\">21</sup> כו' בחי' הגבורות כו'.\n<b>עבדו</b> את הוי' בשמחה<sup data-n=\"55\">22</sup> הוא בחי' בינה, שהבינה היא בחי' שמחה כמ\"ש אם הבנים שמחה, כי בחכ' אינו שייך עדיין בחי' שמחה (כ\"א בחי' ענג<sup data-n=\"56\">23</sup>, וכמ\"ש וקראת לשבת ענג, שבת הוא בחי' מוחין דאבא בחי' חכ' מצותו לקרות בו בחי' ענג ולא",[["50","17","<b>בלק\"ת פ' מטות בדרושי הנדרים ושם בביאור ע\"פ וידבר כו' ראשי המטות</b>: דף פב, ד."],["51","18","<b>ארז\"ל . . הקנאה והתאוה והכבוד . . ובכהנים נהפוך הוא . . לכבוד ולתפארת</b>: ראה בכ\"ז אוה\"ת תצוה (כרך ז) ע' ב'תשנב-ג. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380194\" data-slug=\"likkutei-torah\" data-id=\"4001380194\">לקו\"ת אחרי כז, ג</a>. אוה\"ת בא ע' רמו."],["52","19","<b>הכהנים . . חח\"ן מימין . . כה\"ג חכמה סגן חסד כהן הדיוט נצח</b>: ראה ביאוה\"ז לאדהאמ\"צ קלג, א. ולהצ\"צ ח\"א ע' קיד. ח\"ב ע' תרפא. תרפח. תרצג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670037\" data-slug=\"or-hatorah-hb\" data-id=\"8158670037\">אוה\"ת ויצא קפח, א</a>. וראה המובא ע\"ז באוה\"ת בראשית (כרך ב) תסא, ב."],["53","20","<b>בלק\"ת פ' צו בד\"ה ואכלתם אכול</b>: דף ז, ב."],["54","21","<b>עד\"ז הו\"ע נר חנוכה משמאל . . להתעלות גם שמאל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, סע\"ג</a>-ד. אוה\"ת חנוכה רפג, ב ואילך. שכו, ב. ובארוכה ס' תורת שמואל דרושי חתונה ע' מב. וס\"ע מה ואילך. וש\"נ."],["55","22","<b>עבדו את הוי' בשמחה</b>: בהבא לקמן בפיסקא זו ראה ד\"ה מזמור לתודה בסידור עם דא\"ח שם מה, סע\"ג-ד. פירוש המלות לאדהאמ\"צ צח, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650258\" data-slug=\"or-hatorah-hb\" data-id=\"8316650258\">אוה\"ת נ\"ך (כרך ב) שם ע' תתקפז</a>."],["56","23","<b>שהבינה היא בחי' שמחה . . בחכ' . . בחי' ענג</b>: ראה סה\"מ תרל\"ה ח\"ב ע' תכד. ובארוכה סה\"מ תרנ\"ז ע' קעג ואילך. תרס\"ח ע' קסב ואילך. תש\"ט ע' 130 ואילך."]]]]});
